-- Endocrine System question bank: exactly 650 hand-written NCLEX-style
-- single-best-answer questions, 50 per note. Every answer is grounded in
-- (and its rationale limited to) the source note listed for its topic:
--   Notes/Endocrine System/Thyroid-Gland-and-Hormones.html
--   Notes/Endocrine System/Parathyroid-Disorders.html
--   Notes/Endocrine System/Endocrine-Medications.html
--   Notes/Endocrine System/Adrenal-Gland-AD-and-CD.html
--   Notes/Endocrine System/Thyroid-Gland.html
--   Notes/Endocrine System/Insulin.html
--   Notes/Endocrine System/Diabetes-Mellitus.html
--   Notes/Endocrine System/Metformin.html
--   Notes/Endocrine System/DKA-and-HHNS.html
--   Notes/Endocrine System/Diabetes-Insipidus-and-SIADH.html
--   Notes/Endocrine System/Insulin-Patch.html
--   Notes/Endocrine System/Insulin-Storage-and-Checking.html
--   Notes/Endocrine System/Mixing-of-Insulin-Guidelines.html
--
-- Maps each source path through note_catalog.note_id to the published test_topics
-- row(s) for that note (matching test.html's note-level topic grouping). All
-- missing/ambiguous mappings are reported before any deletion or insertion.
-- Safe to rerun: only rows carrying this script's category labels are replaced,
-- and the transaction aborts unless exactly 50 rows per topic (650) exist after insert.
BEGIN;

CREATE TEMP TABLE _endo_sources (
  source_key text PRIMARY KEY,
  source_path text NOT NULL UNIQUE,
  category text NOT NULL UNIQUE
) ON COMMIT DROP;

INSERT INTO _endo_sources (source_key, source_path, category) VALUES
  ('thyroid_hormones', 'Notes/Endocrine System/Thyroid-Gland-and-Hormones.html', 'Endocrine System NCLEX seed v1 - thyroid hormones'),
  ('parathyroid', 'Notes/Endocrine System/Parathyroid-Disorders.html', 'Endocrine System NCLEX seed v1 - parathyroid'),
  ('medications', 'Notes/Endocrine System/Endocrine-Medications.html', 'Endocrine System NCLEX seed v1 - medications'),
  ('adrenal', 'Notes/Endocrine System/Adrenal-Gland-AD-and-CD.html', 'Endocrine System NCLEX seed v1 - adrenal'),
  ('thyroid_structure', 'Notes/Endocrine System/Thyroid-Gland.html', 'Endocrine System NCLEX seed v1 - thyroid structure'),
  ('insulin', 'Notes/Endocrine System/Insulin.html', 'Endocrine System NCLEX seed v1 - insulin'),
  ('diabetes', 'Notes/Endocrine System/Diabetes-Mellitus.html', 'Endocrine System NCLEX seed v1 - diabetes mellitus'),
  ('metformin', 'Notes/Endocrine System/Metformin.html', 'Endocrine System NCLEX seed v1 - metformin'),
  ('dka_hhns', 'Notes/Endocrine System/DKA-and-HHNS.html', 'Endocrine System NCLEX seed v1 - DKA and HHNS'),
  ('di_siadh', 'Notes/Endocrine System/Diabetes-Insipidus-and-SIADH.html', 'Endocrine System NCLEX seed v1 - DI and SIADH'),
  ('patch', 'Notes/Endocrine System/Insulin-Patch.html', 'Endocrine System NCLEX seed v1 - insulin patch'),
  ('storage', 'Notes/Endocrine System/Insulin-Storage-and-Checking.html', 'Endocrine System NCLEX seed v1 - insulin storage'),
  ('mixing', 'Notes/Endocrine System/Mixing-of-Insulin-Guidelines.html', 'Endocrine System NCLEX seed v1 - insulin mixing');

CREATE TEMP TABLE _endo_seed_map (
  source_key text PRIMARY KEY,
  source_path text NOT NULL,
  category text NOT NULL,
  note_id uuid NOT NULL,
  note_title text NOT NULL,
  topic_id uuid NOT NULL,
  topic_aliases text[] NOT NULL
) ON COMMIT DROP;

CREATE TEMP TABLE _endo_seed_config (test_id bigint NOT NULL) ON COMMIT DROP;

DO $$
DECLARE
  v_subject_id uuid;
  v_subject_count integer;
  v_note_count integer;
  v_topic_count integer;
  v_note_id uuid;
  v_note_title text;
  v_topic_id uuid;
  v_aliases text[];
  v_test_id bigint;
  v_errors text[] := ARRAY[]::text[];
  r record;
BEGIN
  SELECT count(*)
    INTO v_subject_count
    FROM test_subjects
   WHERE lower(btrim(name)) = 'endocrine system'
     AND is_active = true;
  IF v_subject_count <> 1 THEN
    v_errors := array_append(v_errors,
      format('Expected exactly one active test_subjects row named "Endocrine System"; found %s.', v_subject_count));
  ELSE
    SELECT id INTO v_subject_id
      FROM test_subjects
     WHERE lower(btrim(name)) = 'endocrine system'
       AND is_active = true;
  END IF;

  SELECT id INTO v_test_id
    FROM tests
   WHERE is_active = true
   ORDER BY id
   LIMIT 1;
  IF v_test_id IS NULL THEN
    v_errors := array_append(v_errors, 'No active tests row is available for test_questions.test_id.');
  END IF;

  FOR r IN SELECT source_key, source_path, category FROM _endo_sources ORDER BY source_key LOOP
    SELECT count(*)
      INTO v_note_count
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_note_count = 0 THEN
      v_errors := array_append(v_errors,
        format('Missing active note_catalog mapping for %s.', r.source_path));
      CONTINUE;
    ELSIF v_note_count > 1 THEN
      v_errors := array_append(v_errors,
        format('Ambiguous active note_catalog mapping for %s (%s rows).', r.source_path, v_note_count));
      CONTINUE;
    END IF;

    SELECT note_id, title
      INTO v_note_id, v_note_title
      FROM note_catalog
     WHERE path = r.source_path
       AND is_active = true;

    IF v_subject_count <> 1 THEN
      v_errors := array_append(v_errors,
        format('Cannot resolve test_topics aliases for %s because the active Endocrine System subject mapping is not unique.',
               r.source_path));
      CONTINUE;
    END IF;

    SELECT count(*)
      INTO v_topic_count
      FROM test_topics
     WHERE subject_id = v_subject_id
       AND note_id = v_note_id
       AND (status = 'published' OR status IS NULL);

    IF v_topic_count = 0 THEN
      v_errors := array_append(v_errors,
        format('No published test_topics row in Endocrine System points to note %s (%s).',
               v_note_title, r.source_path));
      CONTINUE;
    END IF;

    -- Sibling topics are expected aliases in test.html's note-level merged row.
    -- Insert all 50 for this source under one deterministic sibling topic_id.
    SELECT t.id
      INTO v_topic_id
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL)
     ORDER BY t.display_order NULLS LAST, t.created_at, t.name, t.id
     LIMIT 1;

    -- Collect the actual underlying aliases for the mapping check/report context.
    SELECT array_agg(t.name ORDER BY t.display_order NULLS LAST, t.name, t.id)
      INTO v_aliases
      FROM test_topics t
     WHERE t.subject_id = v_subject_id
       AND t.note_id = v_note_id
       AND (t.status = 'published' OR t.status IS NULL);

    INSERT INTO _endo_seed_map
      (source_key, source_path, category, note_id, note_title, topic_id, topic_aliases)
    VALUES
      (r.source_key, r.source_path, r.category, v_note_id, v_note_title, v_topic_id, v_aliases);
  END LOOP;

  IF cardinality(v_errors) > 0 THEN
    RAISE EXCEPTION E'Endocrine seed mapping validation failed before any deletion/insertion:\n - %',
      array_to_string(v_errors, E'\n - ');
  END IF;

  IF (SELECT count(*) FROM _endo_seed_map) <> 13 THEN
    RAISE EXCEPTION 'Internal mapping check failed: expected 13 note mappings, found %.',
      (SELECT count(*) FROM _endo_seed_map);
  END IF;

  INSERT INTO _endo_seed_config (test_id) VALUES (v_test_id);
END $$;

-- Only rows from this script's unique category names are replaced.
DELETE FROM test_questions q
 USING _endo_seed_map m
 WHERE q.category = m.category;

INSERT INTO test_questions
  (test_id, topic_id, question, question_stem, options, correct_answer, rationale,
   category, is_multiple_choice, display_order, points, is_active)
SELECT c.test_id, m.topic_id, v.stem, v.stem, v.options, v.correct_answer, v.rationale,
       m.category, false, v.display_order, 1, true
  FROM (VALUES
  ('thyroid_hormones', 1, 'A nurse is preparing to palpate the thyroid gland of a client during a physical assessment. Where should the nurse expect to find the gland?', '[{"id": "a", "text": "Back of the neck, behind the trachea and above the shoulder blades"}, {"id": "b", "text": "Front of the neck, below the Adam''s apple and above the chest bone"}, {"id": "c", "text": "Front of the neck, above the Adam''s apple and just below the jaw"}, {"id": "d", "text": "Upper chest, below the top of the chest bone and over the heart"}]'::jsonb, '["b"]', 'The thyroid is a butterfly-shaped gland in the front of the neck, located below the Adam''s apple and above the top of the chest bone. It is not above the Adam''s apple near the jaw.'),
  ('thyroid_hormones', 2, 'A client newly diagnosed with a thyroid disorder asks what the thyroid gland needs in order to make its hormones. Which response by the nurse is accurate?', '[{"id": "a", "text": "Calcium and thyroglobulin"}, {"id": "b", "text": "Iodine and cholesterol"}, {"id": "c", "text": "Iodine and thyroglobulin"}, {"id": "d", "text": "Iron and thyroid peroxidase"}]'::jsonb, '["c"]', 'The thyroid needs two main things to make hormones: iodine and thyroglobulin. Calcium and iron are not hormone building blocks; they actually reduce levothyroxine absorption.'),
  ('thyroid_hormones', 3, 'A client asks the nurse how the thyroid gets the iodine it uses to make hormones. Which response is accurate?', '[{"id": "a", "text": "Iodine is made inside the thyroid from the protein thyroglobulin."}, {"id": "b", "text": "Iodine comes from foods such as iodized salt, eggs, and seafood."}, {"id": "c", "text": "Iodine is released by the anterior pituitary along with TSH."}, {"id": "d", "text": "Iodine is produced in the colloid and then stored in the follicles."}]'::jsonb, '["b"]', 'Iodine is obtained from dietary sources such as iodized salt, eggs, and seafood, and then enters thyroid cells. The thyroid does not make iodine from thyroglobulin; iodine attaches to thyroglobulin.'),
  ('thyroid_hormones', 4, 'A nursing student is reviewing thyroid anatomy before caring for a client with a goiter. Which structure is the site where thyroid hormones are made and stored?', '[{"id": "a", "text": "The cells surrounding the follicles"}, {"id": "b", "text": "The trachea the gland surrounds"}, {"id": "c", "text": "The colloid inside the follicles"}, {"id": "d", "text": "The anterior pituitary gland"}]'::jsonb, '["c"]', 'Inside the follicles is a thick fluid called colloid, where thyroid hormones are made and stored. The cells around the follicles make thyroglobulin rather than storing the finished hormone.'),
  ('thyroid_hormones', 5, 'Which substance produced by the cells surrounding the thyroid follicles serves as the protein used to build thyroid hormones?', '[{"id": "a", "text": "Thyroglobulin"}, {"id": "b", "text": "Thyroid peroxidase"}, {"id": "c", "text": "Thyrotropin-releasing hormone"}, {"id": "d", "text": "Thyroid-stimulating hormone"}]'::jsonb, '["a"]', 'The cells around the follicles make thyroglobulin, the protein used to make thyroid hormones. Thyroid peroxidase is the enzyme that attaches iodine to thyroglobulin, not the protein itself.'),
  ('thyroid_hormones', 6, 'A client with Hashimoto''s disease asks how iodine becomes attached to thyroglobulin inside the thyroid follicles. Which substance should the nurse identify?', '[{"id": "a", "text": "Thyroid-stimulating hormone"}, {"id": "b", "text": "Thyrotropin-releasing hormone"}, {"id": "c", "text": "Levothyroxine"}, {"id": "d", "text": "Thyroid peroxidase"}]'::jsonb, '["d"]', 'The enzyme thyroid peroxidase helps attach iodine to thyroglobulin inside the follicles. TSH tells the thyroid to make hormone but is not the enzyme that attaches iodine.'),
  ('thyroid_hormones', 7, 'Which combination correctly describes how triiodothyronine (T3) is formed in the thyroid follicle?', '[{"id": "a", "text": "MIT + DIT, giving 3 iodine atoms"}, {"id": "b", "text": "DIT + DIT, giving 4 iodine atoms"}, {"id": "c", "text": "MIT + MIT, giving 2 iodine atoms"}, {"id": "d", "text": "DIT + DIT, giving 3 iodine atoms"}]'::jsonb, '["a"]', 'T3 is formed from MIT plus DIT, for a total of 3 iodine atoms. DIT plus DIT forms T4, which has 4 iodine atoms.'),
  ('thyroid_hormones', 8, 'A client taking levothyroxine asks what the difference is between T4 and T3. Which response by the nurse is accurate?', '[{"id": "a", "text": "T4 is the stronger hormone that does most of the work in cells."}, {"id": "b", "text": "T4 is a less active storage form that the body converts to T3."}, {"id": "c", "text": "T3 is a storage form that the body converts to T4 when needed."}, {"id": "d", "text": "T3 and T4 are equally active and do not convert to each other."}]'::jsonb, '["b"]', 'T4 is less active and works mostly as a storage form, and the body converts T4 to T3 when it needs more active hormone. T3, not T4, is the stronger hormone that does most of the work.'),
  ('thyroid_hormones', 9, 'A client with hypothyroidism asks how the brain controls the thyroid gland. Which sequence should the nurse describe?', '[{"id": "a", "text": "Pituitary releases TRH, hypothalamus releases TSH, thyroid releases T3/T4"}, {"id": "b", "text": "Thyroid releases TSH, pituitary releases TRH, hypothalamus releases T3/T4"}, {"id": "c", "text": "Hypothalamus releases TRH, pituitary releases TSH, thyroid releases T3/T4"}, {"id": "d", "text": "Hypothalamus releases TSH, pituitary releases TRH, thyroid releases T3/T4"}]'::jsonb, '["c"]', 'The hypothalamus releases TRH, which tells the pituitary to release TSH, which tells the thyroid to release T3 and T4. TRH comes from the hypothalamus, not the pituitary.'),
  ('thyroid_hormones', 10, 'A client reports fatigue, cold intolerance, and weight gain. Laboratory results show an elevated TSH and a low T4. How should the nurse interpret these results?', '[{"id": "a", "text": "Secondary hypothyroidism; the pituitary is the problem"}, {"id": "b", "text": "Hyperthyroidism; the thyroid is making excess hormone"}, {"id": "c", "text": "Primary hypothyroidism; the thyroid is the problem"}, {"id": "d", "text": "Normal feedback; no thyroid problem is present"}]'::jsonb, '["c"]', 'In primary hypothyroidism T4 is low and TSH is high because the thyroid is the problem and the pituitary keeps sending more TSH. In secondary hypothyroidism both T4 and TSH are low.'),
  ('thyroid_hormones', 11, 'A client being evaluated for fatigue and cold intolerance has a low T4 and a low TSH. The nurse recognizes that this pattern most likely indicates which problem?', '[{"id": "a", "text": "The thyroid is failing despite high pituitary stimulation."}, {"id": "b", "text": "Autoimmune antibodies are stimulating the thyroid gland."}, {"id": "c", "text": "High T4 levels are suppressing the release of TSH."}, {"id": "d", "text": "The pituitary is not sending enough TSH to the thyroid."}]'::jsonb, '["d"]', 'When both T4 and TSH are low, the pituitary is the problem and is not sending enough TSH to the thyroid (secondary hypothyroidism). A failing thyroid with high pituitary stimulation would show a high TSH.'),
  ('thyroid_hormones', 12, 'A client with suspected Graves'' disease has thyroid function tests drawn. Which laboratory pattern should the nurse expect?', '[{"id": "a", "text": "T3/T4 decreased, TSH elevated"}, {"id": "b", "text": "T3/T4 decreased, TSH decreased"}, {"id": "c", "text": "T3/T4 elevated, TSH elevated"}, {"id": "d", "text": "T3/T4 elevated, TSH decreased"}]'::jsonb, '["d"]', 'Graves'' disease is hyperthyroidism, in which T3/T4 are high and TSH is low. Low T3/T4 with high TSH is the pattern of hypothyroidism.'),
  ('thyroid_hormones', 13, 'A client with hyperthyroidism asks why the TSH level is low when the thyroid is overactive. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "High T3 and T4 signal the pituitary to release more TSH."}, {"id": "b", "text": "Low TRH from the hypothalamus causes T3 and T4 to rise."}, {"id": "c", "text": "High T3 and T4 signal the brain to lower TRH and TSH."}, {"id": "d", "text": "The thyroid converts excess TSH directly into T3 and T4."}]'::jsonb, '["c"]', 'Through negative feedback, high T3/T4 stops TRH and TSH release, so TSH falls. High T3/T4 does not stimulate more TSH; low T3/T4 is what stimulates TRH and TSH.'),
  ('thyroid_hormones', 14, 'A client with primary hypothyroidism asks why the TSH level is high when the thyroid is underactive. Which response by the nurse is accurate?', '[{"id": "a", "text": "The pituitary keeps sending more TSH to try to fix low hormone."}, {"id": "b", "text": "High thyroid hormone levels are stimulating the pituitary gland."}, {"id": "c", "text": "The pituitary is damaged and is not sending enough TSH out."}, {"id": "d", "text": "The thyroid is releasing TSH because T3 and T4 production stopped."}]'::jsonb, '["a"]', 'In primary hypothyroidism the thyroid is the problem, and the pituitary keeps sending more TSH trying to fix it. A pituitary that is not sending enough TSH describes secondary hypothyroidism, in which TSH is low.'),
  ('thyroid_hormones', 15, 'A nurse is teaching a group of clients about the effects of T3 on the body. Which statement by the nurse is accurate?', '[{"id": "a", "text": "T3 helps the liver clear cholesterol from the blood."}, {"id": "b", "text": "T3 lowers the heart rate and cardiac output."}, {"id": "c", "text": "T3 decreases oxygen consumption and fat burning."}, {"id": "d", "text": "T3 slows bone remodeling and bone growth."}]'::jsonb, '["a"]', 'T3''s role in the liver is to clear cholesterol from the blood. T3 increases, rather than lowers, heart rate and cardiac output.'),
  ('thyroid_hormones', 16, 'A client in the first trimester of pregnancy who has hypothyroidism asks why adequate thyroid hormone matters for the baby. Which response by the nurse is accurate?', '[{"id": "a", "text": "Thyroid hormone slows your metabolism to save energy for the baby."}, {"id": "b", "text": "Thyroid hormone is only needed by the baby after it is born."}, {"id": "c", "text": "Thyroid hormone lowers your heart rate to protect the baby."}, {"id": "d", "text": "Thyroid hormone is critical for the baby''s brain development."}]'::jsonb, '["d"]', 'T3 supports brain function and is critical for fetal brain development. T3 increases energy use rather than slowing metabolism.'),
  ('thyroid_hormones', 17, 'A client with hyperthyroidism asks why they keep losing weight despite eating well. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Excess T3 decreases oxygen use and slows fat burning."}, {"id": "b", "text": "Excess T3 increases energy use, fat burning, and oxygen use."}, {"id": "c", "text": "Low T3 levels cause the body to burn energy too fast."}, {"id": "d", "text": "Excess TSH blocks the absorption of nutrients from food."}]'::jsonb, '["b"]', 'T3 increases energy use, fat burning, and oxygen consumption, so in hyperthyroidism the body burns energy too fast and weight is lost. Low T3 causes hypometabolism and weight gain, not weight loss.'),
  ('thyroid_hormones', 18, 'A nurse is assessing a client with Graves'' disease. Which finding should the nurse expect?', '[{"id": "a", "text": "Exophthalmos"}, {"id": "b", "text": "Periorbital edema"}, {"id": "c", "text": "Bradycardia"}, {"id": "d", "text": "Constipation"}]'::jsonb, '["a"]', 'Exophthalmos (bulging eyes) is a finding of hyperthyroidism (Graves'' disease). Periorbital edema, bradycardia, and constipation are findings of hypothyroidism (Hashimoto''s).'),
  ('thyroid_hormones', 19, 'A nurse is assessing a client with Hashimoto''s thyroiditis. Which findings are most consistent with this condition?', '[{"id": "a", "text": "Heat intolerance and diaphoresis"}, {"id": "b", "text": "Cold intolerance and dry skin"}, {"id": "c", "text": "Insomnia and hyperactivity"}, {"id": "d", "text": "Diarrhea and weight loss"}]'::jsonb, '["b"]', 'Hashimoto''s causes hypothyroidism, with cold intolerance, fatigue, and dry skin. Heat intolerance and diaphoresis are findings of hyperthyroidism.'),
  ('thyroid_hormones', 20, 'A nurse reviews the vital signs of a client with untreated hyperthyroidism. Which findings should the nurse expect?', '[{"id": "a", "text": "Bradycardia and low blood pressure"}, {"id": "b", "text": "Bradycardia and elevated blood pressure"}, {"id": "c", "text": "Tachycardia and low blood pressure"}, {"id": "d", "text": "Tachycardia and elevated blood pressure"}]'::jsonb, '["d"]', 'Hyperthyroidism causes increased BP, increased HR (tachycardia), and increased cardiac output. Low BP and bradycardia are findings of hypothyroidism.'),
  ('thyroid_hormones', 21, 'Which client statement is most consistent with a diagnosis of hypothyroidism?', '[{"id": "a", "text": "\"I''ve had diarrhea and keep losing weight.\""}, {"id": "b", "text": "\"I can''t sleep at night and feel very hyper.\""}, {"id": "c", "text": "\"I sweat all the time and always feel hot.\""}, {"id": "d", "text": "\"I''ve been constipated and keep gaining weight.\""}]'::jsonb, '["d"]', 'Hypothyroidism causes hypometabolism with weight gain and constipation. Diarrhea, weight loss, insomnia, sweating, and feeling hot are findings of hyperthyroidism.'),
  ('thyroid_hormones', 22, 'An older client reports fatigue, sleepiness, weight gain, and a low mood and is being evaluated for depression. The nurse recognizes that these symptoms may also be caused by which condition?', '[{"id": "a", "text": "Graves'' hyperthyroidism"}, {"id": "b", "text": "Hashimoto''s hypothyroidism"}, {"id": "c", "text": "Thyroid storm"}, {"id": "d", "text": "Postoperative hypocalcemia"}]'::jsonb, '["b"]', 'Hypothyroidism (Hashimoto''s) causes fatigue, lethargy, sleepiness, and weight gain, and its symptoms may mimic depression. Graves'' disease causes hyperactivity and weight loss instead.'),
  ('thyroid_hormones', 23, 'A client newly diagnosed with Graves'' disease asks what causes the condition. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "The immune system attacks the thyroid so it makes too little hormone."}, {"id": "b", "text": "The pituitary fails to send TSH, so the thyroid makes extra hormone."}, {"id": "c", "text": "A lack of iodine in the diet causes the thyroid to overproduce hormone."}, {"id": "d", "text": "Autoimmune antibodies stimulate the thyroid to make excess T3/T4."}]'::jsonb, '["d"]', 'In Graves'' disease, autoimmune antibodies stimulate the thyroid, causing excess T3/T4. An immune attack that leaves insufficient hormone describes Hashimoto''s.'),
  ('thyroid_hormones', 24, 'A nurse teaches a client about Hashimoto''s thyroiditis. Which statement by the client indicates understanding?', '[{"id": "a", "text": "\"My immune system attacks my thyroid, so I make too little hormone.\""}, {"id": "b", "text": "\"Antibodies stimulate my thyroid, so I make too much hormone.\""}, {"id": "c", "text": "\"My pituitary sends too little TSH, so my thyroid overworks.\""}, {"id": "d", "text": "\"My thyroid stores too much T3, so my metabolism speeds up.\""}]'::jsonb, '["a"]', 'Hashimoto''s is autoimmune: the immune system attacks the thyroid, resulting in insufficient hormone. Antibodies that stimulate the thyroid to make excess hormone describe Graves'' disease.'),
  ('thyroid_hormones', 25, 'A client with Graves'' disease is prescribed a beta-blocker and asks why it is needed. Which response by the nurse is accurate?', '[{"id": "a", "text": "It destroys the overactive thyroid tissue causing the symptoms."}, {"id": "b", "text": "It replaces thyroid hormone that the gland is unable to produce."}, {"id": "c", "text": "It is the preferred antithyroid drug during early pregnancy."}, {"id": "d", "text": "It controls symptoms such as a fast heart rate, tremors, and anxiety."}]'::jsonb, '["d"]', 'Beta-blockers are used in hyperthyroidism to control symptoms like tachycardia, tremors, and anxiety. Destroying overactive thyroid tissue is the action of radioactive iodine.'),
  ('thyroid_hormones', 26, 'A client who is 9 weeks pregnant is diagnosed with hyperthyroidism. Which medication should the nurse anticipate the provider will prescribe?', '[{"id": "a", "text": "Methimazole"}, {"id": "b", "text": "Propylthiouracil (PTU)"}, {"id": "c", "text": "Radioactive iodine"}, {"id": "d", "text": "Levothyroxine"}]'::jsonb, '["b"]', 'PTU is preferred in the first trimester of pregnancy. Methimazole should be avoided in the first trimester, and radioactive iodine is not for pregnancy.'),
  ('thyroid_hormones', 27, 'A 34-year-old nonpregnant client is newly diagnosed with Graves'' disease and will begin antithyroid therapy. Which medication is preferred for this client?', '[{"id": "a", "text": "Propylthiouracil (PTU)"}, {"id": "b", "text": "Levothyroxine"}, {"id": "c", "text": "Methimazole"}, {"id": "d", "text": "Hydrocortisone"}]'::jsonb, '["c"]', 'Methimazole is the preferred antithyroid medication for most nonpregnant patients. PTU is reserved as the preferred drug in first-trimester pregnancy and thyroid storm.'),
  ('thyroid_hormones', 28, 'A provider is considering propylthiouracil (PTU) for routine treatment of hyperthyroidism in a 10-year-old child. The nurse recognizes that PTU is generally avoided in children because of which risk?', '[{"id": "a", "text": "Liver toxicity"}, {"id": "b", "text": "Hypocalcemia"}, {"id": "c", "text": "Hyponatremia"}, {"id": "d", "text": "Hypoglycemia"}]'::jsonb, '["a"]', 'Routine PTU use should be avoided in children due to liver toxicity. Hypocalcemia is a post-thyroidectomy complication, not the reason PTU is avoided.'),
  ('thyroid_hormones', 29, 'The nurse reviews orders for several clients with hyperthyroidism. For which client should the nurse question an order for radioactive iodine (RAI)?', '[{"id": "a", "text": "A client who is 60 years old and retired"}, {"id": "b", "text": "A client who has a goiter and exophthalmos"}, {"id": "c", "text": "A client who takes a beta-blocker daily"}, {"id": "d", "text": "A client who is breastfeeding an infant"}]'::jsonb, '["d"]', 'Radioactive iodine destroys overactive thyroid tissue and is not for pregnancy or breastfeeding. Goiter and exophthalmos are expected Graves'' findings and do not contraindicate RAI.'),
  ('thyroid_hormones', 30, 'A nurse provides discharge teaching to a client who received radioactive iodine (RAI). Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "\"I will flush the toilet twice after I use it.\""}, {"id": "b", "text": "\"I can hold my sister''s newborn baby a lot this week.\""}, {"id": "c", "text": "\"I will limit close contact with pregnant people.\""}, {"id": "d", "text": "\"I will keep my distance from young children for now.\""}]'::jsonb, '["b"]', 'After RAI, the client should flush the toilet twice and limit close contact with children and pregnant people, so holding a newborn often needs correction. Flushing twice is correct teaching.'),
  ('thyroid_hormones', 31, 'A client returns to the unit after a thyroidectomy. In which position should the nurse place the client?', '[{"id": "a", "text": "Supine and flat"}, {"id": "b", "text": "Prone"}, {"id": "c", "text": "Semi-Fowler''s"}, {"id": "d", "text": "Trendelenburg"}]'::jsonb, '["c"]', 'After thyroidectomy the client should be positioned semi-Fowler''s. A flat or head-down position is not the recommended post-op position.'),
  ('thyroid_hormones', 32, 'Twelve hours after a thyroidectomy, a client has a positive Chvostek''s sign and Trousseau''s sign. The nurse suspects which complication?', '[{"id": "a", "text": "Laryngeal damage from vocal cord injury"}, {"id": "b", "text": "Hypocalcemia from parathyroid gland removal"}, {"id": "c", "text": "Airway obstruction from neck swelling"}, {"id": "d", "text": "Thyroid storm from excess T3 and T4"}]'::jsonb, '["b"]', 'Hypocalcemia can occur after thyroid surgery if the parathyroid glands are accidentally removed; the nurse looks for Trousseau''s and Chvostek''s signs. Laryngeal damage presents as hoarseness or voice loss instead.'),
  ('thyroid_hormones', 33, 'On the first day after a thyroidectomy, a client''s voice is hoarse and weak. Which complication does this finding suggest?', '[{"id": "a", "text": "Hypocalcemia"}, {"id": "b", "text": "Myxedema coma"}, {"id": "c", "text": "Thyroid storm"}, {"id": "d", "text": "Laryngeal damage"}]'::jsonb, '["d"]', 'Hoarseness or voice loss after thyroid surgery suggests laryngeal damage, and vocal cord function should be assessed. Hypocalcemia is identified by Trousseau''s and Chvostek''s signs.'),
  ('thyroid_hormones', 34, 'A client who had a thyroidectomy 4 hours ago has rapidly increasing neck swelling and is struggling to breathe. Which action should the nurse take first?', '[{"id": "a", "text": "Check for Chvostek''s and Trousseau''s signs."}, {"id": "b", "text": "Ask the client to speak to assess for hoarseness."}, {"id": "c", "text": "Notify the provider and prepare for intubation."}, {"id": "d", "text": "Lower the head of the bed to a flat position."}]'::jsonb, '["c"]', 'A swollen neck after thyroid surgery signals airway obstruction, so the nurse should notify the provider and prepare for intubation. Checking for hypocalcemia signs does not address the threatened airway.'),
  ('thyroid_hormones', 35, 'A nurse is planning care for a client who just returned from a thyroidectomy. Which group of assessments is the priority?', '[{"id": "a", "text": "Blood glucose, sodium, temperature, and LOC"}, {"id": "b", "text": "Heart rate, fever, diarrhea, and agitation"}, {"id": "c", "text": "Airway, bleeding, calcium level, and voice"}, {"id": "d", "text": "Weight, bowel pattern, skin, and mood"}]'::jsonb, '["c"]', 'After thyroidectomy the nurse monitors airway, bleeding, calcium, and voice. Fever, tachycardia, diarrhea, and agitation are signs of thyroid storm rather than the routine post-op focus.'),
  ('thyroid_hormones', 36, 'A nurse teaches a client how to take newly prescribed levothyroxine. Which instruction is accurate?', '[{"id": "a", "text": "Take it in the morning on an empty stomach, 30–60 minutes before food."}, {"id": "b", "text": "Take it with breakfast along with a calcium supplement each day."}, {"id": "c", "text": "Take it at bedtime with a light snack to prevent stomach upset."}, {"id": "d", "text": "Take it with an antacid in the morning to protect the stomach."}]'::jsonb, '["a"]', 'Levothyroxine should be taken in the morning on an empty stomach, 30–60 minutes before food. Calcium and antacids reduce its absorption and should be separated from it.'),
  ('thyroid_hormones', 37, 'A nurse is reinforcing teaching with a client who takes levothyroxine. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will take my levothyroxine together with my iron pill.\""}, {"id": "b", "text": "\"I will take my levothyroxine at the same time every day.\""}, {"id": "c", "text": "\"I will not stop taking my levothyroxine suddenly.\""}, {"id": "d", "text": "\"I will tell my provider if my heart starts racing.\""}]'::jsonb, '["a"]', 'Iron, calcium, and antacids reduce levothyroxine absorption, so the drug should be separated from the iron pill. Taking it at the same time every day is correct.'),
  ('thyroid_hormones', 38, 'A client taking levothyroxine reports palpitations, trouble sleeping, and feeling hot all the time. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Reassure the client that these effects are expected."}, {"id": "b", "text": "Notify the provider about possible excess medication."}, {"id": "c", "text": "Instruct the client to stop the medication right away."}, {"id": "d", "text": "Advise taking the dose with calcium to slow absorption."}]'::jsonb, '["b"]', 'Too much levothyroxine can cause tachycardia, palpitations, insomnia, and heat intolerance, and the provider should be notified. The drug should not be stopped abruptly.'),
  ('thyroid_hormones', 39, 'Two weeks after starting levothyroxine, a client says, "I don''t feel any better, so I want to stop taking it." Which response by the nurse is best?', '[{"id": "a", "text": "\"It should work within a day, so it is fine to stop it now.\""}, {"id": "b", "text": "\"Stop it for one week, and then restart it at a higher dose.\""}, {"id": "c", "text": "\"The full effect takes about 6 weeks, so keep taking it daily.\""}, {"id": "d", "text": "\"Take a double dose each morning until you start to feel better.\""}]'::jsonb, '["c"]', 'The full effect and dose adjustment of levothyroxine take about 6 weeks, and the drug should not be stopped abruptly. Doubling the dose risks excess-medication effects such as tachycardia and insomnia.'),
  ('thyroid_hormones', 40, 'A client with primary hypothyroidism has been taking levothyroxine for 6 weeks. Which laboratory change indicates that treatment is effective?', '[{"id": "a", "text": "TSH is rising as T4 falls."}, {"id": "b", "text": "TSH and T4 are both falling."}, {"id": "c", "text": "TSH is rising and T4 is unchanged."}, {"id": "d", "text": "TSH is decreasing as T4 rises."}]'::jsonb, '["d"]', 'Primary hypothyroidism shows low T4 with high TSH; as replacement raises thyroid hormone, negative feedback lowers TSH. Rising TSH with falling T4 is the pattern of untreated hypothyroidism.'),
  ('thyroid_hormones', 41, 'A client with Graves'' disease who has an infection develops a very high fever, a very fast heart rate, high blood pressure, diarrhea, and confusion. The nurse recognizes these findings as which condition?', '[{"id": "a", "text": "Myxedema coma"}, {"id": "b", "text": "Postoperative hypocalcemia"}, {"id": "c", "text": "Thyroid storm"}, {"id": "d", "text": "Secondary hypothyroidism"}]'::jsonb, '["c"]', 'In thyroid storm everything speeds up: very high fever, tachycardia, hypertension, agitation or confusion, and diarrhea. Myxedema coma is the opposite, with hypothermia, bradycardia, and hypotension.'),
  ('thyroid_hormones', 42, 'A client in thyroid storm has prescriptions for propylthiouracil (PTU) and Lugol''s solution. How should the nurse administer these medications?', '[{"id": "a", "text": "Give the Lugol''s solution first, then give the PTU."}, {"id": "b", "text": "Give the PTU first, then give the Lugol''s solution."}, {"id": "c", "text": "Give the PTU and Lugol''s solution at the same time."}, {"id": "d", "text": "Hold the PTU and give only the Lugol''s solution."}]'::jsonb, '["b"]', 'Iodine is given after the antithyroid medication; if iodine is given first, the gland grabs it to make even more T3/T4 and worsens the crisis. Giving Lugol''s solution first is therefore unsafe.'),
  ('thyroid_hormones', 43, 'A client in thyroid storm has a very high fever. Which prescription should the nurse question?', '[{"id": "a", "text": "Aspirin for fever"}, {"id": "b", "text": "Acetaminophen for fever"}, {"id": "c", "text": "Propranolol"}, {"id": "d", "text": "Dexamethasone"}]'::jsonb, '["a"]', 'Aspirin should be avoided in thyroid storm because it knocks T3/T4 off carrier proteins and worsens the crisis; cooling and acetaminophen are used instead. Propranolol and dexamethasone are part of thyroid storm treatment.'),
  ('thyroid_hormones', 44, 'A nurse is preparing to care for a client admitted with thyroid storm. Which interventions should the nurse anticipate?', '[{"id": "a", "text": "Warming measures and IV levothyroxine"}, {"id": "b", "text": "Aspirin to reduce the fever quickly"}, {"id": "c", "text": "Cooling measures and IV fluids"}, {"id": "d", "text": "Iodine given before the antithyroid drug"}]'::jsonb, '["c"]', 'Thyroid storm treatment includes a beta-blocker, antithyroid medication, iodine, IV fluids, cooling, and glucocorticoids. Warming and IV levothyroxine are treatments for myxedema coma.'),
  ('thyroid_hormones', 45, 'A client with hypothyroidism is found with a temperature of 33°C (91.4°F), heart rate of 40/min, blood pressure of 70/50 mm Hg, respiratory rate of 8/min, and stupor. The nurse recognizes these findings as which condition?', '[{"id": "a", "text": "Myxedema coma"}, {"id": "b", "text": "Thyroid storm"}, {"id": "c", "text": "Postoperative hypocalcemia"}, {"id": "d", "text": "Graves'' disease"}]'::jsonb, '["a"]', 'Myxedema coma is a severe hypothyroidism emergency in which everything slows down: hypothermia, bradycardia, hypotension, hypoventilation, and decreased mental status. Thyroid storm is the opposite, with fever and tachycardia.'),
  ('thyroid_hormones', 46, 'A client with hypothyroidism is admitted in myxedema coma. Which factor in the client''s history most likely triggered the crisis?', '[{"id": "a", "text": "Stopped taking levothyroxine two weeks ago"}, {"id": "b", "text": "Takes levothyroxine 30 minutes before breakfast"}, {"id": "c", "text": "Takes iron supplements only in the evening"}, {"id": "d", "text": "Takes levothyroxine at the same time each day"}]'::jsonb, '["a"]', 'Missed thyroid medication is a trigger for myxedema coma, along with infection, cold exposure, trauma, surgery, and sedatives. Taking levothyroxine before breakfast at the same time daily is correct use, not a trigger.'),
  ('thyroid_hormones', 47, 'A nurse reviews the laboratory results of a client in myxedema coma. Which findings should the nurse expect?', '[{"id": "a", "text": "High blood glucose and high sodium"}, {"id": "b", "text": "Low blood glucose and high sodium"}, {"id": "c", "text": "High blood glucose and low sodium"}, {"id": "d", "text": "Low blood glucose and low sodium"}]'::jsonb, '["d"]', 'Hypoglycemia and hyponatremia may occur in myxedema coma, as with a glucose of 55 mg/dL and sodium of 125 mEq/L. Elevated glucose or sodium is not the expected pattern.'),
  ('thyroid_hormones', 48, 'A client is admitted with myxedema coma. Which medications should the nurse anticipate administering?', '[{"id": "a", "text": "Propylthiouracil and Lugol''s solution"}, {"id": "b", "text": "IV levothyroxine and IV hydrocortisone"}, {"id": "c", "text": "Propranolol and acetaminophen"}, {"id": "d", "text": "Methimazole and radioactive iodine"}]'::jsonb, '["b"]', 'Myxedema coma is treated with IV levothyroxine, IV hydrocortisone, warming, and airway/oxygen support. PTU and Lugol''s solution are used for thyroid storm.'),
  ('thyroid_hormones', 49, 'A client in myxedema coma has a respiratory rate of 8/min and is minimally responsive. Which intervention should the nurse implement first?', '[{"id": "a", "text": "Provide airway and oxygen support."}, {"id": "b", "text": "Apply a cooling blanket to the client."}, {"id": "c", "text": "Give a sedative to keep the client calm."}, {"id": "d", "text": "Administer propylthiouracil (PTU)."}]'::jsonb, '["a"]', 'Myxedema coma causes hypoventilation and decreased LOC, and treatment includes airway/oxygen support along with warming. Cooling is used for thyroid storm, and sedatives are a trigger for myxedema coma.'),
  ('thyroid_hormones', 50, 'A nurse is caring for several clients. Which client is at greatest risk for developing myxedema coma?', '[{"id": "a", "text": "A client with Graves'' disease who has a fever and diarrhea"}, {"id": "b", "text": "A client with hypothyroidism who has an infection and got sedatives"}, {"id": "c", "text": "A client who takes levothyroxine every morning before food"}, {"id": "d", "text": "A client who is taking methimazole for hyperthyroidism"}]'::jsonb, '["b"]', 'Myxedema coma is a severe hypothyroidism emergency triggered by infection, sedatives, cold exposure, trauma, surgery, or missed thyroid meds. A client with Graves'' disease and fever is at risk for thyroid storm instead.'),
  ('parathyroid', 1, 'A client who had a thyroidectomy 12 hours ago reports numbness and tingling around the mouth and in the fingertips. The nurse suspects which complication?', '[{"id": "a", "text": "Hypocalcemia from parathyroid gland damage"}, {"id": "b", "text": "Hypercalcemia from increased vitamin D activation"}, {"id": "c", "text": "Hypercalcemia from excess parathyroid hormone"}, {"id": "d", "text": "Kidney stones from calcium deposits"}]'::jsonb, '["a"]', 'Thyroid surgery can accidentally damage or remove the parathyroid glands, causing low PTH and low calcium; tingling around the mouth and in the hands is a sign of hypocalcemia. Hypercalcemia is the opposite problem and causes bones, stones, groans, and moans rather than tingling.'),
  ('parathyroid', 2, 'While assessing a client after a thyroidectomy, the nurse taps the cheek over the facial nerve and observes twitching of the facial muscles. How should the nurse interpret this finding?', '[{"id": "a", "text": "Positive Trousseau''s sign indicating hypocalcemia"}, {"id": "b", "text": "Positive Trousseau''s sign indicating hypercalcemia"}, {"id": "c", "text": "Positive Chvostek''s sign indicating hypercalcemia"}, {"id": "d", "text": "Positive Chvostek''s sign indicating hypocalcemia"}]'::jsonb, '["d"]', 'Facial twitching when the cheek/facial nerve is tapped is Chvostek''s sign, a classic sign of low calcium. Trousseau''s sign is elicited with an inflated BP cuff, not by tapping the cheek.'),
  ('parathyroid', 3, 'The nurse inflates a blood pressure cuff on the arm of a client with hypoparathyroidism, and the client''s hand and wrist curl inward. Which interpretation is correct?', '[{"id": "a", "text": "Positive Trousseau''s sign suggesting high calcium"}, {"id": "b", "text": "Positive Chvostek''s sign suggesting low calcium"}, {"id": "c", "text": "Positive Trousseau''s sign suggesting low calcium"}, {"id": "d", "text": "Expected cuff response suggesting high calcium"}]'::jsonb, '["c"]', 'A hand/wrist carpopedal spasm when a BP cuff is inflated is Trousseau''s sign, a sign of hypocalcemia. Chvostek''s sign is facial twitching from tapping the cheek.'),
  ('parathyroid', 4, 'A client''s laboratory results show calcium 11.8 mg/dL, phosphorus 2.0 mg/dL, and an elevated PTH level. These results are most consistent with which condition?', '[{"id": "a", "text": "Hyperphosphatemia"}, {"id": "b", "text": "Hypoparathyroidism"}, {"id": "c", "text": "Hypocalcemia"}, {"id": "d", "text": "Hyperparathyroidism"}]'::jsonb, '["d"]', 'High PTH with calcium above 10.5 mg/dL and phosphorus below 2.5 mg/dL is the hyperparathyroidism pattern. Hypoparathyroidism shows the reverse pattern: low PTH, low calcium, and high phosphorus.'),
  ('parathyroid', 5, 'A client''s laboratory results show calcium 7.6 mg/dL, phosphorus 5.2 mg/dL, and a low PTH level. Which assessment finding should the nurse anticipate?', '[{"id": "a", "text": "Kidney stone formation"}, {"id": "b", "text": "Decreased deep tendon reflexes"}, {"id": "c", "text": "Positive Trousseau''s sign"}, {"id": "d", "text": "Shortened QT interval"}]'::jsonb, '["c"]', 'Low PTH with low calcium and high phosphorus indicates hypoparathyroidism, which causes signs such as a positive Trousseau''s sign. A shortened QT interval, kidney stones, and decreased reflexes are findings of high calcium.'),
  ('parathyroid', 6, 'The nurse reviews the laboratory results of a client newly diagnosed with hypoparathyroidism. Which result is expected with this diagnosis?', '[{"id": "a", "text": "Phosphorus 5.0 mg/dL"}, {"id": "b", "text": "Phosphorus 2.1 mg/dL"}, {"id": "c", "text": "Calcium 9.4 mg/dL"}, {"id": "d", "text": "Calcium 10.9 mg/dL"}]'::jsonb, '["a"]', 'Too little PTH causes low calcium and high phosphorus, so a phosphorus above the 2.5–4.5 mg/dL range is expected. Phosphorus 2.1 mg/dL is low, which fits hyperparathyroidism instead.'),
  ('parathyroid', 7, 'A client with hyperparathyroidism has a serum calcium of 11.6 mg/dL. Which cardiac finding is consistent with this calcium level?', '[{"id": "a", "text": "Low dysrhythmia risk"}, {"id": "b", "text": "Low blood pressure"}, {"id": "c", "text": "Prolonged QT interval"}, {"id": "d", "text": "Shortened QT interval"}]'::jsonb, '["d"]', 'High calcium affects the heart and causes hypertension, dysrhythmias, and a shortened QT interval. A prolonged QT interval is associated with low calcium.'),
  ('parathyroid', 8, 'A client with hypoparathyroidism has a serum calcium of 7.4 mg/dL. The nurse places the client on a cardiac monitor to watch for which ECG change?', '[{"id": "a", "text": "Prolonged QT interval"}, {"id": "b", "text": "Shortened QT with hypertension"}, {"id": "c", "text": "Normal QT interval"}, {"id": "d", "text": "Shortened QT interval"}]'::jsonb, '["a"]', 'Low calcium can cause dysrhythmias and a prolonged QT interval, so ECG monitoring is a nursing priority. A shortened QT interval is seen with high calcium.'),
  ('parathyroid', 9, 'A client with severe hypocalcemia after a thyroidectomy reports throat tightness and is having difficulty breathing. The nurse is most concerned about which complication?', '[{"id": "a", "text": "Laryngospasm blocking the airway"}, {"id": "b", "text": "Kidney stones from calcium deposits"}, {"id": "c", "text": "Shortened QT interval on ECG"}, {"id": "d", "text": "Fracture from osteoporotic bones"}]'::jsonb, '["a"]', 'Severe hypocalcemia can cause laryngospasm, which can block the airway, so airway and breathing are the priority. Kidney stones, fragile bones, and a shortened QT interval are associated with high calcium.'),
  ('parathyroid', 10, 'A client with a serum calcium of 6.9 mg/dL is experiencing tetany and painful muscle spasms. Which medication should the nurse anticipate administering first?', '[{"id": "a", "text": "Oral alendronate"}, {"id": "b", "text": "IV calcium gluconate"}, {"id": "c", "text": "IV furosemide"}, {"id": "d", "text": "Oral cinacalcet"}]'::jsonb, '["b"]', 'IV calcium gluconate is the emergency treatment for severe symptomatic hypocalcemia such as tetany. Furosemide and cinacalcet are used to lower calcium in hyperparathyroidism and would worsen the problem.'),
  ('parathyroid', 11, 'The nurse is preparing the room for a client returning from a thyroidectomy. Which medication should be readily available at the bedside?', '[{"id": "a", "text": "IV furosemide"}, {"id": "b", "text": "Oral alendronate"}, {"id": "c", "text": "IV calcium gluconate"}, {"id": "d", "text": "Oral cinacalcet"}]'::jsonb, '["c"]', 'After thyroidectomy the parathyroid glands may be damaged, so the nurse keeps IV calcium gluconate available for severe symptomatic hypocalcemia. Furosemide and cinacalcet lower calcium and are used for hypercalcemia.'),
  ('parathyroid', 12, 'A client with severe hypercalcemia has prescriptions for IV normal saline and IV furosemide. Which sequence should the nurse follow?', '[{"id": "a", "text": "Give furosemide alone and withhold fluids"}, {"id": "b", "text": "Hold normal saline until diuresis begins"}, {"id": "c", "text": "Infuse normal saline first, then give furosemide"}, {"id": "d", "text": "Give furosemide first, then infuse normal saline"}]'::jsonb, '["c"]', 'Furosemide may be used after hydration to increase calcium excretion; giving it before fluids can worsen dehydration. Starting with furosemide reverses the safe order.'),
  ('parathyroid', 13, 'A student nurse asks why furosemide is not given before IV fluids to a client with severe hypercalcemia. Which response by the nurse is accurate?', '[{"id": "a", "text": "Diuresis before fluids raises the phosphorus level"}, {"id": "b", "text": "Diuresis before fluids blocks vitamin D activation"}, {"id": "c", "text": "Diuresis before fluids can worsen dehydration"}, {"id": "d", "text": "Diuresis before fluids lowers PTH too quickly"}]'::jsonb, '["c"]', 'Furosemide should not be given before fluids because it can worsen dehydration; it is used after hydration to increase calcium excretion in urine. Lowering PTH is the action of cinacalcet, not a reason to delay the diuretic.'),
  ('parathyroid', 14, 'A client with severe hypercalcemia is started on IV normal saline. The nurse explains that the main purpose of this infusion is to:', '[{"id": "a", "text": "Rehydrate and help the kidneys remove calcium"}, {"id": "b", "text": "Directly lower the secretion of PTH"}, {"id": "c", "text": "Replace the phosphorus lost in the urine"}, {"id": "d", "text": "Strengthen bones and improve bone density"}]'::jsonb, '["a"]', 'IV normal saline rehydrates the client with severe hypercalcemia and helps the kidneys remove calcium. Lowering PTH is the action of cinacalcet, and improving bone density is the action of alendronate.'),
  ('parathyroid', 15, 'A client with hyperparathyroidism is prescribed cinacalcet. Which explanation of the medication''s action should the nurse include in teaching?', '[{"id": "a", "text": "It lowers PTH and helps lower calcium"}, {"id": "b", "text": "It increases bone density to prevent fractures"}, {"id": "c", "text": "It increases calcium loss through diuresis"}, {"id": "d", "text": "It replaces active vitamin D in the body"}]'::jsonb, '["a"]', 'Cinacalcet is a calcimimetic that lowers PTH and helps lower calcium. Improving bone density describes alendronate, and increasing urinary calcium excretion describes furosemide.'),
  ('parathyroid', 16, 'A client with hyperparathyroidism and osteoporosis is prescribed alendronate. The nurse explains that the purpose of this medication is to:', '[{"id": "a", "text": "Lower the PTH level in the blood"}, {"id": "b", "text": "Rehydrate the client with severe hypercalcemia"}, {"id": "c", "text": "Protect bones and improve bone density"}, {"id": "d", "text": "Increase calcium excretion in the urine"}]'::jsonb, '["c"]', 'Alendronate is a bisphosphonate that helps protect bones and improve bone density, especially with osteopenia or osteoporosis. Lowering PTH is the action of cinacalcet.'),
  ('parathyroid', 17, 'A client is diagnosed with primary hyperparathyroidism caused by an overactive parathyroid gland. Which treatment is considered definitive for many of these clients?', '[{"id": "a", "text": "IV calcium gluconate"}, {"id": "b", "text": "Oral calcitriol"}, {"id": "c", "text": "Magnesium supplements"}, {"id": "d", "text": "Parathyroidectomy"}]'::jsonb, '["d"]', 'Surgical removal of the overactive parathyroid gland(s) is the definitive treatment for many patients with primary hyperparathyroidism. Calcium gluconate, calcitriol, and magnesium are treatments for hypoparathyroidism.'),
  ('parathyroid', 18, 'The nurse is teaching a client with hyperparathyroidism about self-care. Which statement by the client indicates a need for further teaching?', '[{"id": "a", "text": "I will start taking calcium supplements daily."}, {"id": "b", "text": "I will drink more water throughout the day."}, {"id": "c", "text": "I will take a walk most days of the week."}, {"id": "d", "text": "I will be careful to prevent falls at home."}]'::jsonb, '["a"]', 'Clients with hyperparathyroidism should avoid calcium supplements and very high-calcium intake unless prescribed. Walking, increasing water intake, and fall precautions are all correct nursing priorities.'),
  ('parathyroid', 19, 'A client with hyperparathyroidism asks, ''Should I cut all calcium out of my diet?'' Which response by the nurse is most appropriate?', '[{"id": "a", "text": "No, eat extra high-calcium foods to rebuild bone."}, {"id": "b", "text": "No, avoid excess calcium but do not fully restrict it."}, {"id": "c", "text": "Yes, remove all calcium-containing foods now."}, {"id": "d", "text": "No, add a daily calcium supplement instead."}]'::jsonb, '["b"]', 'Excessive calcium should be avoided, but calcium should not be completely restricted unless the provider orders it. Adding supplements or extra high-calcium foods would worsen hypercalcemia.'),
  ('parathyroid', 20, 'A client with hyperparathyroidism asks why the nurse keeps encouraging extra water intake. Which explanation is correct?', '[{"id": "a", "text": "Extra water directly strengthens bones"}, {"id": "b", "text": "Extra water lowers the phosphorus level"}, {"id": "c", "text": "Extra water raises the PTH level"}, {"id": "d", "text": "Extra water dilutes urine to prevent stones"}]'::jsonb, '["d"]', 'Increasing water intake helps dilute urine and prevents kidney stones caused by excess calcium. Strengthening bones is the purpose of weight-bearing exercise, not fluids.'),
  ('parathyroid', 21, 'A client with hyperparathyroidism asks what type of activity is best. Which recommendation should the nurse give?', '[{"id": "a", "text": "Only non-weight-bearing range-of-motion exercise"}, {"id": "b", "text": "No activity until calcium returns to normal"}, {"id": "c", "text": "Strict bed rest to protect fragile bones"}, {"id": "d", "text": "Daily walking with light resistance exercise"}]'::jsonb, '["d"]', 'Weight-bearing exercise such as walking and light resistance exercise helps strengthen bones and reduce bone loss. Bed rest and non-weight-bearing activity do not provide this benefit.'),
  ('parathyroid', 22, 'A client with hyperparathyroidism has a bone density scan showing osteoporosis. Which nursing intervention is the priority for client safety?', '[{"id": "a", "text": "Restrict oral fluid intake"}, {"id": "b", "text": "Check for Chvostek''s sign every hour"}, {"id": "c", "text": "Implement fall precautions"}, {"id": "d", "text": "Initiate seizure precautions"}]'::jsonb, '["c"]', 'Bones may be weak in hyperparathyroidism, so the client has a higher risk for fractures and needs fall precautions. Seizure precautions and Chvostek''s sign checks relate to low calcium.'),
  ('parathyroid', 23, 'A client with a serum calcium of 11.4 mg/dL is being assessed for gastrointestinal effects. Which finding should the nurse expect?', '[{"id": "a", "text": "Carpopedal spasm of the hand"}, {"id": "b", "text": "Constipation and abdominal pain"}, {"id": "c", "text": "Positive Chvostek''s sign"}, {"id": "d", "text": "Tingling around the mouth"}]'::jsonb, '["b"]', 'Calcium above 10.5 mg/dL is hypercalcemia, and the ''groans'' of hypercalcemia include nausea, vomiting, constipation, and abdominal pain. Tingling, Chvostek''s sign, and carpopedal spasm are signs of low calcium.'),
  ('parathyroid', 24, 'The family of a client with a serum calcium of 11.9 mg/dL reports that the client has become confused and lethargic. The nurse recognizes these findings as:', '[{"id": "a", "text": "Neurologic effects of low calcium"}, {"id": "b", "text": "Early signs of developing tetany"}, {"id": "c", "text": "Early signs of laryngospasm"}, {"id": "d", "text": "Neurologic effects of high calcium"}]'::jsonb, '["d"]', 'The ''moans'' of hypercalcemia include depression, confusion, lethargy, and extreme fatigue. Tetany and laryngospasm are complications of low calcium.'),
  ('parathyroid', 25, 'The nurse performs a neuromuscular assessment on a client with hyperparathyroidism. Which finding is expected?', '[{"id": "a", "text": "Painful muscle spasms and tetany"}, {"id": "b", "text": "Facial twitching when the cheek is tapped"}, {"id": "c", "text": "Positive Trousseau''s sign"}, {"id": "d", "text": "Decreased deep tendon reflexes"}]'::jsonb, '["d"]', 'High calcium causes muscle weakness and decreased deep tendon reflexes. Trousseau''s sign, tetany, and facial twitching reflect the overactive nerves of low calcium.'),
  ('parathyroid', 26, 'The nurse is monitoring the urinary and fluid status of a client with hypercalcemia from hyperparathyroidism. Which finding is expected?', '[{"id": "a", "text": "Normal urine output and hydration"}, {"id": "b", "text": "Decreased urine output with fluid overload"}, {"id": "c", "text": "Polyuria with signs of dehydration"}, {"id": "d", "text": "Decreased urine output with edema"}]'::jsonb, '["c"]', 'High calcium affects the kidneys and causes polyuria and dehydration. This is also why IV normal saline is used to rehydrate clients with severe hypercalcemia.'),
  ('parathyroid', 27, 'The nurse reviews the diagnostic workup of a client with suspected hyperparathyroidism. Which finding supports this diagnosis?', '[{"id": "a", "text": "Phosphorus level above 4.5 mg/dL"}, {"id": "b", "text": "Bone density scan showing osteoporosis"}, {"id": "c", "text": "PTH level below the normal range"}, {"id": "d", "text": "Calcium level below 8.5 mg/dL"}]'::jsonb, '["b"]', 'Diagnosis of hyperparathyroidism includes high calcium, high PTH, low phosphorus, and a bone density scan showing osteoporosis. High phosphorus, low PTH, and low calcium point to hypoparathyroidism.'),
  ('parathyroid', 28, 'A client with long-standing hyperparathyroidism is admitted for evaluation. The nurse should assess for which complication caused by calcium deposits?', '[{"id": "a", "text": "Tetany"}, {"id": "b", "text": "Kidney stones"}, {"id": "c", "text": "Seizures"}, {"id": "d", "text": "Laryngospasm"}]'::jsonb, '["b"]', 'In hyperparathyroidism, the ''stones'' are kidney stones from calcium deposits. Laryngospasm, seizures, and tetany are complications of low calcium.'),
  ('parathyroid', 29, 'The nurse is caring for two clients, one with hyperparathyroidism and one with hypoparathyroidism. Which finding is consistent with hypoparathyroidism rather than hyperparathyroidism?', '[{"id": "a", "text": "Numbness and tingling around the mouth"}, {"id": "b", "text": "Shortened QT interval"}, {"id": "c", "text": "Constipation and abdominal pain"}, {"id": "d", "text": "Recurrent kidney stones"}]'::jsonb, '["a"]', 'Low calcium causes overactive nerves with numbness/tingling in the hands, feet, and around the mouth. Kidney stones, a shortened QT interval, and constipation are signs of high calcium in hyperparathyroidism.'),
  ('parathyroid', 30, 'A client newly diagnosed with primary hyperparathyroidism asks what usually causes the condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "Damage during thyroid surgery"}, {"id": "b", "text": "A benign tumor of a parathyroid gland"}, {"id": "c", "text": "A deficiency of vitamin D"}, {"id": "d", "text": "Long-standing chronic kidney disease"}]'::jsonb, '["b"]', 'Primary hyperparathyroidism starts inside the gland and is usually caused by a parathyroid adenoma, a benign tumor that produces too much PTH. Chronic kidney disease and vitamin D deficiency cause secondary hyperparathyroidism.'),
  ('parathyroid', 31, 'A client with long-standing chronic kidney disease develops hyperparathyroidism. How should the nurse classify this condition?', '[{"id": "a", "text": "Secondary, caused by prolonged low calcium"}, {"id": "b", "text": "Primary, caused by a parathyroid adenoma"}, {"id": "c", "text": "Primary, caused by parathyroid hyperplasia"}, {"id": "d", "text": "Functional, caused by low magnesium levels"}]'::jsonb, '["a"]', 'Secondary hyperparathyroidism starts outside the gland: calcium is low for a long time, so the glands produce more PTH, and chronic kidney disease is a common cause. Adenoma and hyperplasia cause primary hyperparathyroidism.'),
  ('parathyroid', 32, 'The nurse is reviewing the histories of several clients. Which client is at risk for secondary hyperparathyroidism?', '[{"id": "a", "text": "A client with autoimmune parathyroid disease"}, {"id": "b", "text": "A client who had a thyroidectomy yesterday"}, {"id": "c", "text": "A client with a parathyroid adenoma"}, {"id": "d", "text": "A client with vitamin D deficiency"}]'::jsonb, '["d"]', 'Common causes of secondary hyperparathyroidism include chronic kidney disease and vitamin D deficiency. A parathyroid adenoma causes primary hyperparathyroidism, while thyroid surgery and autoimmune disease cause hypoparathyroidism.'),
  ('parathyroid', 33, 'A client with hypoparathyroidism has persistent hypocalcemia, and the latest laboratory results show a low magnesium level. Which prescription should the nurse anticipate?', '[{"id": "a", "text": "Magnesium supplements"}, {"id": "b", "text": "Oral alendronate therapy"}, {"id": "c", "text": "IV furosemide therapy"}, {"id": "d", "text": "Oral cinacalcet therapy"}]'::jsonb, '["a"]', 'Low magnesium should be corrected because magnesium is needed for normal PTH release and function. Furosemide and cinacalcet lower calcium and are used for hypercalcemia.'),
  ('parathyroid', 34, 'A client asks how a low magnesium level could cause hypoparathyroidism. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Low magnesium makes kidneys excrete phosphorus"}, {"id": "b", "text": "Low magnesium causes PTH to be overproduced"}, {"id": "c", "text": "Magnesium is needed for normal PTH release"}, {"id": "d", "text": "Low magnesium pulls calcium out of bones"}]'::jsonb, '["c"]', 'Magnesium is needed for normal PTH release and action, so severe hypomagnesemia can cause functional hypoparathyroidism. Low magnesium prevents PTH release rather than causing overproduction.'),
  ('parathyroid', 35, 'A client with hypoparathyroidism is prescribed calcitriol and asks why it is needed. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It lowers the PTH level in the blood"}, {"id": "b", "text": "It increases calcium loss in the urine"}, {"id": "c", "text": "It protects bones and improves bone density"}, {"id": "d", "text": "It is active vitamin D to aid calcium absorption"}]'::jsonb, '["d"]', 'Calcitriol is the active form of vitamin D and helps the intestines absorb calcium; it is used because low PTH reduces vitamin D activation. Lowering PTH describes cinacalcet, and improving bone density describes alendronate.'),
  ('parathyroid', 36, 'The nurse is teaching a client with hypoparathyroidism about diet. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will include more high-calcium foods."}, {"id": "b", "text": "I can keep drinking cola with my lunch."}, {"id": "c", "text": "I will cut back on processed meats."}, {"id": "d", "text": "I will take my calcium supplement as prescribed."}]'::jsonb, '["b"]', 'Clients with hypoparathyroidism should avoid high-phosphorus foods such as cola/soda, processed meats, and organ meats. Eating high-calcium foods and taking calcium supplements as prescribed are correct.'),
  ('parathyroid', 37, 'A client with hypoparathyroidism asks which type of diet is recommended. Which diet should the nurse encourage?', '[{"id": "a", "text": "Low-calcium, low-phosphorus diet"}, {"id": "b", "text": "High-calcium, high-phosphorus diet"}, {"id": "c", "text": "High-calcium, low-phosphorus diet"}, {"id": "d", "text": "Low-calcium, high-phosphorus diet"}]'::jsonb, '["c"]', 'Hypoparathyroidism causes low calcium and high phosphorus, so a high-calcium, low-phosphorus diet helps increase calcium and reduce phosphorus. A high-phosphorus diet would worsen the imbalance.'),
  ('parathyroid', 38, 'A client who had a thyroidectomy this morning reports tingling in the fingers. Which action should the nurse take first?', '[{"id": "a", "text": "Prepare to administer IV furosemide"}, {"id": "b", "text": "Assess for Chvostek''s and Trousseau''s signs"}, {"id": "c", "text": "Document the finding and recheck in 4 hours"}, {"id": "d", "text": "Encourage walking to strengthen the bones"}]'::jsonb, '["b"]', 'Tingling after thyroidectomy suggests hypocalcemia, and Chvostek''s and Trousseau''s signs should always be checked in post-thyroidectomy clients. Furosemide and weight-bearing exercise are interventions for hypercalcemia.'),
  ('parathyroid', 39, 'The nurse is caring for a client with hypoparathyroidism. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "New-onset seizure activity"}, {"id": "b", "text": "Phosphorus of 4.0 mg/dL"}, {"id": "c", "text": "Calcium of 9.2 mg/dL"}, {"id": "d", "text": "Request for the scheduled oral calcium"}]'::jsonb, '["a"]', 'Seizures, laryngospasm, and bronchospasm occur in severe cases of hypocalcemia and require emergency treatment. Calcium 9.2 mg/dL and phosphorus 4.0 mg/dL are within normal ranges.'),
  ('parathyroid', 40, 'The nurse is reviewing the histories of four clients. Which client is at highest risk for developing hypoparathyroidism?', '[{"id": "a", "text": "A client with chronic kidney disease"}, {"id": "b", "text": "A client who had thyroid surgery yesterday"}, {"id": "c", "text": "A client with parathyroid hyperplasia"}, {"id": "d", "text": "A client with a parathyroid adenoma"}]'::jsonb, '["b"]', 'Thyroid surgery is the most common cause of hypoparathyroidism because the parathyroid glands may be accidentally damaged or removed. Adenoma, hyperplasia, and chronic kidney disease are causes of hyperparathyroidism.'),
  ('parathyroid', 41, 'A client asks how parathyroid hormone raises the blood calcium level. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "It tells kidneys to excrete more calcium"}, {"id": "b", "text": "It pulls calcium from bones into the blood"}, {"id": "c", "text": "It blocks the activation of vitamin D"}, {"id": "d", "text": "It tells kidneys to hold on to phosphorus"}]'::jsonb, '["b"]', 'PTH raises calcium by pulling calcium from bones into blood, helping the intestines absorb calcium, telling kidneys to keep calcium, and activating vitamin D. Excreting calcium and blocking vitamin D would lower calcium.'),
  ('parathyroid', 42, 'A client has an elevated PTH level. Which effect on the kidneys should the nurse expect?', '[{"id": "a", "text": "Retaining both calcium and phosphorus"}, {"id": "b", "text": "Excreting both calcium and phosphorus"}, {"id": "c", "text": "Retaining phosphorus and excreting calcium"}, {"id": "d", "text": "Retaining calcium and excreting phosphorus"}]'::jsonb, '["d"]', 'With high PTH, the kidneys keep calcium and excrete phosphorus in the urine, so calcium rises and phosphorus falls. Retaining phosphorus while losing calcium occurs with low PTH.'),
  ('parathyroid', 43, 'A client scheduled for neck surgery asks where the parathyroid glands are located. Which description by the nurse is accurate?', '[{"id": "a", "text": "Two glands within the pancreas"}, {"id": "b", "text": "One gland at the base of the brain"}, {"id": "c", "text": "Four small glands behind the thyroid"}, {"id": "d", "text": "Two glands resting on top of the kidneys"}]'::jsonb, '["c"]', 'The parathyroid glands are four small glands located behind the thyroid gland in the neck. This location explains why thyroid surgery can damage them.'),
  ('parathyroid', 44, 'A client with hypoparathyroidism asks why less calcium is absorbed from food. Which explanation by the nurse is correct?', '[{"id": "a", "text": "The bones are releasing too much calcium"}, {"id": "b", "text": "The kidneys are excreting too much phosphorus"}, {"id": "c", "text": "Less vitamin D is being activated"}, {"id": "d", "text": "The kidneys are keeping too much calcium"}]'::jsonb, '["c"]', 'With low PTH, less vitamin D is activated, leading to less calcium absorption from the gut. Low PTH also causes the kidneys to lose calcium and retain phosphorus, not the reverse.'),
  ('parathyroid', 45, 'A client with hypoparathyroidism has been treated with oral calcium and vitamin D. Which finding indicates the treatment has been effective?', '[{"id": "a", "text": "Calcium 9.2 mg/dL with no tingling"}, {"id": "b", "text": "Calcium 7.8 mg/dL with no tingling"}, {"id": "c", "text": "Positive Chvostek''s sign on assessment"}, {"id": "d", "text": "Phosphorus 5.4 mg/dL with no cramps"}]'::jsonb, '["a"]', 'A calcium of 9.2 mg/dL is within the normal 8.5–10.5 mg/dL range, and absence of tingling shows resolved symptoms. Calcium 7.8 mg/dL and phosphorus 5.4 mg/dL remain abnormal, and a positive Chvostek''s sign indicates ongoing hypocalcemia.'),
  ('parathyroid', 46, 'A client with hyperparathyroidism has been treated with cinacalcet. Which laboratory result indicates the medication is having the desired effect?', '[{"id": "a", "text": "Calcium 11.6 mg/dL"}, {"id": "b", "text": "Calcium 12.1 mg/dL"}, {"id": "c", "text": "Phosphorus 2.0 mg/dL"}, {"id": "d", "text": "Calcium 9.8 mg/dL"}]'::jsonb, '["d"]', 'Cinacalcet lowers PTH and helps lower calcium, so a calcium of 9.8 mg/dL within the 8.5–10.5 mg/dL range shows effect. Calcium above 10.5 mg/dL and phosphorus below 2.5 mg/dL indicate persistent hyperparathyroidism.'),
  ('parathyroid', 47, 'A client with hyperparathyroidism has a serum calcium of 12.0 mg/dL. Which nursing intervention is a priority?', '[{"id": "a", "text": "Encourage a high-calcium diet"}, {"id": "b", "text": "Monitor the cardiac rhythm closely"}, {"id": "c", "text": "Restrict all oral fluid intake"}, {"id": "d", "text": "Inflate a BP cuff to test for spasm"}]'::jsonb, '["b"]', 'High calcium affects the heart and can cause abnormal rhythms and a shortened QT interval, so monitoring for dysrhythmias is a priority. Restricting fluids is wrong because increased water intake helps prevent kidney stones.'),
  ('parathyroid', 48, 'A client has a serum calcium of 7.5 mg/dL. Which set of findings should the nurse expect?', '[{"id": "a", "text": "Confusion and kidney stones"}, {"id": "b", "text": "Painful muscle cramps and spasms"}, {"id": "c", "text": "Muscle weakness and decreased reflexes"}, {"id": "d", "text": "Constipation and polyuria"}]'::jsonb, '["b"]', 'Calcium below 8.5 mg/dL means hypocalcemia, which causes overactive nerves and tetany with painful muscle cramps and spasms. Muscle weakness, decreased reflexes, constipation, polyuria, and kidney stones are signs of high calcium.'),
  ('parathyroid', 49, 'A nursing student is reviewing how PTH affects calcium and phosphorus. Which statement by the student indicates correct understanding?', '[{"id": "a", "text": "When PTH is high, calcium and phosphorus both rise."}, {"id": "b", "text": "When PTH is high, calcium rises and phosphorus falls."}, {"id": "c", "text": "When PTH is low, calcium and phosphorus both fall."}, {"id": "d", "text": "When PTH is low, calcium rises and phosphorus falls."}]'::jsonb, '["b"]', 'Calcium and phosphorus usually work oppositely under PTH control: high PTH raises calcium and lowers phosphorus. Low PTH lowers calcium and raises phosphorus.'),
  ('parathyroid', 50, 'A client with no history of neck surgery is diagnosed with hypoparathyroidism. The nurse recognizes which as a possible cause?', '[{"id": "a", "text": "Autoimmune attack on the parathyroid glands"}, {"id": "b", "text": "Long-standing chronic kidney disease"}, {"id": "c", "text": "A benign parathyroid adenoma"}, {"id": "d", "text": "Enlargement of the parathyroid glands"}]'::jsonb, '["a"]', 'Besides thyroid surgery, hypoparathyroidism can be caused by autoimmune disease in which the body attacks the parathyroid glands. Adenoma, hyperplasia, and chronic kidney disease cause hyperparathyroidism.'),
  ('medications', 1, 'A client with diabetes is shaky and diaphoretic with a low capillary glucose. The client is alert and able to swallow. What is the nurse''s first action?', '[{"id": "a", "text": "Administer glucagon by injection"}, {"id": "b", "text": "Give 15 g of fast-acting carbohydrate by mouth"}, {"id": "c", "text": "Start an infusion of IV dextrose"}, {"id": "d", "text": "Recheck the glucose in 15 minutes before treating"}]'::jsonb, '["b"]', 'A conscious client with mild hypoglycemia receives oral glucose, juice, or glucose tablets: 15 g of fast carbohydrate, then a recheck in 15 minutes. Glucagon is reserved for clients who are unconscious or cannot swallow, and the recheck follows treatment rather than replacing it.'),
  ('medications', 2, 'The nurse is teaching the family of a client with type 1 diabetes what to do if they find the client unconscious at home from hypoglycemia. Which medication should the family be taught to give?', '[{"id": "a", "text": "Orange juice poured into the mouth"}, {"id": "b", "text": "Glucose tablets placed under the tongue"}, {"id": "c", "text": "Glucagon by injection"}, {"id": "d", "text": "An extra dose of regular insulin"}]'::jsonb, '["c"]', 'Glucagon is used for severe hypoglycemia when there is no IV access and the client is unconscious or cannot swallow. Juice and glucose tablets are for a conscious client with mild hypoglycemia.'),
  ('medications', 3, 'A hospitalized client with severe hypoglycemia receives IV dextrose through an existing IV line, and the glucose level rises. What should the nurse continue to monitor for?', '[{"id": "a", "text": "Agranulocytosis"}, {"id": "b", "text": "Orthostatic hypotension"}, {"id": "c", "text": "Hypercalcemia"}, {"id": "d", "text": "Rebound hypoglycemia"}]'::jsonb, '["d"]', 'IV dextrose is used for severe hypoglycemia with IV access; it works fast, but the nurse must monitor for rebound hypoglycemia. Agranulocytosis is linked to methimazole, not dextrose.'),
  ('medications', 4, 'A client is newly prescribed levothyroxine for hypothyroidism. Which instruction should the nurse include?', '[{"id": "a", "text": "Take it in the morning on an empty stomach before breakfast"}, {"id": "b", "text": "Take it at bedtime with a light snack to aid absorption"}, {"id": "c", "text": "Take it with breakfast to reduce stomach upset"}, {"id": "d", "text": "Take it only on days when symptoms are noticeable"}]'::jsonb, '["a"]', 'Levothyroxine is taken in the morning on an empty stomach, 30–60 minutes before breakfast, and is lifelong. Taking it with food or only when symptomatic contradicts these rules.'),
  ('medications', 5, 'A client taking levothyroxine calls the clinic. Which reported findings suggest the dose may be too high?', '[{"id": "a", "text": "Weight gain and daytime sleepiness"}, {"id": "b", "text": "Slow heart rate and low energy"}, {"id": "c", "text": "Palpitations and insomnia"}, {"id": "d", "text": "Decreased sweating and calm mood"}]'::jsonb, '["c"]', 'Signs of too much levothyroxine include tachycardia, chest pain, palpitations, nervousness, sweating, insomnia, and weight loss. Weight gain and a slow heart rate are the opposite of these signs.'),
  ('medications', 6, 'A client''s thyroid replacement is changed from levothyroxine to liothyronine. Which feature of liothyronine should guide the nurse''s monitoring?', '[{"id": "a", "text": "It is a synthetic T4 with a slower onset"}, {"id": "b", "text": "It acts faster and causes more cardiac stimulation"}, {"id": "c", "text": "It blocks the conversion of T4 to T3"}, {"id": "d", "text": "It destroys overactive thyroid tissue"}]'::jsonb, '["b"]', 'Liothyronine is synthetic T3, faster acting, with more cardiac stimulation, so it must be used carefully. Blocking T4-to-T3 conversion describes PTU, and destroying thyroid tissue describes radioactive iodine.'),
  ('medications', 7, 'A client taking methimazole for hyperthyroidism reports a new fever and sore throat. How should the nurse interpret these findings?', '[{"id": "a", "text": "An expected reaction as the drug takes effect"}, {"id": "b", "text": "Early signs that the client has become hypothyroid"}, {"id": "c", "text": "Signs of severe liver injury from the drug"}, {"id": "d", "text": "Possible agranulocytosis that must be reported"}]'::jsonb, '["d"]', 'Fever or sore throat in a client on methimazole signals possible agranulocytosis and must be reported. Severe liver injury is the hallmark risk of PTU, signaled by jaundice and dark urine.'),
  ('medications', 8, 'A client taking propylthiouracil (PTU) reports several new symptoms. Which finding requires immediate reporting because it suggests the drug''s most serious adverse effect?', '[{"id": "a", "text": "Dark urine and right upper abdominal pain"}, {"id": "b", "text": "Constipation after starting the drug"}, {"id": "c", "text": "Dizziness when standing up quickly"}, {"id": "d", "text": "Decreased urine output over the day"}]'::jsonb, '["a"]', 'PTU can cause severe liver injury; jaundice, dark urine, fever, nausea, or right upper abdominal pain must be reported immediately. Constipation is a concern with oral calcium, and orthostatic dizziness with dopamine agonists.'),
  ('medications', 9, 'A client in the first trimester of pregnancy is diagnosed with hyperthyroidism. Which medication does the nurse anticipate is often preferred?', '[{"id": "a", "text": "Radioactive iodine"}, {"id": "b", "text": "Liothyronine"}, {"id": "c", "text": "Propylthiouracil (PTU)"}, {"id": "d", "text": "Levothyroxine"}]'::jsonb, '["c"]', 'PTU decreases thyroid hormone production and is often preferred in the first trimester of pregnancy. Radioactive iodine requires avoiding pregnancy, and liothyronine and levothyroxine are replacements for hypothyroidism.'),
  ('medications', 10, 'The nurse teaches a client scheduled for radioactive iodine therapy. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I need to avoid becoming pregnant.\""}, {"id": "b", "text": "\"This treatment means my thyroid can never become underactive.\""}, {"id": "c", "text": "\"I will follow the radiation precautions I was given.\""}, {"id": "d", "text": "\"The treatment works by destroying thyroid tissue.\""}]'::jsonb, '["b"]', 'Radioactive iodine destroys thyroid tissue and may cause hypothyroidism, so the client''s belief that the thyroid cannot become underactive is incorrect. Avoiding pregnancy and following radiation precautions are correct.'),
  ('medications', 11, 'A client with hyperthyroidism asks why propranolol was added to the treatment plan. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It lowers the amount of thyroid hormone you make.\""}, {"id": "b", "text": "\"It destroys part of the overactive thyroid gland.\""}, {"id": "c", "text": "\"It replaces the T3 your body is unable to make.\""}, {"id": "d", "text": "\"It controls symptoms like a fast heart rate and tremor.\""}]'::jsonb, '["d"]', 'Beta blockers control tachycardia, tremor, and anxiety for symptomatic relief but do not lower thyroid hormone. Destroying thyroid tissue describes radioactive iodine.'),
  ('medications', 12, 'A client in thyroid storm has prescriptions for propylthiouracil (PTU) and Lugol solution. How should the nurse sequence these medications?', '[{"id": "a", "text": "Give the PTU first, then the iodine solution"}, {"id": "b", "text": "Give the iodine solution first, then the PTU"}, {"id": "c", "text": "Give the iodine solution and hold the PTU"}, {"id": "d", "text": "Give the PTU and omit the iodine solution"}]'::jsonb, '["a"]', 'The antithyroid medication is given first, then iodine. If iodine is given first, it can provide more substrate for thyroid hormone production.'),
  ('medications', 13, 'A client is admitted with myxedema coma. Which combination of treatments does the nurse anticipate?', '[{"id": "a", "text": "IV PTU, iodine solution, and a cooling blanket"}, {"id": "b", "text": "Beta blocker, methimazole, and cooling measures"}, {"id": "c", "text": "IV levothyroxine, hydrocortisone, and warming"}, {"id": "d", "text": "Oral liothyronine, fluid restriction, and cooling"}]'::jsonb, '["c"]', 'Myxedema coma is treated with IV levothyroxine, hydrocortisone, warming, and airway/ventilation support. Beta blockers, antithyroid drugs, iodine, and cooling are thyroid storm treatments.'),
  ('medications', 14, 'The nurse reviews prescriptions for a client in thyroid storm. Which prescription should the nurse question?', '[{"id": "a", "text": "Propranolol"}, {"id": "b", "text": "Warming blanket"}, {"id": "c", "text": "Corticosteroid"}, {"id": "d", "text": "Methimazole"}]'::jsonb, '["b"]', 'Thyroid storm is treated with a beta blocker, PTU or methimazole, iodine solution, a corticosteroid, and cooling. Warming is part of myxedema coma care, not thyroid storm.'),
  ('medications', 15, 'A client with adrenal insufficiency is prescribed daily hydrocortisone. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will take my hydrocortisone with food.\""}, {"id": "b", "text": "\"My provider may raise my dose when I am ill.\""}, {"id": "c", "text": "\"I can stop the pills once my energy returns.\""}, {"id": "d", "text": "\"I must never stop this medicine suddenly.\""}]'::jsonb, '["c"]', 'Hydrocortisone replaces cortisol and must never be stopped abruptly. Taking it with food and increasing the dose during illness per the provider are correct.'),
  ('medications', 16, 'A client with Addison''s disease takes fludrocortisone. Which assessment finding is most important for the nurse to report?', '[{"id": "a", "text": "Blood pressure within the client''s usual range"}, {"id": "b", "text": "Stable weight compared with last week"}, {"id": "c", "text": "Serum sodium within the normal range"}, {"id": "d", "text": "New ankle edema and elevated blood pressure"}]'::jsonb, '["d"]', 'Fludrocortisone retains sodium and water, so the nurse monitors BP and edema; new edema with elevated BP should be reported. The other findings are stable and expected.'),
  ('medications', 17, 'The nurse monitors the laboratory results of a client receiving fludrocortisone. Which electrolyte change is consistent with the action of this drug?', '[{"id": "a", "text": "Increased serum potassium"}, {"id": "b", "text": "Decreased serum potassium"}, {"id": "c", "text": "Decreased serum sodium"}, {"id": "d", "text": "Increased serum calcium"}]'::jsonb, '["b"]', 'Fludrocortisone is a mineralocorticoid that retains sodium and water and loses potassium, so serum potassium may decrease. Decreased sodium is the reverse of its sodium-retaining effect.'),
  ('medications', 18, 'A client with chronic adrenal insufficiency arrives confused and severely hypotensive after missing several doses of medication. Which treatment does the nurse anticipate?', '[{"id": "a", "text": "IV hydrocortisone, normal saline, and dextrose"}, {"id": "b", "text": "Fluid restriction and hypertonic saline 3%"}, {"id": "c", "text": "IV levothyroxine and warming"}, {"id": "d", "text": "Oral fludrocortisone and fluid restriction"}]'::jsonb, '["a"]', 'Adrenal crisis requires immediate IV corticosteroids, IV saline, and dextrose. Fluid restriction and hypertonic saline are SIADH treatments, and IV levothyroxine with warming treats myxedema coma.'),
  ('medications', 19, 'A client has been taking prednisone for several months for an inflammatory condition. Which laboratory value is most important for the nurse to monitor because of this medication?', '[{"id": "a", "text": "Serum prolactin"}, {"id": "b", "text": "Urine specific gravity"}, {"id": "c", "text": "Blood glucose"}, {"id": "d", "text": "Serum TSH"}]'::jsonb, '["c"]', 'Prednisone can cause hyperglycemia along with infection risk, osteoporosis, and Cushingoid features, so blood glucose is monitored. TSH is monitored for levothyroxine therapy.'),
  ('medications', 20, 'The nurse teaches a client who will be taking a corticosteroid long term. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I will take my dose on an empty stomach.\""}, {"id": "b", "text": "\"I can skip doses on days I feel well.\""}, {"id": "c", "text": "\"A fever is expected and does not need reporting.\""}, {"id": "d", "text": "\"I will stay away from people who are sick.\""}]'::jsonb, '["d"]', 'Corticosteroid teaching includes avoiding sick contacts, taking the drug with food, not stopping abruptly, and reporting fever or infection. Fever should be reported, not ignored.'),
  ('medications', 21, 'A client with Cushing syndrome is started on ketoconazole to decrease cortisol production. Which laboratory tests should the nurse plan to monitor?', '[{"id": "a", "text": "Liver function tests"}, {"id": "b", "text": "Thyroid function tests"}, {"id": "c", "text": "Serum prolactin level"}, {"id": "d", "text": "Urine specific gravity"}]'::jsonb, '["a"]', 'Ketoconazole decreases cortisol production and requires monitoring of liver function. Thyroid tests relate to thyroid drugs, and urine specific gravity to DI treatment.'),
  ('medications', 22, 'A client with Cushing syndrome is receiving metyrapone to decrease cortisol synthesis. The nurse should monitor the client for signs of which complication?', '[{"id": "a", "text": "Hypercalcemia"}, {"id": "b", "text": "Agranulocytosis"}, {"id": "c", "text": "Adrenal insufficiency"}, {"id": "d", "text": "Water intoxication"}]'::jsonb, '["c"]', 'Metyrapone decreases cortisol synthesis, so the nurse monitors for adrenal insufficiency symptoms. Water intoxication is a risk of desmopressin, and agranulocytosis of methimazole.'),
  ('medications', 23, 'A client with pheochromocytoma is being prepared for surgery and has prescriptions for phenoxybenzamine and propranolol. Which plan is correct?', '[{"id": "a", "text": "Start propranolol first, then add phenoxybenzamine"}, {"id": "b", "text": "Give both drugs together starting the same day"}, {"id": "c", "text": "Give propranolol alone and omit phenoxybenzamine"}, {"id": "d", "text": "Start phenoxybenzamine first, then add propranolol"}]'::jsonb, '["d"]', 'Phenoxybenzamine is an alpha blocker given before surgery, and the alpha blocker must be given before the beta blocker. Beta blockers are used only after alpha blockade.'),
  ('medications', 24, 'A nursing student asks why a beta blocker must never be given first to a client with pheochromocytoma. What is the nurse''s best explanation?', '[{"id": "a", "text": "Unopposed alpha stimulation can worsen severe hypertension"}, {"id": "b", "text": "The beta blocker will drop blood pressure to unsafe lows"}, {"id": "c", "text": "The beta blocker increases catecholamine production"}, {"id": "d", "text": "The beta blocker makes the alpha blocker ineffective"}]'::jsonb, '["a"]', 'Giving a beta blocker first leaves alpha stimulation unopposed, which can worsen severe hypertension. Decreasing catecholamine production is the action of metyrosine, not a beta blocker effect.'),
  ('medications', 25, 'A client with pheochromocytoma develops a hypertensive crisis and receives phentolamine. What is the nurse''s priority assessment?', '[{"id": "a", "text": "Urine specific gravity"}, {"id": "b", "text": "Liver function results"}, {"id": "c", "text": "Blood pressure, closely"}, {"id": "d", "text": "Serum calcium level"}]'::jsonb, '["c"]', 'Phentolamine is an alpha blocker for hypertensive crisis, and BP must be monitored closely. The other assessments relate to drugs for DI, Cushing syndrome, and calcium disorders.'),
  ('medications', 26, 'A client with diabetes insipidus is receiving desmopressin (DDAVP). Which findings indicate the medication is effective?', '[{"id": "a", "text": "Urine output increases and specific gravity decreases"}, {"id": "b", "text": "Urine output decreases and specific gravity increases"}, {"id": "c", "text": "Urine output increases and specific gravity increases"}, {"id": "d", "text": "Urine output decreases and specific gravity decreases"}]'::jsonb, '["b"]', 'When DDAVP is working, urine output decreases, urine specific gravity increases, and serum sodium normalizes. The other options reverse one or both directions.'),
  ('medications', 27, 'The nurse is caring for a client receiving desmopressin for diabetes insipidus. Which finding should the nurse report?', '[{"id": "a", "text": "Urine output lower than before therapy"}, {"id": "b", "text": "Urine specific gravity higher than before"}, {"id": "c", "text": "Serum sodium returning to normal range"}, {"id": "d", "text": "Serum sodium falling below normal range"}]'::jsonb, '["d"]', 'Desmopressin requires monitoring for hyponatremia and water intoxication, so a sodium below normal must be reported. Decreased urine output, increased specific gravity, and normalizing sodium indicate the drug is working.'),
  ('medications', 28, 'A client with nephrogenic diabetes insipidus is prescribed a thiazide diuretic. The family asks why a diuretic is being used. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It removes the extra water the kidneys are holding.\""}, {"id": "b", "text": "\"It replaces the ADH that the body is lacking.\""}, {"id": "c", "text": "\"In this type of DI, it paradoxically reduces urine.\""}, {"id": "d", "text": "\"It blocks ADH so the sodium level can rise.\""}]'::jsonb, '["c"]', 'Thiazide diuretics are sometimes used for nephrogenic DI because they paradoxically decrease urine output. Replacing ADH describes desmopressin or vasopressin.'),
  ('medications', 29, 'A client is diagnosed with SIADH and has mild hyponatremia without severe symptoms. Which intervention is the common first-line treatment?', '[{"id": "a", "text": "Encourage oral fluid intake"}, {"id": "b", "text": "Administer desmopressin"}, {"id": "c", "text": "Administer vasopressin"}, {"id": "d", "text": "Restrict fluids and weigh daily"}]'::jsonb, '["d"]', 'Fluid restriction is the common first-line treatment for SIADH, with strict I&O and daily weight. Desmopressin and vasopressin replace ADH and are used for DI.'),
  ('medications', 30, 'A client with SIADH has severe symptomatic hyponatremia and is receiving hypertonic saline 3%. Which nursing action is a priority?', '[{"id": "a", "text": "Encourage the client to drink fluids"}, {"id": "b", "text": "Implement seizure precautions"}, {"id": "c", "text": "Check sodium only after the infusion"}, {"id": "d", "text": "Administer desmopressin as needed"}]'::jsonb, '["b"]', 'Hypertonic saline 3% is used for severe symptomatic hyponatremia; sodium is monitored closely and seizure precautions are implemented. Sodium must be monitored closely, not only after the infusion.'),
  ('medications', 31, 'A client with SIADH is started on tolvaptan. Which complication is the nurse''s priority concern?', '[{"id": "a", "text": "Sodium rising too quickly"}, {"id": "b", "text": "Rebound hypoglycemia"}, {"id": "c", "text": "Agranulocytosis"}, {"id": "d", "text": "Esophageal injury"}]'::jsonb, '["a"]', 'Tolvaptan raises sodium, and sodium can rise too quickly and cause osmotic demyelination syndrome, so close monitoring is required. Esophageal injury is a risk of oral bisphosphonates.'),
  ('medications', 32, 'A child with growth hormone deficiency is receiving somatropin. Which assessments should the nurse include in the monitoring plan?', '[{"id": "a", "text": "Urine specific gravity and sodium"}, {"id": "b", "text": "Liver enzymes and urine color"}, {"id": "c", "text": "Heart rhythm and serum calcium"}, {"id": "d", "text": "Growth, blood glucose, and joint pain"}]'::jsonb, '["d"]', 'Somatropin treats growth hormone deficiency, and the nurse monitors growth, glucose, and joint pain. Heart rhythm and calcium are monitored with IV calcium gluconate.'),
  ('medications', 33, 'A client with acromegaly is prescribed octreotide to decrease growth hormone release. The nurse should monitor for which drug-related problems?', '[{"id": "a", "text": "Low calcium and phosphate changes"}, {"id": "b", "text": "Glucose changes and gallbladder issues"}, {"id": "c", "text": "Rapidly rising serum sodium"}, {"id": "d", "text": "Fever and sore throat"}]'::jsonb, '["b"]', 'Octreotide requires monitoring of glucose, gallbladder issues, and GI effects. Rapidly rising sodium is a tolvaptan concern, and fever with sore throat is a methimazole concern.'),
  ('medications', 34, 'A client with a prolactinoma is started on bromocriptine. Which instruction is most important for the nurse to give?', '[{"id": "a", "text": "Report any fever or sore throat"}, {"id": "b", "text": "Report dark urine or yellow skin"}, {"id": "c", "text": "Report dizziness when standing up"}, {"id": "d", "text": "Report constipation that develops"}]'::jsonb, '["c"]', 'Bromocriptine is a dopamine agonist that can cause orthostatic hypotension, so dizziness on standing should be reported. Fever/sore throat and dark urine relate to antithyroid drugs.'),
  ('medications', 35, 'A client with hypoparathyroidism develops tetany, and IV calcium gluconate is prescribed. How should the nurse administer this medication?', '[{"id": "a", "text": "As a rapid IV push to stop the tetany"}, {"id": "b", "text": "Slowly, while monitoring heart rhythm"}, {"id": "c", "text": "Orally with meals to aid absorption"}, {"id": "d", "text": "Along with a dose of IV furosemide"}]'::jsonb, '["b"]', 'IV calcium gluconate treats acute symptomatic hypocalcemia/tetany and is given slowly with heart rhythm monitoring. Furosemide helps calcium excretion and is used for hypercalcemia.'),
  ('medications', 36, 'A client is taking oral calcium carbonate for calcium replacement. Which adverse effect should the nurse teach the client to watch for?', '[{"id": "a", "text": "Agranulocytosis"}, {"id": "b", "text": "Orthostatic hypotension"}, {"id": "c", "text": "Rebound hypoglycemia"}, {"id": "d", "text": "Constipation"}]'::jsonb, '["d"]', 'Oral calcium carbonate or citrate requires watching for constipation and hypercalcemia. Orthostatic hypotension is associated with dopamine agonists such as bromocriptine.'),
  ('medications', 37, 'The nurse teaches a client who is starting alendronate for osteoporosis. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will lie down for a while after I take it.\""}, {"id": "b", "text": "\"I will take it with a full glass of plain water.\""}, {"id": "c", "text": "\"I will take it in the morning on an empty stomach.\""}, {"id": "d", "text": "\"I will stay upright for 30 to 60 minutes after.\""}]'::jsonb, '["a"]', 'Alendronate must be taken on an empty stomach with plain water, and the client must stay upright 30–60 minutes to avoid esophageal injury. Lying down afterward is unsafe.'),
  ('medications', 38, 'A client with hyperparathyroidism is started on cinacalcet. Which laboratory finding should the nurse report as an adverse effect?', '[{"id": "a", "text": "Serum calcium above normal"}, {"id": "b", "text": "Serum sodium above normal"}, {"id": "c", "text": "Serum calcium below normal"}, {"id": "d", "text": "Serum potassium above normal"}]'::jsonb, '["c"]', 'Cinacalcet decreases PTH and calcium, so the nurse watches for hypocalcemia. A high calcium reflects the hyperparathyroid condition being treated, not a drug adverse effect.'),
  ('medications', 39, 'A client with hypercalcemia receives calcitonin. Which statement about this medication guides the nurse''s care?', '[{"id": "a", "text": "It lowers calcium slowly but with a lasting effect"}, {"id": "b", "text": "It lowers calcium quickly but its effect is short-term"}, {"id": "c", "text": "It raises calcium by increasing intestinal absorption"}, {"id": "d", "text": "It lowers calcium by restricting the client''s fluids"}]'::jsonb, '["b"]', 'Calcitonin quickly lowers calcium, but the effect is short-term, so calcium is monitored. Increasing calcium absorption describes calcitriol and vitamin D.'),
  ('medications', 40, 'A client with severe hypercalcemia has prescriptions for IV normal saline and IV furosemide. Which sequence is appropriate?', '[{"id": "a", "text": "Give furosemide first, then begin saline"}, {"id": "b", "text": "Give furosemide and withhold the saline"}, {"id": "c", "text": "Give furosemide and restrict all fluids"}, {"id": "d", "text": "Begin saline hydration, then furosemide"}]'::jsonb, '["d"]', 'Normal saline dilutes calcium and increases renal excretion, and loop diuretics help calcium excretion after hydration. Giving furosemide before or without hydration contradicts this order.'),
  ('medications', 41, 'A client with severe hypercalcemia is receiving large volumes of IV normal saline. For which complication should the nurse monitor?', '[{"id": "a", "text": "Fluid overload"}, {"id": "b", "text": "Agranulocytosis"}, {"id": "c", "text": "Rebound hypoglycemia"}, {"id": "d", "text": "Esophagitis"}]'::jsonb, '["a"]', 'Normal saline dilutes calcium and increases renal excretion, and the nurse monitors for fluid overload. Esophagitis is a risk of oral bisphosphonates.'),
  ('medications', 42, 'A postmenopausal client with osteoporosis has a history of blood clots. Which prescribed osteoporosis medication should the nurse question?', '[{"id": "a", "text": "Calcium carbonate"}, {"id": "b", "text": "Vitamin D3"}, {"id": "c", "text": "Alendronate"}, {"id": "d", "text": "Raloxifene"}]'::jsonb, '["d"]', 'Raloxifene, a SERM, carries a risk of VTE, which is a concern with a clot history. Alendronate''s main risk is esophagitis, and calcium with vitamin D supports bone health.'),
  ('medications', 43, 'The nurse reviews requests for combined oral contraceptives. Which client is the poorest candidate for this medication?', '[{"id": "a", "text": "A 22-year-old nonsmoker with no history of clots"}, {"id": "b", "text": "A 28-year-old nonsmoker with normal blood pressure"}, {"id": "c", "text": "A 38-year-old who smokes one pack of cigarettes daily"}, {"id": "d", "text": "A 30-year-old nonsmoker with regular menstrual cycles"}]'::jsonb, '["c"]', 'Combined oral contraceptives are avoided in smokers over 35, clients with a history of clots, and clients with uncontrolled hypertension. The other clients have none of these risks.'),
  ('medications', 44, 'A client with prostate cancer is starting leuprolide. What should the nurse teach the client to expect initially?', '[{"id": "a", "text": "Immediate and complete hormone suppression"}, {"id": "b", "text": "A temporary hormone flare before suppression"}, {"id": "c", "text": "A permanent increase in hormone production"}, {"id": "d", "text": "No change in hormone levels for the first year"}]'::jsonb, '["b"]', 'Leuprolide is a GnRH agonist that causes a temporary hormone flare, then suppression. Immediate suppression ignores the initial flare.'),
  ('medications', 45, 'A client receiving estrogen therapy for menopause symptoms is also prescribed a progestin. The client asks why. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The progestin helps protect the lining of the uterus.\""}, {"id": "b", "text": "\"The progestin removes the risk of blood clots.\""}, {"id": "c", "text": "\"The progestin is needed to help you ovulate.\""}, {"id": "d", "text": "\"The progestin keeps the estrogen from working.\""}]'::jsonb, '["a"]', 'Progesterone/progestins often protect the endometrium when estrogen is used. Estrogen carries a clot risk that a progestin does not remove, and ovulation induction is the use of clomiphene.'),
  ('medications', 46, 'A client is admitted with diabetic ketoacidosis (DKA). Which plan reflects the correct initial treatment order?', '[{"id": "a", "text": "IV regular insulin first, then begin IV fluids"}, {"id": "b", "text": "Subcutaneous glargine first, then IV fluids"}, {"id": "c", "text": "IV fluids first, then IV regular insulin"}, {"id": "d", "text": "IV fluids first, then subcutaneous NPH"}]'::jsonb, '["c"]', 'DKA is treated with IV fluids first, then regular insulin IV, with potassium monitoring and replacement. Regular insulin is the only insulin used IV, so glargine and NPH are not appropriate.'),
  ('medications', 47, 'A provider prescribes a continuous insulin infusion for a critically ill client. Which insulin should the nurse expect to use?', '[{"id": "a", "text": "NPH insulin"}, {"id": "b", "text": "Regular insulin"}, {"id": "c", "text": "Glargine insulin"}, {"id": "d", "text": "Detemir insulin"}]'::jsonb, '["b"]', 'Regular insulin is the only insulin used IV. NPH is a cloudy insulin that is rolled gently, and glargine and detemir are not mixed.'),
  ('medications', 48, 'The nurse is preparing insulin doses for several clients. Which action is appropriate?', '[{"id": "a", "text": "Rolling a cloudy NPH vial gently before use"}, {"id": "b", "text": "Mixing glargine with regular in one syringe"}, {"id": "c", "text": "Giving an NPH dose by the IV route"}, {"id": "d", "text": "Mixing detemir with NPH in one syringe"}]'::jsonb, '["a"]', 'NPH is cloudy, is rolled gently, and can be mixed. Glargine, detemir, and degludec are not mixed, and regular insulin is the only insulin used IV.'),
  ('medications', 49, 'A client with type 2 diabetes is started on an SGLT2 inhibitor. Which client statement indicates understanding of the teaching?', '[{"id": "a", "text": "\"I should watch for signs of a urinary or genital infection.\""}, {"id": "b", "text": "\"This drug works by keeping glucose out of my urine.\""}, {"id": "c", "text": "\"Limiting how much I drink will help this drug work.\""}, {"id": "d", "text": "\"I cannot get ketoacidosis if my glucose stays normal.\""}]'::jsonb, '["a"]', 'With SGLT2 inhibitors, glucose leaves through the urine, and there is risk of UTI, genital infection, dehydration, and euglycemic DKA. Limiting fluids would worsen dehydration risk, and DKA can occur with normal glucose.'),
  ('medications', 50, 'A client who takes metformin is scheduled for a CT scan with IV contrast. Which action by the nurse is appropriate?', '[{"id": "a", "text": "Give the usual dose just before the scan"}, {"id": "b", "text": "Hold the drug per policy and review the eGFR"}, {"id": "c", "text": "Double the next dose after the scan is done"}, {"id": "d", "text": "Give the dose with extra food before the scan"}]'::jsonb, '["b"]', 'Metformin is held for surgery or contrast per policy, with eGFR monitoring because of lactic acidosis risk. Giving the usual or a doubled dose ignores this rule.'),
  ('adrenal', 1, 'A nursing student is reviewing adrenal gland anatomy. Which statement about the adrenal medulla is correct?', '[{"id": "a", "text": "It produces cortisol under the control of ACTH"}, {"id": "b", "text": "It produces aldosterone under the control of ACTH"}, {"id": "c", "text": "It produces catecholamines and is not regulated by ACTH"}, {"id": "d", "text": "It produces androgens and is the outer layer of the gland"}]'::jsonb, '["c"]', 'The inner medulla produces catecholamines (epinephrine, norepinephrine) and is not regulated by ACTH. Cortisol, aldosterone, and androgens come from the outer cortex.'),
  ('adrenal', 2, 'The adrenal cortex produces steroid hormones in response to ACTH. Which gland releases ACTH?', '[{"id": "a", "text": "Anterior pituitary"}, {"id": "b", "text": "Adrenal medulla"}, {"id": "c", "text": "Thyroid gland"}, {"id": "d", "text": "Pancreas"}]'::jsonb, '["a"]', 'The adrenal cortex produces steroid hormones and is regulated by ACTH from the anterior pituitary. The adrenal medulla produces catecholamines and is not regulated by ACTH.'),
  ('adrenal', 3, 'A client asks the nurse how aldosterone affects blood pressure. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It makes the kidneys release sodium, which lowers blood pressure.\""}, {"id": "b", "text": "\"It makes the kidneys hold sodium, and water follows to raise pressure.\""}, {"id": "c", "text": "\"It raises blood glucose, which pulls water into the blood vessels.\""}, {"id": "d", "text": "\"It makes the kidneys hold potassium, which raises blood pressure.\""}]'::jsonb, '["b"]', 'Aldosterone tells the kidneys to hold on to sodium; where sodium goes, water follows, increasing blood volume and blood pressure. Raising blood glucose is a function of cortisol, not aldosterone.'),
  ('adrenal', 4, 'Which hormone of the adrenal cortex raises blood glucose and suppresses the immune system?', '[{"id": "a", "text": "Aldosterone"}, {"id": "b", "text": "Epinephrine"}, {"id": "c", "text": "Androgens"}, {"id": "d", "text": "Cortisol"}]'::jsonb, '["d"]', 'Cortisol is a glucocorticoid from the cortex that raises blood glucose and suppresses the immune system. Aldosterone regulates sodium, potassium, and water.'),
  ('adrenal', 5, 'A client is diagnosed with Cushing''s disease. The client asks what caused the condition. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Autoimmune destruction of your adrenal cortex.\""}, {"id": "b", "text": "\"A pituitary adenoma producing too much ACTH.\""}, {"id": "c", "text": "\"Long-term use of prescribed steroid medications.\""}, {"id": "d", "text": "\"A tumor in the adrenal medulla making epinephrine.\""}]'::jsonb, '["b"]', 'Cushing''s disease is caused by a pituitary adenoma that produces too much ACTH, which overstimulates the adrenal cortex. Long-term steroid use causes Cushing''s syndrome, not Cushing''s disease.'),
  ('adrenal', 6, 'A client who has taken high-dose steroids for many years develops a moon face, buffalo hump, and purple striae. Which condition does the nurse recognize?', '[{"id": "a", "text": "Cushing''s disease"}, {"id": "b", "text": "Addison''s disease"}, {"id": "c", "text": "Cushing''s syndrome"}, {"id": "d", "text": "Adrenal crisis"}]'::jsonb, '["c"]', 'Cushing''s syndrome is too much cortisol from any cause, including long-term steroid use. Cushing''s disease is the specific type caused by a pituitary adenoma producing too much ACTH.'),
  ('adrenal', 7, 'A client with small-cell lung cancer develops high cortisol from an ectopic ACTH-producing tumor. How should this condition be classified?', '[{"id": "a", "text": "Cushing''s syndrome"}, {"id": "b", "text": "Cushing''s disease"}, {"id": "c", "text": "Addison''s disease"}, {"id": "d", "text": "Adrenal insufficiency"}]'::jsonb, '["a"]', 'An ectopic ACTH tumor such as small-cell lung cancer is a cause of Cushing''s syndrome. Cushing''s disease is reserved for a pituitary adenoma producing too much ACTH.'),
  ('adrenal', 8, 'The nurse is teaching a group of students about Cushing''s disease and Cushing''s syndrome. Which student statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Cushing''s disease is one specific type of Cushing''s syndrome.\""}, {"id": "b", "text": "\"Cushing''s syndrome means high cortisol from any cause.\""}, {"id": "c", "text": "\"Cushing''s disease involves a pituitary ACTH problem.\""}, {"id": "d", "text": "\"Cushing''s disease is caused by long-term steroid use.\""}]'::jsonb, '["d"]', 'Long-term steroid use causes Cushing''s syndrome; Cushing''s disease is caused by a pituitary adenoma producing too much ACTH. Disease is a pituitary ACTH problem, while syndrome is high cortisol from any cause.'),
  ('adrenal', 9, 'The nurse is assessing a client admitted with Cushing''s disease. Which group of findings does the nurse expect?', '[{"id": "a", "text": "Moon face, buffalo hump, and purple striae"}, {"id": "b", "text": "Bronze skin, salt craving, and weight loss"}, {"id": "c", "text": "Hypotension, hypoglycemia, and dehydration"}, {"id": "d", "text": "Orthostatic dizziness, fatigue, and diarrhea"}]'::jsonb, '["a"]', 'Moon face, buffalo hump, and purple striae are hallmarks of Cushing''s. Bronze skin, salt craving, weight loss, hypotension, and hypoglycemia are findings of Addison''s disease.'),
  ('adrenal', 10, 'A client with Cushing''s disease has an enlarged abdomen with thin arms and legs. The client asks why the limbs look so thin. Which explanation is accurate?', '[{"id": "a", "text": "\"Low cortisol is causing poor appetite and weight loss.\""}, {"id": "b", "text": "\"Muscle wasting from protein breakdown thins the limbs.\""}, {"id": "c", "text": "\"Fluid is shifting out of the arms and legs into the abdomen.\""}, {"id": "d", "text": "\"Low aldosterone is causing sodium and water loss in the limbs.\""}]'::jsonb, '["b"]', 'In Cushing''s, muscle wasting from protein breakdown makes the extremities look thin while weight collects in the trunk. Low cortisol and low aldosterone describe Addison''s disease.'),
  ('adrenal', 11, 'The nurse reviews laboratory results for a client with Cushing''s disease. Which combination of findings is expected?', '[{"id": "a", "text": "Low cortisol, low glucose, high potassium"}, {"id": "b", "text": "High cortisol, low glucose, high potassium"}, {"id": "c", "text": "High cortisol, high glucose, low potassium"}, {"id": "d", "text": "Low cortisol, high glucose, low potassium"}]'::jsonb, '["c"]', 'Cushing''s involves high cortisol with hyperglycemia, and potassium may go down. Low cortisol, low glucose, and high potassium describe Addison''s disease.'),
  ('adrenal', 12, 'A client with Cushing''s disease has arterial blood gases drawn. Which acid-base imbalance may occur in this condition?', '[{"id": "a", "text": "Respiratory acidosis"}, {"id": "b", "text": "Respiratory alkalosis"}, {"id": "c", "text": "Metabolic acidosis"}, {"id": "d", "text": "Metabolic alkalosis"}]'::jsonb, '["d"]', 'Metabolic alkalosis, in which the blood becomes too basic, may occur in Cushing''s. Metabolic acidosis is listed as a finding of Addison''s disease.'),
  ('adrenal', 13, 'A client with long-standing Cushing''s disease is at risk for weak bones. What is the reason for this risk?', '[{"id": "a", "text": "Cortisol is breaking down bone"}, {"id": "b", "text": "Aldosterone is pulling calcium out"}, {"id": "c", "text": "Low ACTH is weakening the bones"}, {"id": "d", "text": "Weight loss is thinning the bones"}]'::jsonb, '["a"]', 'Osteoporosis occurs in Cushing''s because excess cortisol breaks down bone. ACTH is high, not low, in Cushing''s disease, and weight loss is an Addison''s finding.'),
  ('adrenal', 14, 'A client with Cushing''s disease has a surgical incision. Which nursing concern is most directly related to excess cortisol?', '[{"id": "a", "text": "Excessive fluid loss from the wound"}, {"id": "b", "text": "Poor wound healing and infection risk"}, {"id": "c", "text": "Low blood glucose delaying healing"}, {"id": "d", "text": "Darkening of the skin near the wound"}]'::jsonb, '["b"]', 'Cortisol weakens skin, slows repair, and suppresses the immune system, causing poor wound healing and increased infection risk. Low glucose and skin darkening are Addison''s findings.'),
  ('adrenal', 15, 'A client with Cushing''s disease is admitted for evaluation. Which laboratory value should the nurse monitor closely because of the client''s excess cortisol?', '[{"id": "a", "text": "Serum calcium for hypercalcemia"}, {"id": "b", "text": "Blood glucose for hypoglycemia"}, {"id": "c", "text": "Blood glucose for hyperglycemia"}, {"id": "d", "text": "Serum potassium for hyperkalemia"}]'::jsonb, '["c"]', 'Excess cortisol raises blood glucose, so hyperglycemia is a symptom of Cushing''s. Hypoglycemia and hyperkalemia are Addison''s findings.'),
  ('adrenal', 16, 'A client with Cushing''s disease shows the nurse several large bruises from minor bumps. Which explanation is accurate?', '[{"id": "a", "text": "Low platelets from adrenal destruction"}, {"id": "b", "text": "High ACTH darkening the skin"}, {"id": "c", "text": "Thin, fragile skin from excess cortisol"}, {"id": "d", "text": "Low aldosterone causing dry skin"}]'::jsonb, '["c"]', 'Excess cortisol in Cushing''s causes thin skin and easy bruising because cortisol weakens skin. Skin darkening from high ACTH and dry skin from low aldosterone are Addison''s findings.'),
  ('adrenal', 17, 'A female client with suspected Cushing''s disease is being assessed. Which finding supports the diagnosis?', '[{"id": "a", "text": "Bronze skin and salt craving"}, {"id": "b", "text": "Weight loss and hypotension"}, {"id": "c", "text": "Dry skin and dehydration"}, {"id": "d", "text": "Hirsutism and acne"}]'::jsonb, '["d"]', 'Hirsutism (excessive hair growth, especially in females) and acne are listed symptoms of too much cortisol. Bronze skin, salt craving, weight loss, and dehydration are Addison''s findings.'),
  ('adrenal', 18, 'A client is diagnosed with Cushing''s disease from an ACTH-producing pituitary tumor. Which treatment does the nurse anticipate first?', '[{"id": "a", "text": "Transsphenoidal pituitary surgery"}, {"id": "b", "text": "Lifelong fludrocortisone therapy"}, {"id": "c", "text": "IV hydrocortisone and normal saline"}, {"id": "d", "text": "Increased sodium and fluid intake"}]'::jsonb, '["a"]', 'Cushing''s disease is treated with transsphenoidal pituitary surgery to remove the ACTH-producing tumor. IV hydrocortisone with saline treats adrenal crisis.'),
  ('adrenal', 19, 'A client has returned from transsphenoidal surgery to remove an ACTH-producing pituitary tumor. What should the nurse monitor?', '[{"id": "a", "text": "Rising cortisol and signs of hypervolemia"}, {"id": "b", "text": "Cortisol levels and signs of adrenal insufficiency"}, {"id": "c", "text": "Growing buffalo hump and purple striae"}, {"id": "d", "text": "Rising blood glucose and rising potassium"}]'::jsonb, '["b"]', 'After surgery, cortisol levels and signs of adrenal insufficiency are monitored, and temporary glucocorticoid replacement may be needed. A growing buffalo hump would be a Cushing''s finding, not the expected post-operative concern.'),
  ('adrenal', 20, 'After pituitary surgery for Cushing''s disease, a client is discharged on temporary hydrocortisone. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I may only need this medicine for a while.\""}, {"id": "b", "text": "\"Hydrocortisone replaces the cortisol I am missing.\""}, {"id": "c", "text": "\"I can stop this medicine all at once when I feel well.\""}, {"id": "d", "text": "\"Stopping it suddenly could cause an adrenal crisis.\""}]'::jsonb, '["c"]', 'Temporary glucocorticoid replacement may be needed after surgery, but steroid replacement must never be stopped abruptly because it can cause adrenal crisis.'),
  ('adrenal', 21, 'A client''s Cushing''s disease has returned after repeated treatments, and bilateral adrenalectomy is planned. Which statement about this procedure is accurate?', '[{"id": "a", "text": "It is a first-line option and needs no replacement"}, {"id": "b", "text": "It is a first-line option and needs temporary replacement"}, {"id": "c", "text": "It is a last-resort option and needs temporary replacement"}, {"id": "d", "text": "It is a last-resort option and needs lifelong replacement"}]'::jsonb, '["d"]', 'Bilateral adrenalectomy is usually a last-resort or life-saving option and requires lifelong hormone replacement. Transsphenoidal pituitary surgery is the initial treatment.'),
  ('adrenal', 22, 'A client newly diagnosed with Addison''s disease asks what usually causes it. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Usually autoimmune destruction of the adrenal cortex.\""}, {"id": "b", "text": "\"Usually a pituitary tumor making too much ACTH.\""}, {"id": "c", "text": "\"Usually long-term use of steroid medications.\""}, {"id": "d", "text": "\"Usually a lung tumor producing extra ACTH.\""}]'::jsonb, '["a"]', 'Addison''s disease is usually caused by autoimmune destruction of the adrenal cortex, resulting in low cortisol and low aldosterone. A pituitary tumor making too much ACTH causes Cushing''s disease.'),
  ('adrenal', 23, 'The nurse notes darkened, bronze-colored skin on a client with Addison''s disease. What causes this finding?', '[{"id": "a", "text": "High cortisol thinning the skin"}, {"id": "b", "text": "High ACTH stimulating the skin"}, {"id": "c", "text": "Low aldosterone drying the skin"}, {"id": "d", "text": "Low glucose darkening the skin"}]'::jsonb, '["b"]', 'Bronze skin or hyperpigmentation in Addison''s results from high ACTH stimulation and is a hallmark of the disease. Low aldosterone causes dehydration and dry skin, not darkening.'),
  ('adrenal', 24, 'The nurse reviews laboratory results for a client with Addison''s disease. Which set of findings is expected?', '[{"id": "a", "text": "Sodium high, potassium low, glucose high"}, {"id": "b", "text": "Sodium high, potassium high, glucose low"}, {"id": "c", "text": "Sodium low, potassium low, glucose high"}, {"id": "d", "text": "Sodium low, potassium high, glucose low"}]'::jsonb, '["d"]', 'In Addison''s disease everything goes down except potassium: hyponatremia, hyperkalemia, and hypoglycemia. Low potassium with high glucose fits Cushing''s.'),
  ('adrenal', 25, 'A client with Addison''s disease reports feeling dizzy and lightheaded when getting out of bed. Which finding does the nurse expect when measuring vital signs?', '[{"id": "a", "text": "Blood pressure that rises on standing"}, {"id": "b", "text": "Blood pressure that is high when lying"}, {"id": "c", "text": "Blood pressure that drops on standing"}, {"id": "d", "text": "Blood pressure unchanged on standing"}]'::jsonb, '["c"]', 'Orthostatic hypotension occurs in Addison''s disease: blood pressure drops when standing, causing dizziness or fainting. High blood pressure is a Cushing''s finding.'),
  ('adrenal', 26, 'A client with fatigue and weight loss tells the nurse, "I keep wanting to eat salty foods." Which condition is most consistent with this report?', '[{"id": "a", "text": "Addison''s disease"}, {"id": "b", "text": "Cushing''s disease"}, {"id": "c", "text": "Cushing''s syndrome"}, {"id": "d", "text": "Pituitary adenoma"}]'::jsonb, '["a"]', 'Salt craving occurs in Addison''s disease because sodium is low, and it accompanies fatigue and weight loss. Cushing''s involves weight gain in the trunk rather than weight loss.'),
  ('adrenal', 27, 'A client with Addison''s disease has a low blood glucose level. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Too much aldosterone is lowering your blood sugar.\""}, {"id": "b", "text": "\"Too much ACTH is lowering your blood sugar.\""}, {"id": "c", "text": "\"Your body is retaining too much sodium and water.\""}, {"id": "d", "text": "\"Cortisol normally helps raise your blood sugar.\""}]'::jsonb, '["d"]', 'Hypoglycemia occurs in Addison''s because cortisol normally helps raise glucose and cortisol is low. Retaining sodium and water is a feature of Cushing''s, not Addison''s.'),
  ('adrenal', 28, 'A client with Addison''s disease has a serum potassium above the normal range. The nurse understands this is mainly due to which hormone deficiency?', '[{"id": "a", "text": "Androgens"}, {"id": "b", "text": "Aldosterone"}, {"id": "c", "text": "Epinephrine"}, {"id": "d", "text": "ACTH"}]'::jsonb, '["b"]', 'Hyperkalemia occurs in Addison''s because aldosterone is low; aldosterone normally regulates potassium. ACTH is actually high in Addison''s, causing bronze skin.'),
  ('adrenal', 29, 'A client with weight loss, fatigue, and hyperpigmentation also reports frequent gastrointestinal complaints. Which complaints are consistent with Addison''s disease?', '[{"id": "a", "text": "Increased appetite and constipation"}, {"id": "b", "text": "Weight gain and abdominal bloating"}, {"id": "c", "text": "Nausea, vomiting, and abdominal pain"}, {"id": "d", "text": "Heartburn after high-sodium meals"}]'::jsonb, '["c"]', 'Nausea, vomiting, abdominal pain, and diarrhea are common GI symptoms of Addison''s disease. Addison''s causes weight loss with poor appetite rather than weight gain or increased appetite.'),
  ('adrenal', 30, 'A client with Addison''s disease is scheduled for elective surgery. Why is this client at particular risk during the surgical period?', '[{"id": "a", "text": "The body cannot make enough cortisol under stress"}, {"id": "b", "text": "The body makes too much cortisol under stress"}, {"id": "c", "text": "The body retains too much sodium under stress"}, {"id": "d", "text": "The body releases too much ACTH-driven cortisol"}]'::jsonb, '["a"]', 'Clients with Addison''s have stress intolerance because the body cannot make enough cortisol during illness, surgery, or trauma. Excess cortisol and sodium retention are features of Cushing''s.'),
  ('adrenal', 31, 'A client with Addison''s disease is prescribed hydrocortisone and fludrocortisone. The client asks what fludrocortisone does. Which response is accurate?', '[{"id": "a", "text": "\"It replaces cortisol and raises your blood sugar.\""}, {"id": "b", "text": "\"It lowers the ACTH made by your pituitary gland.\""}, {"id": "c", "text": "\"It replaces aldosterone and helps keep sodium and water.\""}, {"id": "d", "text": "\"It helps your kidneys get rid of extra sodium.\""}]'::jsonb, '["c"]', 'Fludrocortisone is mineralocorticoid replacement that replaces aldosterone and helps keep sodium and water. Hydrocortisone is the glucocorticoid that replaces cortisol.'),
  ('adrenal', 32, 'A client with Addison''s disease calls the clinic with a fever and a respiratory infection. Which instruction is most appropriate?', '[{"id": "a", "text": "Hold the steroid until the fever resolves"}, {"id": "b", "text": "Increase the steroid dose as directed for illness"}, {"id": "c", "text": "Take the usual dose every other day while ill"}, {"id": "d", "text": "Stop the steroid and drink extra water instead"}]'::jsonb, '["b"]', 'Clients with Addison''s increase the steroid dose during stress such as illness, surgery, trauma, or fever. Holding or stopping steroids can trigger adrenal crisis.'),
  ('adrenal', 33, 'A client with Addison''s disease plans to do yard work on a hot summer day. Which teaching should the nurse reinforce?', '[{"id": "a", "text": "Restrict fluids to avoid fluid overload"}, {"id": "b", "text": "Avoid salty foods to prevent hypertension"}, {"id": "c", "text": "Skip the steroid dose on days of exertion"}, {"id": "d", "text": "Maintain adequate sodium and fluid intake"}]'::jsonb, '["d"]', 'Clients with Addison''s need adequate sodium and fluids, especially with sweating, vomiting, diarrhea, or hot weather. Restricting salt or fluids would worsen sodium and water loss.'),
  ('adrenal', 34, 'The nurse is preparing a client with Addison''s disease for discharge. Which items should the nurse recommend the client carry?', '[{"id": "a", "text": "A medical alert bracelet and emergency steroid injection kit"}, {"id": "b", "text": "A glucagon kit and a portable blood pressure cuff"}, {"id": "c", "text": "A potassium supplement and a medical alert bracelet"}, {"id": "d", "text": "A sodium-free snack and a portable glucose meter"}]'::jsonb, '["a"]', 'A medical alert bracelet and emergency steroid injection kit are needed because adrenal crisis can be life-threatening. Potassium is already high in Addison''s, so a potassium supplement is not appropriate.'),
  ('adrenal', 35, 'The nurse teaches a client with Addison''s disease about daily steroid replacement. Which client statement indicates understanding?', '[{"id": "a", "text": "\"I can skip a dose if I have an upset stomach.\""}, {"id": "b", "text": "\"I will stop my steroids once my skin color improves.\""}, {"id": "c", "text": "\"I should lower my dose when I am under stress.\""}, {"id": "d", "text": "\"I will take my steroids daily and never stop suddenly.\""}]'::jsonb, '["d"]', 'Daily steroids are taken as prescribed and never stopped abruptly, because stopping suddenly can cause adrenal crisis. The dose is increased, not lowered, during stress.'),
  ('adrenal', 36, 'A client with Addison''s disease has had vomiting for two days and could not keep down steroid doses. The client is confused with a BP of 70/50 mmHg. What does the nurse suspect?', '[{"id": "a", "text": "Cushing''s syndrome"}, {"id": "b", "text": "Adrenal crisis"}, {"id": "c", "text": "Expected orthostatic change"}, {"id": "d", "text": "Excess steroid effect"}]'::jsonb, '["b"]', 'Adrenal crisis can be triggered by missed steroid doses or dehydration and presents with severe hypotension such as 70/50 mmHg, confusion, vomiting, and shock. It is an extreme emergency, not an expected orthostatic change.'),
  ('adrenal', 37, 'A client is in adrenal crisis with severe hypotension and confusion. Which treatment should the nurse prepare to give immediately?', '[{"id": "a", "text": "Oral prednisone and a high-sodium meal"}, {"id": "b", "text": "IV hydrocortisone, normal saline, and dextrose"}, {"id": "c", "text": "Oral fludrocortisone and fluid restriction"}, {"id": "d", "text": "IV potassium, normal saline, and insulin"}]'::jsonb, '["b"]', 'Adrenal crisis requires immediate IV hydrocortisone, IV normal saline, and dextrose. IV potassium with insulin is not part of this treatment, and hyperkalemia may already be present in adrenal crisis.'),
  ('adrenal', 38, 'A client is admitted in adrenal crisis. Which laboratory pattern may the nurse find?', '[{"id": "a", "text": "Hypernatremia, hypokalemia, hyperglycemia"}, {"id": "b", "text": "Hyponatremia, hypokalemia, hyperglycemia"}, {"id": "c", "text": "Hyponatremia, hyperkalemia, hypoglycemia"}, {"id": "d", "text": "Hypernatremia, hyperkalemia, hypoglycemia"}]'::jsonb, '["c"]', 'Labs in adrenal crisis may show hyponatremia, hyperkalemia, and hypoglycemia. Low potassium with high glucose is the Cushing''s pattern.'),
  ('adrenal', 39, 'The nurse reviews admission prescriptions for a client in adrenal crisis with a BP of 72/48 mmHg. Which prescription should the nurse question?', '[{"id": "a", "text": "IV hydrocortisone now"}, {"id": "b", "text": "IV normal saline bolus"}, {"id": "c", "text": "IV dextrose infusion"}, {"id": "d", "text": "Restrict IV fluids"}]'::jsonb, '["d"]', 'Adrenal crisis is shock with low cortisol and is treated with IV hydrocortisone plus fluids given fast. Restricting fluids contradicts the need for IV normal saline.'),
  ('adrenal', 40, 'A client reports fatigue and is found to have hypotension and hyponatremia. Which condition do these findings most likely indicate?', '[{"id": "a", "text": "Cushing''s disease"}, {"id": "b", "text": "Cushing''s syndrome"}, {"id": "c", "text": "Addison''s disease"}, {"id": "d", "text": "Pituitary ACTH excess"}]'::jsonb, '["c"]', 'Addison''s disease causes low cortisol and aldosterone, so sodium and water are lost, leading to hypotension and hyponatremia. Cushing''s causes sodium and water retention with hypertension.'),
  ('adrenal', 41, 'A client presents with hypertension, hyperglycemia, and hypokalemia. Which condition is most consistent with these findings?', '[{"id": "a", "text": "Cushing''s disease"}, {"id": "b", "text": "Addison''s disease"}, {"id": "c", "text": "Adrenal crisis"}, {"id": "d", "text": "Adrenal insufficiency"}]'::jsonb, '["a"]', 'In Cushing''s, volume, BP, and sugar go up while potassium may go down. Addison''s disease and adrenal crisis cause hypotension, hypoglycemia, and hyperkalemia.'),
  ('adrenal', 42, 'The nurse is assessing fluid status in a client with untreated Addison''s disease. Which volume status does the nurse expect?', '[{"id": "a", "text": "Hypervolemia from sodium retention"}, {"id": "b", "text": "Hypovolemia from sodium and water loss"}, {"id": "c", "text": "Hypervolemia from potassium retention"}, {"id": "d", "text": "Normal volume with high sodium"}]'::jsonb, '["b"]', 'Addison''s causes sodium and water loss, leading to hypovolemia and hyponatremia. Hypervolemia from sodium retention is a feature of Cushing''s.'),
  ('adrenal', 43, 'A client is recovering from surgery to remove an ACTH-producing pituitary tumor. Which findings should the nurse report as possible adrenal insufficiency?', '[{"id": "a", "text": "Hypertension and hyperglycemia"}, {"id": "b", "text": "Weight gain and purple striae"}, {"id": "c", "text": "Hypokalemia and new acne"}, {"id": "d", "text": "Hypotension and hypoglycemia"}]'::jsonb, '["d"]', 'After pituitary surgery, the nurse monitors for adrenal insufficiency, which presents with low cortisol findings such as hypotension and hypoglycemia. Hypertension, hyperglycemia, and purple striae reflect excess cortisol.'),
  ('adrenal', 44, 'A client with Addison''s disease has been taking fludrocortisone for two weeks. Which finding indicates the medication is having the intended effect?', '[{"id": "a", "text": "Serum sodium rising toward normal"}, {"id": "b", "text": "Serum potassium rising further"}, {"id": "c", "text": "Blood pressure dropping on standing"}, {"id": "d", "text": "Salt craving becoming stronger"}]'::jsonb, '["a"]', 'Fludrocortisone replaces aldosterone and helps keep sodium and water, so sodium rising toward normal shows effect. Rising potassium, orthostatic BP drops, and salt craving are findings of low aldosterone, not improvement.'),
  ('adrenal', 45, 'A client has just undergone bilateral adrenalectomy. The nurse recognizes that the client now has which condition?', '[{"id": "a", "text": "Cushing''s disease"}, {"id": "b", "text": "Cushing''s syndrome"}, {"id": "c", "text": "Ectopic ACTH excess"}, {"id": "d", "text": "Addison''s disease"}]'::jsonb, '["d"]', 'Addison''s disease (low cortisol and low aldosterone) may occur after bilateral adrenalectomy, which is why lifelong hormone replacement is required. Removing both glands does not produce excess cortisol.'),
  ('adrenal', 46, 'The nurse explains to a client why aldosterone deficiency causes low blood pressure. Which statement reflects the underlying principle?', '[{"id": "a", "text": "\"Where potassium goes, water follows.\""}, {"id": "b", "text": "\"Where glucose goes, water follows.\""}, {"id": "c", "text": "\"Where sodium goes, water follows.\""}, {"id": "d", "text": "\"Where cortisol goes, water follows.\""}]'::jsonb, '["c"]', 'Aldosterone causes sodium reabsorption, and wherever sodium goes, water follows, increasing blood volume and blood pressure. Without aldosterone, sodium and water are lost and blood pressure falls.'),
  ('adrenal', 47, 'The nurse is comparing two clients, one with Addison''s disease and one with Cushing''s disease. Which finding is a hallmark that points specifically to Addison''s disease?', '[{"id": "a", "text": "Purple striae"}, {"id": "b", "text": "Bronze skin"}, {"id": "c", "text": "Moon face"}, {"id": "d", "text": "Buffalo hump"}]'::jsonb, '["b"]', 'Bronze skin is the hallmark of Addison''s disease. Moon face, buffalo hump, and purple striae are hallmarks of Cushing''s.'),
  ('adrenal', 48, 'A client is being evaluated for an adrenal disorder. Which weight change and blood pressure pattern would suggest Addison''s disease rather than Cushing''s?', '[{"id": "a", "text": "Truncal weight gain with high blood pressure"}, {"id": "b", "text": "Truncal weight gain with low blood pressure"}, {"id": "c", "text": "Weight loss with high blood pressure"}, {"id": "d", "text": "Weight loss with low blood pressure"}]'::jsonb, '["d"]', 'Addison''s disease causes weight loss and hypotension. Truncal obesity with hypertension is the Cushing''s pattern.'),
  ('adrenal', 49, 'A client with Cushing''s disease has persistent hypertension. The client asks why the blood pressure is high. Which explanation is accurate?', '[{"id": "a", "text": "\"Sodium and water loss is raising your blood pressure.\""}, {"id": "b", "text": "\"Sodium and water retention is raising your volume and pressure.\""}, {"id": "c", "text": "\"High potassium is tightening your blood vessels.\""}, {"id": "d", "text": "\"Low blood sugar is triggering a rise in pressure.\""}]'::jsonb, '["b"]', 'In Cushing''s, sodium and water retention leads to hypervolemia and hypertension. Sodium and water loss is the Addison''s mechanism, which lowers blood pressure.'),
  ('adrenal', 50, 'The nurse assesses the skin and mucous membranes of a client with Addison''s disease. Which finding is expected, and why?', '[{"id": "a", "text": "Dry skin, from sodium and water loss"}, {"id": "b", "text": "Oily skin, from excess androgens"}, {"id": "c", "text": "Purple striae, from fragile skin"}, {"id": "d", "text": "Moist skin, from fluid retention"}]'::jsonb, '["a"]', 'In Addison''s, low aldosterone causes sodium and water loss, leading to dehydration and dry skin. Purple striae from fragile skin occur in Cushing''s.'),
  ('thyroid_structure', 1, 'A nurse is preparing to palpate a client''s thyroid gland. Between which two landmarks should the nurse expect to locate it?', '[{"id": "a", "text": "The jaw and the laryngeal prominence"}, {"id": "b", "text": "The laryngeal prominence and the suprasternal notch"}, {"id": "c", "text": "The suprasternal notch and the lower sternum"}, {"id": "d", "text": "The base of the skull and the shoulder blades"}]'::jsonb, '["b"]', 'The thyroid lies between the Adam''s apple (laryngeal prominence) and the suprasternal notch. It is not located above the laryngeal prominence near the jaw.'),
  ('thyroid_structure', 2, 'While viewing an image of the thyroid, a client asks what connects the right and left sides of the gland. Which structure should the nurse identify?', '[{"id": "a", "text": "The isthmus"}, {"id": "b", "text": "The colloid"}, {"id": "c", "text": "The follicle"}, {"id": "d", "text": "The trachea"}]'::jsonb, '["a"]', 'The thyroid is butterfly-shaped, with two lobes connected by an isthmus. The colloid is the gel-like fluid inside the follicles, not a connecting structure.'),
  ('thyroid_structure', 3, 'A client with an enlarged thyroid asks which structure in the neck the gland is wrapped around. Which response by the nurse is accurate?', '[{"id": "a", "text": "The suprasternal notch"}, {"id": "b", "text": "The trachea, or windpipe"}, {"id": "c", "text": "The laryngeal prominence"}, {"id": "d", "text": "The anterior pituitary"}]'::jsonb, '["b"]', 'The thyroid is located in the neck and is wrapped around the trachea (windpipe). The laryngeal prominence and suprasternal notch are the landmarks it lies between, not structures it wraps around.'),
  ('thyroid_structure', 4, 'A client''s thyroid biopsy report mentions follicles. The client asks what follicles are. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Cells that produce calcitonin"}, {"id": "b", "text": "Tiny sacs that store thyroid hormones"}, {"id": "c", "text": "Enzymes that convert T4 to T3"}, {"id": "d", "text": "Proteins that carry T3 in the blood"}]'::jsonb, '["b"]', 'Follicles are tiny sacs that store thyroid hormones. Calcitonin is produced by parafollicular C-cells, not by the follicles themselves.'),
  ('thyroid_structure', 5, 'Which thyroid cells are responsible for producing thyroglobulin, the protein to which iodide is attached during hormone synthesis?', '[{"id": "a", "text": "Parafollicular C-cells"}, {"id": "b", "text": "Anterior pituitary cells"}, {"id": "c", "text": "Peripheral tissue cells"}, {"id": "d", "text": "Follicular cells"}]'::jsonb, '["d"]', 'Follicular cells produce thyroglobulin protein, which thyroid peroxidase attaches iodide to. Parafollicular C-cells produce calcitonin instead.'),
  ('thyroid_structure', 6, 'A nursing student asks where inside the thyroid the hormones are actually synthesized and stored. Which response by the nurse is accurate?', '[{"id": "a", "text": "In the isthmus that connects the two lobes"}, {"id": "b", "text": "In the parafollicular C-cells between follicles"}, {"id": "c", "text": "In the colloid, a gel-like fluid inside the follicles"}, {"id": "d", "text": "In the peripheral tissues outside the gland"}]'::jsonb, '["c"]', 'Colloid is the gel-like fluid inside follicles where hormones are synthesized and stored. Peripheral tissues are where T4 is converted to T3, not where hormones are synthesized and stored.'),
  ('thyroid_structure', 7, 'A nursing student is matching thyroid cell types with their products. Which pairing is correct?', '[{"id": "a", "text": "Follicular cells — calcitonin"}, {"id": "b", "text": "Parafollicular C-cells — thyroglobulin"}, {"id": "c", "text": "Colloid — calcitonin"}, {"id": "d", "text": "Parafollicular C-cells — calcitonin"}]'::jsonb, '["d"]', 'Calcitonin is produced by the parafollicular C-cells of the thyroid. Follicular cells produce thyroglobulin, not calcitonin.'),
  ('thyroid_structure', 8, 'A client with a goiter caused by iodine deficiency asks how the thyroid gets iodine. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "Iodine from salt, eggs, and seafood is converted to iodide."}, {"id": "b", "text": "The thyroid makes its own iodine from thyroglobulin protein."}, {"id": "c", "text": "Iodine is released by the anterior pituitary along with TSH."}, {"id": "d", "text": "Iodine is made by parafollicular C-cells and sent to the colloid."}]'::jsonb, '["a"]', 'Dietary iodine from salt, eggs, and seafood is converted to iodide, which then enters follicular cells. The thyroid does not make iodine from thyroglobulin; iodide is attached to thyroglobulin.'),
  ('thyroid_structure', 9, 'Dietary iodine must be changed into which form before it is transported into the thyroid follicular cells?', '[{"id": "a", "text": "Iodide (I⁻)"}, {"id": "b", "text": "Monoiodotyrosine (MIT)"}, {"id": "c", "text": "Diiodotyrosine (DIT)"}, {"id": "d", "text": "Thyroxine (T4)"}]'::jsonb, '["a"]', 'Dietary iodine is converted to iodide (I⁻), which then enters follicular cells. MIT and DIT form later, when thyroid peroxidase attaches iodide to thyroglobulin.'),
  ('thyroid_structure', 10, 'A nursing student is studying how iodide gets into the thyroid. By which mechanism does iodide enter the follicular cells?', '[{"id": "a", "text": "The sodium-iodide symporter"}, {"id": "b", "text": "The enzyme thyroid peroxidase"}, {"id": "c", "text": "The enzyme deiodinase"}, {"id": "d", "text": "Thyroxine-binding globulin"}]'::jsonb, '["a"]', 'Iodide enters follicular cells via the sodium-iodide symporter. Thyroid peroxidase acts later, attaching iodide to thyroglobulin.'),
  ('thyroid_structure', 11, 'After iodide moves from the follicular cells into the colloid, which substance is used to oxidize it?', '[{"id": "a", "text": "Selenium"}, {"id": "b", "text": "Thyroglobulin"}, {"id": "c", "text": "Hydrogen peroxide"}, {"id": "d", "text": "Thyroxine-binding globulin"}]'::jsonb, '["c"]', 'In the colloid, iodide is oxidized using H₂O₂. Selenium is required by deiodinase for T4-to-T3 conversion, not for oxidizing iodide.'),
  ('thyroid_structure', 12, 'Which enzyme attaches iodide to thyroglobulin to begin forming thyroid hormone?', '[{"id": "a", "text": "Deiodinase"}, {"id": "b", "text": "Thyroid peroxidase"}, {"id": "c", "text": "Sodium-iodide symporter"}, {"id": "d", "text": "Thyroxine-binding globulin"}]'::jsonb, '["b"]', 'The enzyme thyroid peroxidase attaches iodide to thyroglobulin. Deiodinase is the enzyme that converts T4 to T3.'),
  ('thyroid_structure', 13, 'When two iodine atoms are attached to thyroglobulin, which molecule is formed?', '[{"id": "a", "text": "Monoiodotyrosine (MIT)"}, {"id": "b", "text": "Diiodotyrosine (DIT)"}, {"id": "c", "text": "Triiodothyronine (T3)"}, {"id": "d", "text": "Thyroxine (T4)"}]'::jsonb, '["b"]', 'Two iodines attached form DIT, while one iodine forms MIT. T3 and T4 are formed later by combining MIT and DIT molecules.'),
  ('thyroid_structure', 14, 'Which combination produces thyroxine (T4)?', '[{"id": "a", "text": "MIT + DIT, containing 4 iodine"}, {"id": "b", "text": "DIT + DIT, containing 4 iodine"}, {"id": "c", "text": "MIT + DIT, containing 3 iodine"}, {"id": "d", "text": "MIT + MIT, containing 2 iodine"}]'::jsonb, '["b"]', 'T4 is formed from DIT plus DIT and contains 4 iodine. MIT plus DIT forms T3, which contains 3 iodine.'),
  ('thyroid_structure', 15, 'Which combination produces triiodothyronine (T3)?', '[{"id": "a", "text": "DIT + DIT, containing 3 iodine"}, {"id": "b", "text": "DIT + DIT, containing 4 iodine"}, {"id": "c", "text": "MIT + MIT, containing 2 iodine"}, {"id": "d", "text": "MIT + DIT, containing 3 iodine"}]'::jsonb, '["d"]', 'T3 is formed from MIT plus DIT and contains 3 iodine. DIT plus DIT forms T4, which contains 4 iodine.'),
  ('thyroid_structure', 16, 'Which sequence correctly describes thyroid hormone synthesis?', '[{"id": "a", "text": "Iodide binds thyroglobulin, enters cells, then is oxidized to MIT/DIT"}, {"id": "b", "text": "Iodide enters cells, is oxidized, binds thyroglobulin, then forms MIT/DIT"}, {"id": "c", "text": "Iodide forms MIT/DIT, enters cells, then binds thyroglobulin in blood"}, {"id": "d", "text": "Iodide is oxidized in blood, forms T3/T4, then enters follicular cells"}]'::jsonb, '["b"]', 'Iodide enters follicular cells via the symporter, moves into the colloid and is oxidized, and then thyroid peroxidase attaches it to thyroglobulin to form MIT and DIT. Iodide does not bind thyroglobulin before it enters the cells.'),
  ('thyroid_structure', 17, 'Which enzyme converts T4 into T3?', '[{"id": "a", "text": "Deiodinase"}, {"id": "b", "text": "Thyroid peroxidase"}, {"id": "c", "text": "Sodium-iodide symporter"}, {"id": "d", "text": "Thyroglobulin"}]'::jsonb, '["a"]', 'Deiodinase, which requires selenium, converts T4 to the active T3. Thyroid peroxidase attaches iodide to thyroglobulin rather than converting T4.'),
  ('thyroid_structure', 18, 'A client has a documented selenium deficiency. Which effect on thyroid hormone physiology should the nurse anticipate?', '[{"id": "a", "text": "Reduced conversion of iodine to iodide"}, {"id": "b", "text": "Increased release of calcitonin"}, {"id": "c", "text": "Increased binding of T3 to albumin"}, {"id": "d", "text": "Reduced conversion of T4 to active T3"}]'::jsonb, '["d"]', 'Deiodinase requires selenium to convert T4 to T3, so selenium deficiency limits production of the active form. Selenium is not described as needed for converting iodine to iodide.'),
  ('thyroid_structure', 19, 'A client asks which nutrients the body needs for normal thyroid hormone production. Which response by the nurse is accurate?', '[{"id": "a", "text": "Iodine and calcium"}, {"id": "b", "text": "Selenium and calcium"}, {"id": "c", "text": "Iodine and selenium"}, {"id": "d", "text": "Calcium and albumin"}]'::jsonb, '["c"]', 'Thyroid hormone synthesis requires iodine and selenium. Calcium is the mineral regulated by calcitonin, not a requirement for hormone synthesis.'),
  ('thyroid_structure', 20, 'A nursing student asks where deiodinase converts T4 to T3. Which response by the nurse is accurate?', '[{"id": "a", "text": "In peripheral tissues"}, {"id": "b", "text": "In the anterior pituitary"}, {"id": "c", "text": "In the hypothalamus"}, {"id": "d", "text": "In the parafollicular C-cells"}]'::jsonb, '["a"]', 'T4 is converted to T3 in peripheral tissues by deiodinase. The hypothalamus and anterior pituitary release TRH and TSH, not convert T4.'),
  ('thyroid_structure', 21, 'A client asks which thyroid hormone is the active form that acts on the body''s cells. Which response by the nurse is accurate?', '[{"id": "a", "text": "T4, which is formed from T3 by deiodinase"}, {"id": "b", "text": "Thyroglobulin, which is made by follicular cells"}, {"id": "c", "text": "TSH, which is made by the thyroid follicles"}, {"id": "d", "text": "T3, which is formed from T4 by deiodinase"}]'::jsonb, '["d"]', 'Deiodinase converts T4 to T3, the active form. T4 is not formed from T3; the conversion runs from T4 to T3.'),
  ('thyroid_structure', 22, 'Which statement accurately describes how thyroid hormones travel in the blood?', '[{"id": "a", "text": "Most circulates free and is fully active."}, {"id": "b", "text": "Most is protein-bound and inactive while bound."}, {"id": "c", "text": "Most is bound and active while it is bound."}, {"id": "d", "text": "It travels unbound to any carrier protein."}]'::jsonb, '["b"]', 'Most T3/T4 in the blood is protein-bound and inactive while bound. Only the free hormone is biologically active.'),
  ('thyroid_structure', 23, 'Which proteins carry T3 and T4 in the bloodstream?', '[{"id": "a", "text": "Thyroxine-binding globulin and albumin"}, {"id": "b", "text": "Thyroglobulin and thyroid peroxidase"}, {"id": "c", "text": "Thyroxine-binding globulin and colloid"}, {"id": "d", "text": "Deiodinase and albumin"}]'::jsonb, '["a"]', 'T3/T4 travel in the blood bound to thyroxine-binding globulin (TBG) and albumin. Thyroglobulin is the protein inside the thyroid used to build hormone, not a blood carrier.'),
  ('thyroid_structure', 24, 'A nursing student states, "Once T3 binds to TBG in the blood, it can enter cells and act on DNA." Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Only T3 bound to albumin can enter cells.\""}, {"id": "b", "text": "\"Only T4 bound to TBG can act on DNA.\""}, {"id": "c", "text": "\"Only free T3 enters cells and acts on DNA.\""}, {"id": "d", "text": "\"Bound and free T3 act on DNA equally.\""}]'::jsonb, '["c"]', 'Only free T3 is biologically active and enters cells to act on DNA; protein-bound T3 is inactive. T3 bound to albumin is still protein-bound and inactive.'),
  ('thyroid_structure', 25, 'How does free T3 get into a target cell?', '[{"id": "a", "text": "It is carried into the cell bound to TBG."}, {"id": "b", "text": "It enters the cell attached to albumin."}, {"id": "c", "text": "It crosses the cell membrane via transporters."}, {"id": "d", "text": "It is converted to T4 to cross the membrane."}]'::jsonb, '["c"]', 'Free T3 crosses the cell membrane via transporters; bound T3 does not enter cells. Only free T3, not TBG-bound T3, enters cells.'),
  ('thyroid_structure', 26, 'After free T3 enters the nucleus of a cell, what does it bind to?', '[{"id": "a", "text": "Thyroxine-binding globulin in the nucleus"}, {"id": "b", "text": "Thyroglobulin stored in the nucleus"}, {"id": "c", "text": "Thyroid hormone receptors (TRs) on DNA"}, {"id": "d", "text": "TSH receptors on the cell surface"}]'::jsonb, '["c"]', 'Free T3 enters the nucleus and binds thyroid hormone receptors (TRs) on DNA. TBG is a blood carrier protein, not a nuclear receptor.'),
  ('thyroid_structure', 27, 'Once T3 has bound its receptor, the T3-receptor complex attaches to which DNA sites?', '[{"id": "a", "text": "Thyroid peroxidase sites"}, {"id": "b", "text": "Sodium-iodide symporters"}, {"id": "c", "text": "Thyroxine-binding globulin"}, {"id": "d", "text": "Thyroid response elements (TREs)"}]'::jsonb, '["d"]', 'The T3-TR complex binds thyroid response elements (TREs) on DNA. The sodium-iodide symporter brings iodide into follicular cells and is not a DNA site.'),
  ('thyroid_structure', 28, 'A client asks how thyroid hormone actually changes the body''s metabolism at the cellular level. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "T3 stays in the blood and acts only on cell surfaces."}, {"id": "b", "text": "T3 turns genes on or off so that proteins are made."}, {"id": "c", "text": "T3 is broken down into iodide that speeds up the cell."}, {"id": "d", "text": "T3 binds to TBG inside the cell to release energy."}]'::jsonb, '["b"]', 'Inside the nucleus, T3 turns genes on or off, proteins are made, and metabolic effects occur. T3 does not act only on the cell surface; free T3 enters the cell and nucleus.'),
  ('thyroid_structure', 29, 'Which sequence correctly describes how T3 produces its effects in a cell?', '[{"id": "a", "text": "Bound T3 enters the cell, binds TREs, the complex binds TRs, genes change"}, {"id": "b", "text": "Free T3 enters the cell, binds TRs, the complex binds TREs, genes change"}, {"id": "c", "text": "Free T3 binds TREs in blood, enters the cell, binds TRs, genes change"}, {"id": "d", "text": "Free T3 changes genes, binds TRs, then the complex binds TREs in blood"}]'::jsonb, '["b"]', 'Only free T3 enters cells, binds thyroid hormone receptors in the nucleus, and the T3-TR complex binds TREs to turn genes on or off. Bound T3 does not enter cells.'),
  ('thyroid_structure', 30, 'A client has an elevated serum calcium level. Which thyroid hormone acts to lower blood calcium in this situation?', '[{"id": "a", "text": "Thyroxine (T4)"}, {"id": "b", "text": "Calcitonin"}, {"id": "c", "text": "Triiodothyronine (T3)"}, {"id": "d", "text": "Thyroid-stimulating hormone"}]'::jsonb, '["b"]', 'Calcitonin, produced by the parafollicular C-cells, lowers blood calcium when levels are too high. T3 and T4 regulate metabolism, heart rate, and development rather than calcium.'),
  ('thyroid_structure', 31, 'A nursing student asks how calcitonin relates to parathyroid hormone (PTH). Which response by the nurse is accurate?', '[{"id": "a", "text": "Calcitonin stimulates the release of PTH."}, {"id": "b", "text": "Calcitonin is converted into PTH in bone."}, {"id": "c", "text": "Calcitonin and PTH both raise calcium."}, {"id": "d", "text": "Calcitonin opposes the action of PTH."}]'::jsonb, '["d"]', 'Calcitonin opposes PTH. Calcitonin lowers blood calcium, so it does not raise calcium as the distractor suggests.'),
  ('thyroid_structure', 32, 'A client with osteoporosis is prescribed calcitonin and asks how it works. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It raises blood calcium by pulling it out of bone.\""}, {"id": "b", "text": "\"It increases thyroid hormone to strengthen bone.\""}, {"id": "c", "text": "\"It lowers blood calcium by storing it in your bones.\""}, {"id": "d", "text": "\"It acts like PTH to move calcium into your blood.\""}]'::jsonb, '["c"]', 'Calcitonin lowers blood calcium by storing it in the bones and is used therapeutically for osteoporosis. It opposes PTH rather than acting like it.'),
  ('thyroid_structure', 33, 'A client with hypercalcemia is receiving calcitonin. Which finding indicates that the medication is having the intended effect?', '[{"id": "a", "text": "Serum calcium is decreasing."}, {"id": "b", "text": "Serum calcium is increasing."}, {"id": "c", "text": "Serum TSH is increasing."}, {"id": "d", "text": "Serum free T3 is increasing."}]'::jsonb, '["a"]', 'Calcitonin is used therapeutically for hypercalcemia because it lowers blood calcium. A rising calcium would indicate the drug is not achieving its effect.'),
  ('thyroid_structure', 34, 'A client asks which gland releases the hormone that tells the anterior pituitary to release TSH. Which response by the nurse is accurate?', '[{"id": "a", "text": "The hypothalamus, which releases TRH"}, {"id": "b", "text": "The thyroid, which releases TRH"}, {"id": "c", "text": "The hypothalamus, which releases T4"}, {"id": "d", "text": "The posterior pituitary, which releases TSH"}]'::jsonb, '["a"]', 'The hypothalamus releases TRH, which tells the anterior pituitary to release TSH. The thyroid releases T3 and T4, not TRH.'),
  ('thyroid_structure', 35, 'A client has a pituitary tumor that is producing excess TSH. Which laboratory pattern should the nurse expect?', '[{"id": "a", "text": "TSH elevated, T3/T4 elevated"}, {"id": "b", "text": "TSH elevated, T3/T4 decreased"}, {"id": "c", "text": "TSH decreased, T3/T4 elevated"}, {"id": "d", "text": "TSH decreased, T3/T4 decreased"}]'::jsonb, '["a"]', 'TSH tells the thyroid to produce T3 and T4, so a pituitary tumor making excess TSH causes hyperthyroidism with high TSH and high T3/T4. Low TSH with high T3/T4 is the pattern expected when the thyroid itself is overproducing.'),
  ('thyroid_structure', 36, 'A nurse is explaining the roles of T3 and T4 to a client. Which body functions do these hormones regulate?', '[{"id": "a", "text": "Blood calcium, bone storage, and PTH"}, {"id": "b", "text": "Metabolism, heart rate, and development"}, {"id": "c", "text": "Iodide uptake, oxidation, and binding"}, {"id": "d", "text": "TRH release, TSH release, and feedback"}]'::jsonb, '["b"]', 'T3 and T4 regulate metabolism, heart rate, and development. Lowering blood calcium and opposing PTH are the roles of calcitonin.'),
  ('thyroid_structure', 37, 'A client with Graves'' disease has elevated T3 and T4 levels. Which TSH result should the nurse expect, based on negative feedback?', '[{"id": "a", "text": "Increased TSH, because high T3/T4 stimulates TRH and TSH"}, {"id": "b", "text": "Increased TSH, because Graves'' disease destroys the pituitary"}, {"id": "c", "text": "Normal TSH, because feedback stops working in Graves'' disease"}, {"id": "d", "text": "Decreased TSH, because high T3/T4 suppresses TRH and TSH"}]'::jsonb, '["d"]', 'Through negative feedback, high T3/T4 suppresses TRH and TSH, so TSH falls. High T3/T4 does not stimulate TRH and TSH; low T3/T4 does.'),
  ('thyroid_structure', 38, 'A client with Hashimoto''s thyroiditis has low T3 and T4 levels. Which change in pituitary output should the nurse expect?', '[{"id": "a", "text": "TSH rises as TRH increases"}, {"id": "b", "text": "TSH falls as TRH decreases"}, {"id": "c", "text": "TSH falls as TRH increases"}, {"id": "d", "text": "TSH rises as TRH decreases"}]'::jsonb, '["a"]', 'Low T3/T4 increases TRH, so TSH rises and signals the thyroid to make more hormone. Falling TRH and TSH is the response to high T3/T4.'),
  ('thyroid_structure', 39, 'A client has damage to the anterior pituitary that results in low TSH. Which effect on the thyroid should the nurse anticipate?', '[{"id": "a", "text": "Hyperthyroidism from too little thyroid stimulation"}, {"id": "b", "text": "Hyperthyroidism from excess TSH stimulation"}, {"id": "c", "text": "Hypothyroidism from excess TSH stimulation"}, {"id": "d", "text": "Hypothyroidism from too little thyroid stimulation"}]'::jsonb, '["d"]', 'TSH tells the thyroid to produce T3 and T4, and low TSH is a cause of hypothyroidism. Excess TSH, as with a pituitary tumor, causes hyperthyroidism instead.'),
  ('thyroid_structure', 40, 'A client who lives where dietary iodine is scarce has an enlarged thyroid, fatigue, and cold intolerance. The nurse recognizes these findings as which condition?', '[{"id": "a", "text": "Hyperthyroidism with goiter from Graves'' disease"}, {"id": "b", "text": "Hyperthyroidism with goiter from a pituitary tumor"}, {"id": "c", "text": "Hypothyroidism with myxedema from excess selenium"}, {"id": "d", "text": "Hypothyroidism with goiter from iodine deficiency"}]'::jsonb, '["d"]', 'Iodine deficiency is a cause of hypothyroidism and can produce a goiter, with fatigue and cold intolerance. Graves'' disease causes hyperthyroidism with heat intolerance rather than cold intolerance.'),
  ('thyroid_structure', 41, 'A nurse is assessing a client with Hashimoto''s thyroiditis. Which findings should the nurse expect?', '[{"id": "a", "text": "Weight loss and heat intolerance"}, {"id": "b", "text": "Sweating and anxiety"}, {"id": "c", "text": "Weight gain and cold intolerance"}, {"id": "d", "text": "Exophthalmos and a fast heart"}]'::jsonb, '["c"]', 'Hashimoto''s thyroiditis is an autoimmune cause of hypothyroidism, which produces weight gain and cold intolerance. Weight loss and heat intolerance are findings of hyperthyroidism.'),
  ('thyroid_structure', 42, 'A nurse is assessing a client newly diagnosed with Graves'' disease. Which findings should the nurse expect?', '[{"id": "a", "text": "Weight gain, cold intolerance, and fatigue"}, {"id": "b", "text": "Puffy face, doughy skin, and slow heart"}, {"id": "c", "text": "Constipation, slow thinking, and fatigue"}, {"id": "d", "text": "Weight loss, heat intolerance, and sweating"}]'::jsonb, '["d"]', 'Graves'' disease causes hyperthyroidism with fast metabolism, weight loss, heat intolerance, and sweating. Weight gain and cold intolerance are findings of hypothyroidism.'),
  ('thyroid_structure', 43, 'A nurse is monitoring a client with untreated hyperthyroidism on telemetry. Which cardiac complication is this client at risk for?', '[{"id": "a", "text": "Atrial fibrillation"}, {"id": "b", "text": "Slow heart rate"}, {"id": "c", "text": "Non-pitting edema"}, {"id": "d", "text": "Periorbital edema"}]'::jsonb, '["a"]', 'Hyperthyroidism carries a risk of atrial fibrillation. A slow heart is a finding of hypothyroidism, not hyperthyroidism.'),
  ('thyroid_structure', 44, 'A client with Graves'' disease asks why the eyes appear to bulge forward. The nurse explains that this finding is called which of the following?', '[{"id": "a", "text": "Exophthalmos"}, {"id": "b", "text": "Periorbital edema"}, {"id": "c", "text": "Myxedema"}, {"id": "d", "text": "Goiter"}]'::jsonb, '["a"]', 'Exophthalmos is a finding of hyperthyroidism in Graves'' disease. Periorbital edema is the puffy face seen in hypothyroidism.'),
  ('thyroid_structure', 45, 'A client with Graves'' disease has visible swelling at the front of the neck. Which term should the nurse use to document this finding?', '[{"id": "a", "text": "Exophthalmos"}, {"id": "b", "text": "Myxedema"}, {"id": "c", "text": "Goiter"}, {"id": "d", "text": "Periorbital edema"}]'::jsonb, '["c"]', 'A goiter is an enlarged thyroid and is listed among the findings of hyperthyroidism. Exophthalmos refers to the eyes, not to neck swelling.'),
  ('thyroid_structure', 46, 'A client with hypothyroidism has noticeable puffiness around the eyes. The nurse documents this finding as which of the following?', '[{"id": "a", "text": "Exophthalmos"}, {"id": "b", "text": "Goiter"}, {"id": "c", "text": "Periorbital edema"}, {"id": "d", "text": "Atrial fibrillation"}]'::jsonb, '["c"]', 'A puffy face with periorbital edema is a finding of hypothyroidism. Exophthalmos is the bulging-eye finding of Graves'' disease.'),
  ('thyroid_structure', 47, 'When pressing on the swollen skin of a client with hypothyroidism, the nurse notes that no indentation remains and the skin feels doughy. The nurse recognizes this finding as which of the following?', '[{"id": "a", "text": "Exophthalmos"}, {"id": "b", "text": "Goiter"}, {"id": "c", "text": "Pitting edema"}, {"id": "d", "text": "Myxedema"}]'::jsonb, '["d"]', 'Myxedema is non-pitting edema with doughy skin and is a finding of hypothyroidism. Pitting edema would leave an indentation, which is not described for myxedema.'),
  ('thyroid_structure', 48, 'A client reports fatigue and feeling depressed, and the nurse notes a slow heart rate. These findings are most consistent with which condition?', '[{"id": "a", "text": "Hyperthyroidism"}, {"id": "b", "text": "Graves'' disease"}, {"id": "c", "text": "Hypothyroidism"}, {"id": "d", "text": "Excess TSH from a pituitary tumor"}]'::jsonb, '["c"]', 'Fatigue, a slow heart, and depression are findings of hypothyroidism. Graves'' disease and a TSH-secreting pituitary tumor cause hyperthyroidism with a fast heart.'),
  ('thyroid_structure', 49, 'Which set of findings in a client indicates that the T3 level is too high?', '[{"id": "a", "text": "Fatigue, slow thinking, and constipation"}, {"id": "b", "text": "Weight gain and cold intolerance"}, {"id": "c", "text": "Anxiety, fast heart, and heat intolerance"}, {"id": "d", "text": "Puffy face and doughy skin"}]'::jsonb, '["c"]', 'Signs of T3 that is too high include weight loss, sweating, a fast heart, anxiety, and heat intolerance. Fatigue, slow thinking, and constipation indicate T3 that is too low.'),
  ('thyroid_structure', 50, 'A client with low T3 levels is being assessed. Which client report is consistent with this imbalance?', '[{"id": "a", "text": "\"My heart races and I feel anxious all day.\""}, {"id": "b", "text": "\"I sweat constantly and can''t stand the heat.\""}, {"id": "c", "text": "\"My thinking feels slow and I''m constipated.\""}, {"id": "d", "text": "\"I keep losing weight even though I eat well.\""}]'::jsonb, '["c"]', 'Low T3 causes weight gain, fatigue, cold intolerance, slow thinking, and constipation. A racing heart and anxiety indicate T3 that is too high.'),
  ('insulin', 1, 'A client receives regular insulin subcutaneously at 0730 before breakfast. During which time period is the client at greatest risk for hypoglycemia?', '[{"id": "a", "text": "0745 to 0800"}, {"id": "b", "text": "0930 to 1130"}, {"id": "c", "text": "1330 to 1530"}, {"id": "d", "text": "1930 to 2130"}]'::jsonb, '["b"]', 'Regular insulin peaks about 2-4 hours after administration, which is when hypoglycemia risk is highest; 0930-1130 is 2-4 hours after 0730. 0745-0800 is too early for the regular insulin peak.'),
  ('insulin', 2, 'A client receives NPH insulin subcutaneously at 0700. At which time should the nurse be most alert for signs of hypoglycemia?', '[{"id": "a", "text": "0730"}, {"id": "b", "text": "0900"}, {"id": "c", "text": "1500"}, {"id": "d", "text": "0700 the next day"}]'::jsonb, '["c"]', 'NPH usually peaks about 4-12 hours after administration, the time of highest hypoglycemia risk; 1500 is 8 hours after the dose. 0900 is only 2 hours after injection, which reflects the regular insulin peak, not NPH.'),
  ('insulin', 3, 'A client who takes NPH insulin each evening at 2100 is receiving discharge teaching. Which client statement indicates understanding?', '[{"id": "a", "text": "I need to watch for low blood sugar during the night."}, {"id": "b", "text": "My risk for low blood sugar is highest right after the shot."}, {"id": "c", "text": "My evening insulin cannot cause low blood sugar."}, {"id": "d", "text": "I only need to watch for low blood sugar before lunch."}]'::jsonb, '["a"]', 'With evening NPH, the nurse watches for possible overnight hypoglycemia because NPH peaks hours after the dose. The risk is not highest immediately after injection, since NPH peaks about 4-12 hours later.'),
  ('insulin', 4, 'A nurse is teaching a client who will begin taking NPH insulin every morning. Which instruction is most appropriate?', '[{"id": "a", "text": "Your risk of low blood sugar is greatest within 15 minutes."}, {"id": "b", "text": "You may skip lunch if you are not hungry."}, {"id": "c", "text": "Low blood sugar from this insulin happens only overnight."}, {"id": "d", "text": "Watch for low blood sugar later in the day."}]'::jsonb, '["d"]', 'For morning NPH, the nurse watches for hypoglycemia later in the day because NPH peaks about 4-12 hours after administration, and meals and snacks must be eaten as scheduled. Overnight hypoglycemia is the concern with evening NPH, not morning NPH.'),
  ('insulin', 5, 'A client is prescribed insulin lispro before breakfast. The nurse learns the breakfast trays will arrive in 45 minutes. What should the nurse do?', '[{"id": "a", "text": "Give the lispro now so it is working when the tray arrives"}, {"id": "b", "text": "Give the lispro when the tray is available or within 15 minutes of eating"}, {"id": "c", "text": "Give the lispro 2 hours after the client finishes eating"}, {"id": "d", "text": "Give the lispro 30 minutes before the tray is expected to arrive"}]'::jsonb, '["b"]', 'Rapid-acting insulin such as lispro is given only when the meal is available or within 15 minutes before eating to prevent hypoglycemia. Giving it 30 minutes before the meal is the timing for subcutaneous regular insulin, not rapid-acting insulin.'),
  ('insulin', 6, 'A client is prescribed subcutaneous regular insulin before lunch. Lunch will be served at 1200. At what time should the nurse administer the insulin?', '[{"id": "a", "text": "1000"}, {"id": "b", "text": "1155"}, {"id": "c", "text": "1130"}, {"id": "d", "text": "1400"}]'::jsonb, '["c"]', 'Subcutaneous regular insulin is given about 30 minutes before meals to prevent hypoglycemia, so 1130 is correct for a 1200 meal. Giving it within minutes of the meal is the timing for rapid-acting insulin.'),
  ('insulin', 7, 'A client receives insulin aspart at 0800 with breakfast. The nurse expects the effect of this insulin to last until approximately which time?', '[{"id": "a", "text": "1100 to 1300"}, {"id": "b", "text": "0815 to 0830"}, {"id": "c", "text": "2000 to 2200"}, {"id": "d", "text": "0800 the next morning"}]'::jsonb, '["a"]', 'Aspart is a rapid-acting insulin that lasts about 3-5 hours, so its effect ends around 1100-1300. Coverage lasting about 24 hours describes long-acting insulin, not rapid-acting insulin.'),
  ('insulin', 8, 'A client in diabetic ketoacidosis (DKA) has a prescription for a continuous IV insulin infusion. Which insulin should the nurse add to the IV bag?', '[{"id": "a", "text": "NPH insulin"}, {"id": "b", "text": "Insulin glargine"}, {"id": "c", "text": "Insulin detemir"}, {"id": "d", "text": "Regular insulin"}]'::jsonb, '["d"]', 'Regular insulin is the standard IV insulin, especially for DKA treatment. NPH, glargine, and detemir are for subcutaneous use only and must never be given IV.'),
  ('insulin', 9, 'A client with diabetic ketoacidosis (DKA) on an IV regular insulin infusion has a blood glucose of 420 mg/dL at 0800. Which 0900 blood glucose reflects the expected rate of decrease?', '[{"id": "a", "text": "400 mg/dL"}, {"id": "b", "text": "355 mg/dL"}, {"id": "c", "text": "250 mg/dL"}, {"id": "d", "text": "180 mg/dL"}]'::jsonb, '["b"]', 'In DKA, blood glucose should decrease gradually, about 50-75 mg/dL per hour; a drop from 420 to 355 is 65 mg/dL. A drop to 250 mg/dL is 170 mg/dL in one hour, which is too fast and increases the risk for complications.'),
  ('insulin', 10, 'A client with diabetic ketoacidosis (DKA) receiving IV regular insulin has a blood glucose that fell from 480 mg/dL to 300 mg/dL in 1 hour. How should the nurse interpret this finding?', '[{"id": "a", "text": "The glucose is falling at the expected goal rate"}, {"id": "b", "text": "The glucose is falling too slowly to be effective"}, {"id": "c", "text": "The glucose is falling too fast, raising complication risk"}, {"id": "d", "text": "The glucose change is not significant during DKA"}]'::jsonb, '["c"]', 'A drop of 180 mg/dL in one hour exceeds the gradual goal of about 50-75 mg/dL per hour, and a drop that is too fast creates risk for complications. It is not the expected goal rate, which is much more gradual.'),
  ('insulin', 11, 'A client with diabetic ketoacidosis (DKA) on an IV regular insulin infusion has a blood glucose that decreased from 390 mg/dL to 375 mg/dL over 1 hour. What does the nurse anticipate?', '[{"id": "a", "text": "The insulin infusion may need adjustment"}, {"id": "b", "text": "The infusion should continue unchanged"}, {"id": "c", "text": "The insulin should be changed to IV NPH"}, {"id": "d", "text": "The insulin infusion should be stopped"}]'::jsonb, '["a"]', 'A 15 mg/dL decrease is less than the goal of about 50-75 mg/dL per hour, and if glucose does not decrease enough, the insulin infusion may need adjustment. NPH can never be given IV.'),
  ('insulin', 12, 'While preparing a dose of NPH insulin, the nurse notes the insulin in the vial appears cloudy. What is the nurse''s best action?', '[{"id": "a", "text": "Discard the vial and obtain a new one"}, {"id": "b", "text": "Shake the vial firmly to dissolve the cloudiness"}, {"id": "c", "text": "Return the vial to the pharmacy as contaminated"}, {"id": "d", "text": "Gently roll the vial until it is uniformly cloudy"}]'::jsonb, '["d"]', 'A cloudy appearance is normal for NPH; the vial is gently rolled to mix the insulin evenly so it looks uniformly cloudy before administration. Discarding cloudy insulin applies to regular and rapid-acting insulin, not NPH.'),
  ('insulin', 13, 'Before drawing up a dose, the nurse notices that a vial of regular insulin appears cloudy. What should the nurse do?', '[{"id": "a", "text": "Roll the vial gently until the insulin looks uniform"}, {"id": "b", "text": "Do not use the vial and follow facility policy"}, {"id": "c", "text": "Shake the vial to redistribute the contents evenly"}, {"id": "d", "text": "Warm the vial in hot water and then recheck it"}]'::jsonb, '["b"]', 'Regular insulin should be clear and colorless; if it is cloudy, discolored, or has particles, it should not be used and facility policy should be followed. Rolling a cloudy vial is appropriate only for NPH, which is normally cloudy.'),
  ('insulin', 14, 'A nurse is teaching a client how to prepare an NPH insulin pen. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will shake the pen hard so the insulin mixes well."}, {"id": "b", "text": "I will roll the pen gently between my palms first."}, {"id": "c", "text": "The insulin should look evenly cloudy before I inject."}, {"id": "d", "text": "It is normal for my NPH insulin to look cloudy."}]'::jsonb, '["a"]', 'NPH should be gently rolled, not shaken, because shaking can create bubbles and affect accurate dosing. Rolling the pen until the insulin is uniformly cloudy is correct technique.'),
  ('insulin', 15, 'A nursing student asks why NPH insulin is rolled rather than shaken before administration. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Shaking turns the cloudy insulin clear"}, {"id": "b", "text": "Shaking speeds up the onset of action"}, {"id": "c", "text": "Shaking can create bubbles and affect dosing"}, {"id": "d", "text": "Shaking prevents the insulin from peaking"}]'::jsonb, '["c"]', 'Shaking can create bubbles that affect accurate dosing, so NPH is gently rolled to mix it evenly. NPH is normally cloudy, so making it clear is not a goal of mixing.'),
  ('insulin', 16, 'A nurse receives a prescription to administer NPH insulin intravenously to a client with high blood glucose. What is the nurse''s best action?', '[{"id": "a", "text": "Administer the dose slowly by IV push"}, {"id": "b", "text": "Hold the dose and clarify the route with the provider"}, {"id": "c", "text": "Dilute the dose in saline and infuse it slowly"}, {"id": "d", "text": "Give the dose through the client''s insulin pump"}]'::jsonb, '["b"]', 'NPH is subcutaneous only and must never be given IV, so the nurse should clarify the order. NPH also should not be used in an insulin pump.'),
  ('insulin', 17, 'A client who uses an insulin pump asks which type of insulin is commonly used in pumps. Which insulin should the nurse identify?', '[{"id": "a", "text": "NPH insulin"}, {"id": "b", "text": "Insulin glargine"}, {"id": "c", "text": "Insulin lispro"}, {"id": "d", "text": "Insulin detemir"}]'::jsonb, '["c"]', 'Rapid-acting insulin such as lispro is commonly used as mealtime insulin and may also be used in insulin pumps. NPH should not be used in an insulin pump, and long-acting insulin is not for pump use.'),
  ('insulin', 18, 'A nurse is supervising a nursing student who is caring for a client prescribed insulin glargine. Which statement by the student requires correction?', '[{"id": "a", "text": "I will give the glargine at the same time each day."}, {"id": "b", "text": "Glargine does not have a pronounced peak."}, {"id": "c", "text": "Glargine gives basal coverage for about 24 hours."}, {"id": "d", "text": "I can mix the glargine with regular insulin in one syringe."}]'::jsonb, '["d"]', 'Long-acting insulin such as Lantus (glargine) must never be mixed with any other insulin in the same syringe. The other statements are correct: glargine has no pronounced peak, provides about 24 hours of basal coverage, and is given at the same time every day.'),
  ('insulin', 19, 'A client receives insulin glargine at 2100 each evening. Which plan regarding the client''s meals is appropriate?', '[{"id": "a", "text": "Continue regular meals; no peak-time food tray is required"}, {"id": "b", "text": "Provide a food tray 6 hours after each glargine injection"}, {"id": "c", "text": "Give the glargine only when a meal tray is at the bedside"}, {"id": "d", "text": "Hold breakfast until the glargine has reached its peak"}]'::jsonb, '["a"]', 'Long-acting insulin has no pronounced peak, so no specific peak-time food tray is required and regular meals continue as scheduled. Giving insulin only when the tray is present is the rule for rapid-acting insulin.'),
  ('insulin', 20, 'A client newly prescribed Lantus at bedtime asks, ''Do I have to eat a snack every night before bed?'' Which response by the nurse is best?', '[{"id": "a", "text": "Yes, a snack is needed nightly to cover the insulin peak."}, {"id": "b", "text": "Only if it is ordered or you are at risk for low sugar overnight."}, {"id": "c", "text": "Yes, you must eat within 15 minutes of every Lantus dose."}, {"id": "d", "text": "No, and you may also skip breakfast if your sugar is normal."}]'::jsonb, '["b"]', 'With long-acting insulin, a bedtime snack may be needed only if ordered or if the client is at risk for overnight hypoglycemia; regular meals continue as scheduled. Lantus has no pronounced peak, so a nightly snack to cover a peak is incorrect.'),
  ('insulin', 21, 'A client with diabetes reports that fasting blood glucose readings are high every morning. Which explanation by the nurse describes the dawn phenomenon?', '[{"id": "a", "text": "Long-acting insulin reaches its peak in the early morning"}, {"id": "b", "text": "Injecting insulin into the same site raises morning glucose"}, {"id": "c", "text": "The body naturally releases hormones in the early morning"}, {"id": "d", "text": "Rapid-acting insulin from dinner wears off by the morning"}]'::jsonb, '["c"]', 'In the early morning, the body naturally releases hormones that increase blood glucose to help the body wake up, causing morning hyperglycemia known as the dawn phenomenon. Long-acting insulin has no pronounced peak, so a morning peak does not explain it.'),
  ('insulin', 22, 'A client has persistent morning hyperglycemia related to the dawn phenomenon. Which insulin does the nurse recognize as helping to control fasting blood glucose?', '[{"id": "a", "text": "Insulin lispro"}, {"id": "b", "text": "Insulin aspart"}, {"id": "c", "text": "Regular insulin"}, {"id": "d", "text": "Insulin glargine"}]'::jsonb, '["d"]', 'Long-acting insulin such as glargine provides basal coverage and helps control fasting blood glucose and morning hyperglycemia related to the dawn phenomenon. Lispro and aspart are rapid-acting mealtime insulins.'),
  ('insulin', 23, 'A nurse is preparing to administer insulin into a client''s abdomen. Where should the nurse inject the insulin?', '[{"id": "a", "text": "About 2 inches away from the umbilicus"}, {"id": "b", "text": "About one-half inch from the umbilicus"}, {"id": "c", "text": "Directly next to the edge of the umbilicus"}, {"id": "d", "text": "About 1 inch away from the umbilicus"}]'::jsonb, '["a"]', 'Abdominal insulin injections are given at least 1.5-2 inches (about 5 cm) away from the umbilicus. Distances of 1 inch or less are closer than recommended.'),
  ('insulin', 24, 'A client who has been injecting insulin only into the abdomen asks about other sites. Which site should the nurse identify as approved for insulin injection?', '[{"id": "a", "text": "Inner forearm"}, {"id": "b", "text": "Back of the upper arm"}, {"id": "c", "text": "Lower calf"}, {"id": "d", "text": "Upper chest"}]'::jsonb, '["b"]', 'Approved subcutaneous insulin sites include the abdomen, thighs, buttocks, and back of the upper arms. The forearm, calf, and chest are not among the approved sites.'),
  ('insulin', 25, 'A nurse assesses a client who injects insulin into the exact same spot on the abdomen every day and notes abnormal fatty tissue under the skin at that spot. The nurse recognizes this finding as which complication?', '[{"id": "a", "text": "Dawn phenomenon"}, {"id": "b", "text": "Peak-time hypoglycemia"}, {"id": "c", "text": "Lipodystrophy"}, {"id": "d", "text": "Contaminated insulin"}]'::jsonb, '["c"]', 'Repeated injections in the same area can cause lipodystrophy, which is abnormal fat tissue under the skin. The dawn phenomenon is morning hyperglycemia from natural hormone release, not a skin finding.'),
  ('insulin', 26, 'A client with lipodystrophy at a favorite injection spot asks why blood glucose readings have become unstable. Which explanation by the nurse is best?', '[{"id": "a", "text": "The insulin must be heated before it is injected there."}, {"id": "b", "text": "The insulin loses its strength when stored in the refrigerator."}, {"id": "c", "text": "The dawn phenomenon causes all of the daily variation."}, {"id": "d", "text": "Abnormal fat tissue there can change how insulin is absorbed."}]'::jsonb, '["d"]', 'Lipodystrophy can affect how insulin is absorbed and may cause unstable blood glucose levels, so sites should be rotated. Insulin should never be heated; refrigerated insulin is simply brought to room temperature.'),
  ('insulin', 27, 'A nurse is teaching a client about rotating insulin injection sites. Which instruction is correct?', '[{"id": "a", "text": "Rotate to a new spot within the same body region each time."}, {"id": "b", "text": "Use the exact same spot each time so absorption stays even."}, {"id": "c", "text": "Rotate to a new spot only once a month to protect the skin."}, {"id": "d", "text": "Switch to a different body region with every single injection."}]'::jsonb, '["a"]', 'Injection sites should be rotated within the same body region from one injection to the next to prevent lipodystrophy and poor insulin absorption. Using the exact same spot repeatedly causes lipodystrophy.'),
  ('insulin', 28, 'A nurse removes a vial of NPH insulin from the refrigerator to prepare a dose. Which action is appropriate?', '[{"id": "a", "text": "Shake the vial vigorously to warm the insulin"}, {"id": "b", "text": "Let it reach room temperature or roll it between the palms"}, {"id": "c", "text": "Inject the insulin cold immediately after drawing it up"}, {"id": "d", "text": "Place the vial in hot water until it feels warm"}]'::jsonb, '["b"]', 'Refrigerated insulin is brought to room temperature before injecting, and cloudy insulin like NPH may be gently rolled between the palms; insulin should not be heated or shaken. Placing the vial in hot water heats the insulin, which is not allowed.'),
  ('insulin', 29, 'A nurse inspects a vial of insulin aspart and notes small particles floating in the solution. What should the nurse do?', '[{"id": "a", "text": "Roll the vial until the particles dissolve"}, {"id": "b", "text": "Shake the vial and administer the dose"}, {"id": "c", "text": "Discard the vial and obtain a new one"}, {"id": "d", "text": "Warm the vial in the palms and administer"}]'::jsonb, '["c"]', 'Rapid-acting insulin such as aspart should be clear; if it is cloudy, clumped, discolored, or has particles, it should be discarded. Rolling is used only to mix NPH, which is normally cloudy.'),
  ('insulin', 30, 'A nurse is checking the appearance of several insulin vials before administration. Which insulin is expected to appear cloudy?', '[{"id": "a", "text": "Insulin lispro"}, {"id": "b", "text": "Regular insulin"}, {"id": "c", "text": "Insulin glargine"}, {"id": "d", "text": "Humulin N"}]'::jsonb, '["d"]', 'Humulin N is an NPH insulin, and NPH is normally cloudy. Regular and rapid-acting insulins such as lispro should be clear, and long-acting glargine is also clear.'),
  ('insulin', 31, 'A client''s medication list includes Levemir. The nurse recognizes this medication as which insulin?', '[{"id": "a", "text": "Detemir, a long-acting insulin"}, {"id": "b", "text": "Glargine, a long-acting insulin"}, {"id": "c", "text": "NPH, an intermediate-acting insulin"}, {"id": "d", "text": "Aspart, a rapid-acting insulin"}]'::jsonb, '["a"]', 'Levemir is the brand name for detemir, a long-acting insulin. Lantus, not Levemir, is the brand name for glargine.'),
  ('insulin', 32, 'A client receives regular insulin subcutaneously at 1130. The nurse expects the insulin to begin working at approximately which time?', '[{"id": "a", "text": "1135 to 1145"}, {"id": "b", "text": "1200 to 1230"}, {"id": "c", "text": "1330 to 1530"}, {"id": "d", "text": "1730 to 2330"}]'::jsonb, '["b"]', 'Regular insulin has an onset of 30-60 minutes, so it begins working around 1200-1230. 1330-1530 corresponds to its 2-4 hour peak, not its onset.'),
  ('insulin', 33, 'A nurse reviews an insulin that is cloudy in appearance, is given subcutaneously only, and has an onset of 1 to 2 hours. Which insulin is the nurse reviewing?', '[{"id": "a", "text": "Insulin lispro"}, {"id": "b", "text": "Regular insulin"}, {"id": "c", "text": "NPH insulin"}, {"id": "d", "text": "Insulin glargine"}]'::jsonb, '["c"]', 'NPH is the intermediate-acting insulin that is cloudy, subcutaneous only, and has a 1-2 hour onset. Glargine is also subcutaneous only but is clear and has no peak.'),
  ('insulin', 34, 'A client prescribed insulin glargine once daily asks whether the dose can be taken at any convenient time each day. Which response by the nurse is correct?', '[{"id": "a", "text": "Take it right before each of your meals."}, {"id": "b", "text": "Take it only on days your sugar is high."}, {"id": "c", "text": "Take it within 15 minutes of your breakfast."}, {"id": "d", "text": "Take it at the same time every day."}]'::jsonb, '["d"]', 'Long-acting insulin is given once daily at the same time every day. Taking insulin within 15 minutes of a meal describes rapid-acting insulin timing.'),
  ('insulin', 35, 'A nurse reviews new insulin prescriptions for several clients. Which prescription should the nurse question?', '[{"id": "a", "text": "Insulin glargine 20 units IV now"}, {"id": "b", "text": "Regular insulin IV infusion per DKA protocol"}, {"id": "c", "text": "Insulin lispro subcutaneously with meals"}, {"id": "d", "text": "NPH insulin subcutaneously at 0700"}]'::jsonb, '["a"]', 'Long-acting insulin such as glargine is for subcutaneous use only and must never be given IV. Regular insulin is the standard IV insulin, especially for DKA treatment.'),
  ('insulin', 36, 'A nurse is reinforcing teaching with a client who uses an insulin pump. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I check how my insulin looks before I use it."}, {"id": "b", "text": "I can fill my insulin pump with NPH insulin."}, {"id": "c", "text": "I let refrigerated insulin reach room temperature."}, {"id": "d", "text": "I never heat my insulin to warm it up."}]'::jsonb, '["b"]', 'NPH insulin cannot be given IV and should not be used in an insulin pump. Checking insulin appearance and bringing refrigerated insulin to room temperature without heating are correct practices.'),
  ('insulin', 37, 'A nursing student asks what is meant by the peak time of an insulin. Which explanation by the nurse is correct?', '[{"id": "a", "text": "The time when the insulin first starts to work"}, {"id": "b", "text": "The total length of time the insulin keeps working"}, {"id": "c", "text": "The time when the insulin has its strongest effect"}, {"id": "d", "text": "The time when the insulin dose should be drawn up"}]'::jsonb, '["c"]', 'Peak time is when insulin is working at its strongest effect to lower blood glucose, which is when hypoglycemia risk is highest. The time insulin first starts working is its onset, not its peak.'),
  ('insulin', 38, 'A client is receiving scheduled insulin. Which nursing action is most important during the insulin''s peak time?', '[{"id": "a", "text": "Administer an additional insulin dose"}, {"id": "b", "text": "Hold all meals until the peak has passed"}, {"id": "c", "text": "Encourage the client to skip the next snack"}, {"id": "d", "text": "Ensure meals and snacks are eaten as scheduled"}]'::jsonb, '["d"]', 'During peak time the client is at highest risk for hypoglycemia, so meals or snacks should be eaten as scheduled during this period. Holding meals during the peak would increase the hypoglycemia risk.'),
  ('insulin', 39, 'A client asks which injection site usually gives the fastest and most consistent insulin absorption. Which site should the nurse identify?', '[{"id": "a", "text": "Abdomen"}, {"id": "b", "text": "Thigh"}, {"id": "c", "text": "Upper outer buttock"}, {"id": "d", "text": "Back of the upper arm"}]'::jsonb, '["a"]', 'The abdomen usually provides the fastest and most consistent absorption. The thighs, buttocks, and back of the upper arms are approved sites but are not described as the fastest and most consistent.'),
  ('insulin', 40, 'A nurse is comparing insulin types. Which insulin may be administered either subcutaneously or intravenously?', '[{"id": "a", "text": "NPH insulin"}, {"id": "b", "text": "Regular insulin"}, {"id": "c", "text": "Insulin glargine"}, {"id": "d", "text": "Insulin detemir"}]'::jsonb, '["b"]', 'Regular insulin can be given subcutaneously or IV. NPH, glargine, and detemir are for subcutaneous use only.'),
  ('insulin', 41, 'A nurse is reviewing a client''s insulin orders. Which insulin should the nurse identify as rapid-acting?', '[{"id": "a", "text": "Regular insulin"}, {"id": "b", "text": "NPH insulin"}, {"id": "c", "text": "Insulin glulisine"}, {"id": "d", "text": "Insulin detemir"}]'::jsonb, '["c"]', 'Lispro, aspart, and glulisine are the rapid-acting insulins. Regular insulin is short-acting, NPH is intermediate-acting, and detemir is long-acting.'),
  ('insulin', 42, 'A nurse teaches a client about using insulin lispro at mealtimes. Which client statement indicates understanding?', '[{"id": "a", "text": "I will take it about 2 hours after I finish eating."}, {"id": "b", "text": "I will take it at bedtime even if I do not eat."}, {"id": "c", "text": "I will take it once a day at the same time no matter what."}, {"id": "d", "text": "I will take it when my meal is ready or within 15 minutes of eating."}]'::jsonb, '["d"]', 'Rapid-acting insulin such as lispro is given when the meal tray is present or within 15 minutes before eating. Taking insulin once daily at the same time describes long-acting insulin.'),
  ('insulin', 43, 'A charge nurse observes a new nurse administering insulin to several clients. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Gives insulin aspart 1 hour before the meal tray is expected"}, {"id": "b", "text": "Gives subcutaneous regular insulin 30 minutes before breakfast"}, {"id": "c", "text": "Gently rolls a vial of NPH insulin before drawing up the dose"}, {"id": "d", "text": "Injects insulin 2 inches away from the client''s umbilicus"}]'::jsonb, '["a"]', 'Rapid-acting insulin such as aspart requires the meal tray to be present or given within about 15 minutes, so giving it an hour early risks hypoglycemia. Giving subcutaneous regular insulin about 30 minutes before meals is correct.'),
  ('insulin', 44, 'A nurse inspects a vial of regular insulin before administration. Which finding indicates the insulin is appropriate to use?', '[{"id": "a", "text": "Uniformly cloudy suspension"}, {"id": "b", "text": "Clear and colorless solution"}, {"id": "c", "text": "Milky with a few small particles"}, {"id": "d", "text": "Slightly discolored but clear"}]'::jsonb, '["b"]', 'Regular insulin should be clear and colorless. If it is cloudy, discolored, or has particles, it should not be used; a uniformly cloudy appearance is expected only for NPH.'),
  ('insulin', 45, 'A client who uses Lantus says, ''My insulin always looks clear. Should I roll it until it turns cloudy?'' Which response by the nurse is correct?', '[{"id": "a", "text": "Yes, roll it gently until it becomes cloudy."}, {"id": "b", "text": "Yes, shake it until it looks evenly milky."}, {"id": "c", "text": "No, clear is expected and it needs no mixing."}, {"id": "d", "text": "No, discard it because it should be cloudy."}]'::jsonb, '["c"]', 'Long-acting insulin such as Lantus is clear, and clear insulin does not need mixing. Rolling to achieve a uniformly cloudy appearance applies only to NPH.'),
  ('insulin', 46, 'A client is prescribed insulin glargine and regular insulin to be given at the same time. How should the nurse prepare these insulins?', '[{"id": "a", "text": "Draw up regular first, then glargine, in one syringe"}, {"id": "b", "text": "Draw up glargine first, then regular, in one syringe"}, {"id": "c", "text": "Dilute the glargine in saline, then add the regular"}, {"id": "d", "text": "Prepare and give each insulin in a separate syringe"}]'::jsonb, '["d"]', 'Lantus and Levemir are not to be diluted or mixed with other insulin or solutions, so glargine must be given in its own syringe. Drawing regular first does not make mixing glargine acceptable.'),
  ('insulin', 47, 'A client newly prescribed insulin glargine asks how long one dose will work. Which response by the nurse is correct?', '[{"id": "a", "text": "About 24 hours"}, {"id": "b", "text": "About 3 to 5 hours"}, {"id": "c", "text": "About 2 to 4 hours"}, {"id": "d", "text": "About 30 minutes"}]'::jsonb, '["a"]', 'Long-acting insulin such as glargine provides basal insulin coverage for about 24 hours. A duration of about 3-5 hours describes rapid-acting insulin.'),
  ('insulin', 48, 'A client asks what it means that insulin is given subcutaneously. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It is injected into the muscle"}, {"id": "b", "text": "It is injected into the fatty tissue under the skin"}, {"id": "c", "text": "It is injected directly into a vein"}, {"id": "d", "text": "It is injected into the top layer of the skin"}]'::jsonb, '["b"]', 'Subcutaneous (SQ) injection means injecting into the fatty tissue under the skin. Injection into a vein is the IV route, which is used only for specific insulins such as regular insulin.'),
  ('insulin', 49, 'A nurse is comparing the onset of several insulins. Which insulin begins working the fastest?', '[{"id": "a", "text": "NPH insulin"}, {"id": "b", "text": "Regular insulin"}, {"id": "c", "text": "Insulin aspart"}, {"id": "d", "text": "Insulin detemir"}]'::jsonb, '["c"]', 'Rapid-acting insulins such as aspart have the fastest onset and begin working very quickly. Regular insulin has a slower onset of 30-60 minutes.'),
  ('insulin', 50, 'At 1000, a nurse is caring for four clients with diabetes. Which client is at the highest risk for hypoglycemia at this time?', '[{"id": "a", "text": "Client who received insulin glargine at 2100 last night"}, {"id": "b", "text": "Client who received insulin lispro at 0400 this morning"}, {"id": "c", "text": "Client who received NPH insulin at 2000 last night"}, {"id": "d", "text": "Client who received regular insulin at 0730 this morning"}]'::jsonb, '["d"]', 'Regular insulin given at 0730 is at its 2-4 hour peak at 1000, when hypoglycemia risk is highest. Glargine has no pronounced peak, lispro lasts only about 3-5 hours, and NPH given at 2000 is beyond its 4-12 hour peak.'),
  ('diabetes', 1, 'A client newly diagnosed with diabetes asks which pancreatic hormone is released when blood glucose falls too low. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Beta cells release insulin, which raises blood glucose.\""}, {"id": "b", "text": "\"Alpha cells release glucagon, which raises blood glucose.\""}, {"id": "c", "text": "\"Alpha cells release insulin, which lowers blood glucose.\""}, {"id": "d", "text": "\"Beta cells release glucagon, which lowers blood glucose.\""}]'::jsonb, '["b"]', 'Alpha cells produce glucagon, which is released during hypoglycemia and raises blood glucose. Beta cells produce insulin, which is released during hyperglycemia and lowers blood glucose.'),
  ('diabetes', 2, 'The nurse is explaining pancreatic physiology to a client with type 1 diabetes. Which description of normal beta-cell function is correct?', '[{"id": "a", "text": "They produce insulin, which drives glucose from the blood into cells."}, {"id": "b", "text": "They produce glucagon, which raises blood glucose during hypoglycemia."}, {"id": "c", "text": "They produce amylase, which breaks carbohydrates down into glucose."}, {"id": "d", "text": "They produce insulin, which is released mainly during hypoglycemia."}]'::jsonb, '["a"]', 'Beta cells produce insulin, which is released during hyperglycemia and drives glucose from the blood into cells for energy. Glucagon comes from alpha cells, and insulin is released during hyperglycemia rather than hypoglycemia.'),
  ('diabetes', 3, 'A client with pancreatic disease has difficulty digesting dietary fats. The nurse recognizes this is related to reduced secretion of which pancreatic enzyme?', '[{"id": "a", "text": "Amylase"}, {"id": "b", "text": "Protease"}, {"id": "c", "text": "Lipase"}, {"id": "d", "text": "Glucagon"}]'::jsonb, '["c"]', 'Lipase breaks down fats into lipids (fatty acids). Amylase breaks down carbohydrates, protease breaks down proteins, and glucagon is an alpha-cell hormone rather than an exocrine enzyme.'),
  ('diabetes', 4, 'The nurse is teaching a nursing student about the exocrine pancreas. Which pairing of pancreatic enzyme and digestive end product is correct?', '[{"id": "a", "text": "Amylase — fatty acids"}, {"id": "b", "text": "Lipase — amino acids"}, {"id": "c", "text": "Protease — glucose"}, {"id": "d", "text": "Protease — amino acids"}]'::jsonb, '["d"]', 'Protease breaks down proteins into amino acids. Amylase produces glucose from carbohydrates, and lipase produces fatty acids from fats.'),
  ('diabetes', 5, 'A client asks how pancreatic digestive enzymes reach the food that has been eaten. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"They enter the duodenum through the ductus pancreaticus.\""}, {"id": "b", "text": "\"They enter the bloodstream directly from the alpha cells.\""}, {"id": "c", "text": "\"They enter the liver directly from the beta cells.\""}, {"id": "d", "text": "\"They enter the stomach directly through the gastric lining.\""}]'::jsonb, '["a"]', 'The exocrine enzymes amylase, lipase, and protease are released through the ductus pancreaticus into the duodenum. Alpha and beta cells produce the hormones glucagon and insulin, not digestive enzymes.'),
  ('diabetes', 6, 'A client''s 2-hour postprandial blood glucose is 215 mg/dL. The nurse interprets this result as falling within which range?', '[{"id": "a", "text": "Normal"}, {"id": "b", "text": "Prediabetes"}, {"id": "c", "text": "Diabetes"}, {"id": "d", "text": "Hypoglycemia"}]'::jsonb, '["c"]', 'A 2-hour postprandial value of 200 mg/dL or higher is in the diabetes range. The prediabetes range is 140–199 mg/dL, and normal is below 140 mg/dL.'),
  ('diabetes', 7, 'The nurse reviews 2-hour postprandial blood glucose results for four clients. Which result is within the normal range?', '[{"id": "a", "text": "138 mg/dL"}, {"id": "b", "text": "152 mg/dL"}, {"id": "c", "text": "185 mg/dL"}, {"id": "d", "text": "210 mg/dL"}]'::jsonb, '["a"]', 'A normal 2-hour postprandial glucose is below 140 mg/dL. Values of 152 and 185 mg/dL fall in the 140–199 prediabetes range, and 210 mg/dL is in the diabetes range.'),
  ('diabetes', 8, 'A client with diabetes asks why the provider ordered an HbA1c when daily fingerstick readings are already being recorded. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It shows your average blood glucose over the past 24 hours.\""}, {"id": "b", "text": "\"It shows your average blood glucose over the past 3 months.\""}, {"id": "c", "text": "\"It shows your average blood glucose over the past 2 weeks.\""}, {"id": "d", "text": "\"It shows your average blood glucose over the past 12 months.\""}]'::jsonb, '["b"]', 'HbA1c (glycosylated hemoglobin) reflects average blood glucose over the past 3 months. It does not reflect a single day, a 2-week period, or a full year.'),
  ('diabetes', 9, 'A client who is being treated for diabetes asks how often the HbA1c will be checked. Which interval should the nurse state?', '[{"id": "a", "text": "Every month"}, {"id": "b", "text": "Every 6 months"}, {"id": "c", "text": "Once a year"}, {"id": "d", "text": "Every 3 months"}]'::jsonb, '["d"]', 'HbA1c is checked every 3 months, matching the 3-month period of average glucose it reflects. Monthly checks are too frequent, and 6-month or yearly checks are too infrequent.'),
  ('diabetes', 10, 'A client with no history of diabetes has a screening HbA1c of 6.8%. How should the nurse interpret this result?', '[{"id": "a", "text": "Normal range"}, {"id": "b", "text": "Prediabetes range"}, {"id": "c", "text": "Diabetes range"}, {"id": "d", "text": "Hypoglycemic range"}]'::jsonb, '["c"]', 'An HbA1c of 6.5% or higher is in the diabetes range. The prediabetes range tops out at 6.4%, so 6.8% is beyond it.'),
  ('diabetes', 11, 'A client has been treated for diabetes for one year, and today''s HbA1c is 9.2%. Which evaluation by the nurse is most accurate?', '[{"id": "a", "text": "Glucose control has been within target over the past 3 months."}, {"id": "b", "text": "Glucose control has been above target over the past 3 months."}, {"id": "c", "text": "The result reflects only this morning''s fasting glucose level."}, {"id": "d", "text": "The result indicates frequent hypoglycemia over the past 3 months."}]'::jsonb, '["b"]', 'HbA1c reflects the average glucose over the past 3 months, and the diabetic target is below 7%, so 9.2% shows control above target. It is not a single fasting value, and a high result does not indicate hypoglycemia.'),
  ('diabetes', 12, 'The parent of a 12-year-old newly diagnosed with type 1 diabetes asks what caused the disease. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Excess weight made your child''s cells resistant to insulin.\""}, {"id": "b", "text": "\"Your child''s alpha cells stopped producing enough glucagon.\""}, {"id": "c", "text": "\"Inactivity and diet gradually wore out insulin production.\""}, {"id": "d", "text": "\"The immune system destroyed the cells that produce insulin.\""}]'::jsonb, '["d"]', 'Type 1 diabetes results from autoimmune destruction of beta cells, so no insulin is produced. Insulin resistance linked to obesity, inactivity, and diet describes type 2 diabetes.'),
  ('diabetes', 13, 'The nurse assesses a 14-year-old client newly diagnosed with type 1 diabetes. Which finding does the nurse expect?', '[{"id": "a", "text": "Thin build because the body is burning fat and muscle"}, {"id": "b", "text": "Overweight build associated with physical inactivity"}, {"id": "c", "text": "Gradual onset typical of adults older than 40 years"}, {"id": "d", "text": "Adequate insulin production with insulin resistance"}]'::jsonb, '["a"]', 'In type 1 diabetes the client is typically thin because the body burns fat and muscle for energy. An overweight build, onset after age 40, and insulin resistance are features of type 2 diabetes.'),
  ('diabetes', 14, 'A 52-year-old client who is obese and physically inactive is diagnosed with type 2 diabetes. Which explanation of the disease process is accurate?', '[{"id": "a", "text": "Autoimmune destruction of beta cells has stopped all insulin production."}, {"id": "b", "text": "Alpha cells are overproducing insulin in response to high blood glucose."}, {"id": "c", "text": "Insulin resistance is present along with a progressive beta-cell decline."}, {"id": "d", "text": "The pancreas has stopped releasing digestive enzymes into the duodenum."}]'::jsonb, '["c"]', 'Type 2 diabetes involves insulin resistance plus a progressive decline in beta cells, with genetics and lifestyle as causes. Autoimmune destruction of beta cells is the mechanism of type 1 diabetes.'),
  ('diabetes', 15, 'The nurse is teaching the parents of a child newly diagnosed with type 1 diabetes. Which statement by a parent indicates understanding of the treatment plan?', '[{"id": "a", "text": "\"We''ll try diet and exercise first and add insulin only if needed.\""}, {"id": "b", "text": "\"Metformin will be started first, and insulin can be added later.\""}, {"id": "c", "text": "\"Once blood sugars are normal, insulin can be stopped for good.\""}, {"id": "d", "text": "\"Our child will need insulin for life, starting right away.\""}]'::jsonb, '["d"]', 'Type 1 diabetes requires insulin immediately and lifelong. The diet and exercise → metformin → insulin ladder applies to type 2 diabetes.'),
  ('diabetes', 16, 'A client newly diagnosed with type 2 diabetes asks, "Will I have to start insulin injections now?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Not initially, but insulin may eventually be needed later.\""}, {"id": "b", "text": "\"Yes, insulin is required immediately for all types of diabetes.\""}, {"id": "c", "text": "\"No, people with type 2 diabetes never need insulin at any point.\""}, {"id": "d", "text": "\"Yes, you will need lifelong insulin injections starting today.\""}]'::jsonb, '["a"]', 'In type 2 diabetes, insulin is initially not needed, but the client may eventually need it. Immediate, lifelong insulin describes type 1 diabetes.'),
  ('diabetes', 17, 'Which client presentation is most consistent with type 2 rather than type 1 diabetes?', '[{"id": "a", "text": "An 11-year-old with a thin build who needs insulin at diagnosis"}, {"id": "b", "text": "A 48-year-old who is overweight and has an inactive lifestyle"}, {"id": "c", "text": "A 9-year-old whose beta cells were destroyed by an autoimmune process"}, {"id": "d", "text": "A 15-year-old whose body is burning fat and muscle for energy"}]'::jsonb, '["b"]', 'Type 2 diabetes usually begins in adults older than 40 and is linked to obesity and inactivity. Childhood onset, a thin build, autoimmune beta-cell destruction, and immediate insulin need point to type 1 diabetes.'),
  ('diabetes', 18, 'A client with uncontrolled hyperglycemia is admitted to the medical unit. Which set of classic findings does the nurse expect?', '[{"id": "a", "text": "Cold, clammy skin, trembling hands, and palpitations"}, {"id": "b", "text": "Decreased thirst, scant urine output, and poor appetite"}, {"id": "c", "text": "Extreme thirst, large-volume urination, and excessive hunger"}, {"id": "d", "text": "Pale skin, numbness of the lips, and diaphoresis"}]'::jsonb, '["c"]', 'The 3 Ps of hyperglycemia are polydipsia (extreme thirst), polyuria (large-volume urination), and polyphagia (excessive hunger). Cold, clammy skin, trembling, pallor, and lip numbness are signs of hypoglycemia.'),
  ('diabetes', 19, 'The nurse is assessing a client whose blood glucose has been elevated for several days. Which additional finding is expected?', '[{"id": "a", "text": "Diaphoresis"}, {"id": "b", "text": "Dry mucous membranes"}, {"id": "c", "text": "Trembling hands"}, {"id": "d", "text": "Cold, clammy skin"}]'::jsonb, '["b"]', 'Dry mucous membranes are an additional sign of hyperglycemia. Diaphoresis, trembling hands, and cold, clammy skin are signs of hypoglycemia.'),
  ('diabetes', 20, 'The nurse teaches a client about the 3 Ps of hyperglycemia. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Polydipsia means I feel extremely thirsty.\""}, {"id": "b", "text": "\"Polyuria means I urinate large volumes.\""}, {"id": "c", "text": "\"Polyphagia means I feel excessively hungry.\""}, {"id": "d", "text": "\"Polyphagia means I urinate more than usual.\""}]'::jsonb, '["d"]', 'Polyphagia means excessive hunger; increased urination is polyuria. The other statements correctly define polydipsia, polyuria, and polyphagia.'),
  ('diabetes', 21, 'A client with known hyperglycemia develops new symptoms. Which finding does the nurse recognize as a sign of severe hyperglycemia?', '[{"id": "a", "text": "Increased hunger"}, {"id": "b", "text": "Generalized fatigue"}, {"id": "c", "text": "Nausea and vomiting"}, {"id": "d", "text": "Increased thirst"}]'::jsonb, '["c"]', 'Nausea and vomiting are listed as a severe sign of hyperglycemia. Increased hunger and thirst are classic 3 P symptoms, and fatigue is a general additional sign.'),
  ('diabetes', 22, 'A client who takes insulin skipped lunch and now reports feeling shaky. Which additional findings support hypoglycemia?', '[{"id": "a", "text": "Diaphoresis, tachycardia, and sudden intense hunger"}, {"id": "b", "text": "Dry mucous membranes, polyuria, and polydipsia"}, {"id": "c", "text": "Extreme thirst, headache, and large-volume urination"}, {"id": "d", "text": "Dry mucous membranes, fatigue, and excessive urination"}]'::jsonb, '["a"]', 'Hypoglycemia causes diaphoresis, cold/clammy skin, tachycardia, and sudden intense hunger. Dry mucous membranes, thirst, and large-volume urination indicate hyperglycemia.'),
  ('diabetes', 23, 'A client with diabetes is alert and reports tingling of the lips, irritability, and shakiness. The fingerstick glucose is 58 mg/dL. What is the nurse''s first action?', '[{"id": "a", "text": "Administer D50W by IV push"}, {"id": "b", "text": "Give a sandwich with complex carbs and protein"}, {"id": "c", "text": "Give ½ cup of orange juice"}, {"id": "d", "text": "Recheck the glucose in 15 minutes before treating"}]'::jsonb, '["c"]', 'An alert client with hypoglycemia should receive 15 g of simple carbohydrate immediately, such as ½ cup of orange juice. D50W IV push is reserved for a client who is not alert, and treatment should not be delayed for a recheck.'),
  ('diabetes', 24, 'An alert client with hypoglycemia has just finished drinking ½ can of regular soda. When should the nurse recheck the blood glucose?', '[{"id": "a", "text": "In 5 minutes"}, {"id": "b", "text": "In 15 minutes"}, {"id": "c", "text": "In 30 minutes"}, {"id": "d", "text": "In 60 minutes"}]'::jsonb, '["b"]', 'The Rule of 15 calls for 15 g of carbohydrate, a 15-minute wait, and then a blood glucose recheck. Checking at 5 minutes is too early, and waiting 30–60 minutes delays further treatment.'),
  ('diabetes', 25, 'A client with diabetes is found unresponsive with a blood glucose of 40 mg/dL, and no IV access is available. Which action should the nurse take?', '[{"id": "a", "text": "Place glucose tablets between the cheek and gum"}, {"id": "b", "text": "Administer glucagon by intramuscular injection"}, {"id": "c", "text": "Give ½ cup of orange juice by mouth"}, {"id": "d", "text": "Administer the client''s scheduled insulin dose"}]'::jsonb, '["b"]', 'An unconscious client with hypoglycemia receives glucagon IM or D50W IV, not oral glucose. Oral carbohydrates are only for an alert client, and insulin would lower the glucose further.'),
  ('diabetes', 26, 'An alert client with hypoglycemia needs 15 g of simple carbohydrate. Which choice provides the appropriate amount?', '[{"id": "a", "text": "1 glucose tablet"}, {"id": "b", "text": "¼ cup of orange juice"}, {"id": "c", "text": "3–4 glucose tablets"}, {"id": "d", "text": "2 full cans of regular soda"}]'::jsonb, '["c"]', 'Three to four glucose tablets provide the 15 g of simple carbohydrate needed. One tablet and ¼ cup of juice are too little, and 2 cans of soda would over-treat the hypoglycemia.'),
  ('diabetes', 27, 'Which sequence reflects the correct treatment of hypoglycemia in an alert client?', '[{"id": "a", "text": "Check blood glucose, wait 15 minutes, then give 15 g simple carbs"}, {"id": "b", "text": "Give 15 g simple carbs, check blood glucose, then wait 15 minutes"}, {"id": "c", "text": "Wait 15 minutes, give 15 g simple carbs, then check blood glucose"}, {"id": "d", "text": "Give 15 g simple carbs, wait 15 minutes, then check blood glucose"}]'::jsonb, '["d"]', 'The Rule of 15 is to give 15 g of carbohydrate, wait 15 minutes, and then recheck blood glucose. Waiting before giving carbohydrates delays treatment of the alert hypoglycemic client.'),
  ('diabetes', 28, 'The nurse teaches a client how to manage hypoglycemia at home. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll take 3 to 4 glucose tablets when my sugar is low.\""}, {"id": "b", "text": "\"I''ll recheck my blood sugar 15 minutes after treating it.\""}, {"id": "c", "text": "\"I''ll keep eating candy until I feel completely back to normal.\""}, {"id": "d", "text": "\"I''ll drink half a can of regular soda if my sugar is low.\""}]'::jsonb, '["c"]', 'Hypoglycemia should be treated with 15 g of carbohydrate followed by a recheck in 15 minutes; it should not be over-treated. Glucose tablets, regular soda, and a 15-minute recheck are all correct.'),
  ('diabetes', 29, 'The nurse is monitoring a client who is experiencing hypoglycemia. Which finding indicates the hypoglycemia has become severe?', '[{"id": "a", "text": "Seizure activity"}, {"id": "b", "text": "Sudden hunger"}, {"id": "c", "text": "Irritability"}, {"id": "d", "text": "Palpitations"}]'::jsonb, '["a"]', 'Seizures are listed as a severe sign of hypoglycemia. Sudden hunger, irritability, and palpitations are common hypoglycemia symptoms but are not identified as severe.'),
  ('diabetes', 30, 'A client with hypoglycemia is unconscious and has a patent IV line. The provider orders dextrose 50% (D50W). How should the nurse administer this medication?', '[{"id": "a", "text": "Intramuscular injection"}, {"id": "b", "text": "Subcutaneous injection"}, {"id": "c", "text": "Oral solution"}, {"id": "d", "text": "IV push"}]'::jsonb, '["d"]', 'D50W is given by IV push for an unconscious hypoglycemic client. IM and SubQ are routes for glucagon, and oral glucose is not given to an unconscious client.'),
  ('diabetes', 31, 'A client who self-injects insulin asks which site provides the fastest absorption. Which site should the nurse identify?', '[{"id": "a", "text": "Abdomen"}, {"id": "b", "text": "Outer upper thigh"}, {"id": "c", "text": "Buttocks"}, {"id": "d", "text": "Upper arm"}]'::jsonb, '["a"]', 'The abdomen provides the fastest insulin absorption. The thigh, buttocks, and upper arm are acceptable sites, but the abdomen is the one identified as fastest.'),
  ('diabetes', 32, 'The nurse observes a client inject insulin about 1 inch from the umbilicus. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Inject within 1 inch of the navel for fastest absorption.\""}, {"id": "b", "text": "\"Move the injection 1.5–2 inches (5 cm) away from the navel.\""}, {"id": "c", "text": "\"Inject directly next to the navel to reduce discomfort.\""}, {"id": "d", "text": "\"Avoid the abdomen and use only the buttocks from now on.\""}]'::jsonb, '["b"]', 'Abdominal insulin injections should be 1.5–2 inches (5 cm) away from the umbilicus. The abdomen remains a preferred site because it has the fastest absorption, so it does not need to be avoided.'),
  ('diabetes', 33, 'A client who injects insulin has an area of abnormal, lumpy fat at one injection site. Which teaching should the nurse provide?', '[{"id": "a", "text": "\"Use only the abdomen because it absorbs the fastest.\""}, {"id": "b", "text": "\"Inject in the same spot to keep absorption consistent.\""}, {"id": "c", "text": "\"Switch to the upper arm and inject there every day.\""}, {"id": "d", "text": "\"Rotate injection sites daily to prevent lipodystrophy.\""}]'::jsonb, '["d"]', 'Repeated use of the same site causes lipodystrophy (abnormal fat deposits), so sites should be rotated daily. Using any single site repeatedly, including the abdomen or arm, continues the problem.'),
  ('diabetes', 34, 'The nurse reviews insulin injection technique with a client. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I can use the outer, upper part of my thigh.\""}, {"id": "b", "text": "\"I''ll inject the same spot daily so I don''t forget.\""}, {"id": "c", "text": "\"My buttocks are an acceptable injection site.\""}, {"id": "d", "text": "\"I''ll stay about 2 inches away from my navel.\""}]'::jsonb, '["b"]', 'Sites should be rotated daily to prevent lipodystrophy, so using the same spot every day needs correction. The outer upper thigh, buttocks, and abdomen 1.5–2 inches from the navel are appropriate.'),
  ('diabetes', 35, 'A client is newly diagnosed with type 2 diabetes. Which treatment does the nurse anticipate as the first step?', '[{"id": "a", "text": "Diet and exercise"}, {"id": "b", "text": "Metformin therapy"}, {"id": "c", "text": "Insulin injections"}, {"id": "d", "text": "Glucagon injections"}]'::jsonb, '["a"]', 'The type 2 treatment ladder begins with diet and exercise, followed by metformin and then insulin if needed. Immediate insulin is the treatment for type 1 diabetes.'),
  ('diabetes', 36, 'A client with type 2 diabetes has followed a diet and exercise plan, but blood glucose remains elevated. Which treatment does the nurse anticipate next?', '[{"id": "a", "text": "Glucagon injections"}, {"id": "b", "text": "Immediate lifelong insulin"}, {"id": "c", "text": "Metformin as an oral agent"}, {"id": "d", "text": "Increased carbohydrate intake"}]'::jsonb, '["c"]', 'After diet and exercise, metformin is the first-line oral medication for type 2 diabetes. Insulin is added only if metformin fails, and glucagon treats hypoglycemia.'),
  ('diabetes', 37, 'A client with type 2 diabetes has been taking metformin, and the HbA1c is now 8.4%. Which treatment change does the nurse anticipate?', '[{"id": "a", "text": "Adding insulin to the plan"}, {"id": "b", "text": "Stopping all medications"}, {"id": "c", "text": "Starting glucagon injections"}, {"id": "d", "text": "No change to the plan"}]'::jsonb, '["a"]', 'In type 2 diabetes, insulin is added if metformin fails, indicated by an HbA1c above 7%. An HbA1c of 8.4% is above target, so continuing unchanged or stopping therapy is inappropriate.'),
  ('diabetes', 38, 'A client with long-standing uncontrolled diabetes is diagnosed with diabetic retinopathy. How does the nurse classify this complication and its major risk?', '[{"id": "a", "text": "Macrovascular, with a risk of stroke"}, {"id": "b", "text": "Microvascular, with a risk of blindness"}, {"id": "c", "text": "Acute, with a risk of ketoacidosis"}, {"id": "d", "text": "Macrovascular, with a risk of amputation"}]'::jsonb, '["b"]', 'Diabetic retinopathy is a microvascular complication that can lead to blindness. Stroke and amputation are associated with macrovascular disease, and ketoacidosis is an acute complication.'),
  ('diabetes', 39, 'The nurse is reviewing complications of uncontrolled diabetes. Which complication is classified as macrovascular?', '[{"id": "a", "text": "Nephropathy"}, {"id": "b", "text": "Neuropathy"}, {"id": "c", "text": "Retinopathy"}, {"id": "d", "text": "Stroke"}]'::jsonb, '["d"]', 'Macrovascular complications include MI, stroke, and PVD. Nephropathy, neuropathy, and retinopathy are microvascular complications.'),
  ('diabetes', 40, 'A client with uncontrolled diabetes and peripheral neuropathy has a nonhealing foot ulcer. The nurse recognizes the client is at risk for which outcome?', '[{"id": "a", "text": "Amputation"}, {"id": "b", "text": "Lipodystrophy"}, {"id": "c", "text": "Dawn phenomenon"}, {"id": "d", "text": "Somogyi effect"}]'::jsonb, '["a"]', 'Diabetic foot ulcers can progress to amputation. Lipodystrophy results from repeated use of one injection site, and the dawn phenomenon and Somogyi effect are causes of morning hyperglycemia.'),
  ('diabetes', 41, 'A client with type 2 diabetes has extreme hyperglycemia, and laboratory tests show no ketones. The nurse suspects which acute complication?', '[{"id": "a", "text": "DKA"}, {"id": "b", "text": "Somogyi effect"}, {"id": "c", "text": "HHS"}, {"id": "d", "text": "Dawn phenomenon"}]'::jsonb, '["c"]', 'HHS occurs in type 2 diabetes with extreme hyperglycemia and no ketones. DKA occurs in type 1 diabetes and involves ketones and acidosis.'),
  ('diabetes', 42, 'The nurse is comparing two acute complications of diabetes. Which finding is present in DKA but not in HHS?', '[{"id": "a", "text": "Elevated blood glucose"}, {"id": "b", "text": "Ketones with acidosis"}, {"id": "c", "text": "Onset mainly in type 2"}, {"id": "d", "text": "Absence of ketones"}]'::jsonb, '["b"]', 'DKA, seen in type 1 diabetes, involves ketones and acidosis. HHS occurs in type 2 diabetes with extreme hyperglycemia and no ketones, so elevated glucose does not distinguish the two.'),
  ('diabetes', 43, 'A client with long-standing uncontrolled diabetes is diagnosed with nephropathy. The nurse explains that this complication affects which part of the body?', '[{"id": "a", "text": "The peripheral nerves"}, {"id": "b", "text": "The retina of the eye"}, {"id": "c", "text": "The large arteries"}, {"id": "d", "text": "The kidneys"}]'::jsonb, '["d"]', 'Nephropathy is kidney disease, a microvascular complication of diabetes. Peripheral nerve damage is neuropathy, and retinal damage is retinopathy.'),
  ('diabetes', 44, 'A client with diabetes reports fasting blood glucose readings that are high every morning. Which action best helps the nurse identify the cause?', '[{"id": "a", "text": "Increase the evening insulin dose"}, {"id": "b", "text": "Check blood glucose at 2:00–3:00 AM"}, {"id": "c", "text": "Check blood glucose only before breakfast"}, {"id": "d", "text": "Check blood glucose 2 hours after breakfast"}]'::jsonb, '["b"]', 'A 2–3 AM glucose check differentiates the dawn phenomenon from the Somogyi effect. Insulin should not be increased for morning hyperglycemia until the cause is identified.'),
  ('diabetes', 45, 'A client with high morning blood glucose has a 3:00 AM reading of 58 mg/dL. Which intervention does the nurse anticipate?', '[{"id": "a", "text": "Increase the nighttime insulin dose"}, {"id": "b", "text": "Increase the morning insulin dose"}, {"id": "c", "text": "Reduce nighttime insulin and add a bedtime snack"}, {"id": "d", "text": "Hold all insulin until the morning glucose is normal"}]'::jsonb, '["c"]', 'A low 2–3 AM glucose (below 70 mg/dL) indicates the Somogyi effect, managed by reducing nighttime insulin and adding a bedtime snack. Increasing insulin would worsen the nocturnal hypoglycemia.'),
  ('diabetes', 46, 'A client has high morning blood glucose. A 3:00 AM reading is 150 mg/dL, and the client reports no nighttime symptoms. The nurse suspects which condition?', '[{"id": "a", "text": "Dawn phenomenon"}, {"id": "b", "text": "Somogyi effect"}, {"id": "c", "text": "Nocturnal hypoglycemia"}, {"id": "d", "text": "HHS"}]'::jsonb, '["a"]', 'A normal or high glucose at 2–3 AM with morning hyperglycemia indicates the dawn phenomenon. The Somogyi effect requires a low reading (below 70 mg/dL) during the night.'),
  ('diabetes', 47, 'A client with diabetes reports nightmares, night sweats, and restlessness, along with high fasting glucose in the morning. The nurse suspects which condition?', '[{"id": "a", "text": "Dawn phenomenon"}, {"id": "b", "text": "HHS"}, {"id": "c", "text": "DKA"}, {"id": "d", "text": "Somogyi effect"}]'::jsonb, '["d"]', 'Night sweats, nightmares, and restlessness are signs of nocturnal hypoglycemia, a clue to the Somogyi effect. The dawn phenomenon causes a morning rise without any nighttime low.'),
  ('diabetes', 48, 'A client diagnosed with the dawn phenomenon asks why blood glucose rises early in the morning. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Your blood sugar drops too low overnight and then rebounds.\""}, {"id": "b", "text": "\"Early-morning hormones signal your liver to release glucose.\""}, {"id": "c", "text": "\"Your bedtime snack is too large and raises morning glucose.\""}, {"id": "d", "text": "\"Your evening insulin dose is too high and causes a rebound.\""}]'::jsonb, '["b"]', 'The dawn phenomenon is caused by a normal early-morning hormone surge (cortisol, growth hormone, epinephrine) that signals the liver to release glucose. A rebound after an overnight low describes the Somogyi effect.'),
  ('diabetes', 49, 'The nurse teaches a client with morning hyperglycemia about the dawn phenomenon and the Somogyi effect. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll track my bedtime, nighttime, and morning glucose levels.\""}, {"id": "b", "text": "\"I''ll check my glucose around 2 or 3 in the morning.\""}, {"id": "c", "text": "\"A low reading at 3 AM would point to the Somogyi effect.\""}, {"id": "d", "text": "\"Whenever my morning glucose is high, I''ll take more insulin.\""}]'::jsonb, '["d"]', 'Morning hyperglycemia does not always mean more insulin is needed; increasing insulin blindly can worsen the Somogyi effect. Tracking glucose trends and checking at 2–3 AM are correct.'),
  ('diabetes', 50, 'A client''s 3:00 AM glucose is in the normal range, but the fasting glucose is high each morning. Which management does the nurse anticipate?', '[{"id": "a", "text": "Reduce nighttime insulin and add a bedtime snack"}, {"id": "b", "text": "Treat the client for nocturnal hypoglycemia"}, {"id": "c", "text": "Adjust the evening insulin dose or its timing"}, {"id": "d", "text": "Give a glucagon injection at bedtime"}]'::jsonb, '["c"]', 'A normal 2–3 AM reading with a high morning glucose indicates the dawn phenomenon, managed by adjusting the evening insulin dose or timing. Reducing nighttime insulin and adding a bedtime snack is the management for the Somogyi effect.'),
  ('metformin', 1, 'A client newly prescribed metformin for type 2 diabetes asks how the medication works. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It raises liver glucose release and reduces insulin response.\""}, {"id": "b", "text": "\"It stimulates the pancreas to secrete more insulin each day.\""}, {"id": "c", "text": "\"It lowers liver glucose release and improves insulin response.\""}, {"id": "d", "text": "\"It replaces insulin that the pancreas can no longer produce.\""}]'::jsonb, '["c"]', 'Metformin lowers blood glucose by decreasing glucose release from the liver and improving the body''s response to insulin. It does not stimulate insulin secretion from the pancreas.'),
  ('metformin', 2, 'A client starting metformin as the only diabetes medication asks, "Will this pill make my blood sugar drop too low?" Which response by the nurse is accurate?', '[{"id": "a", "text": "\"The risk is low, because it does not increase insulin secretion.\""}, {"id": "b", "text": "\"The risk is high, because it makes the pancreas release insulin.\""}, {"id": "c", "text": "\"The risk is high, because it replaces your own insulin supply.\""}, {"id": "d", "text": "\"The risk is low, because it raises glucose release from the liver.\""}]'::jsonb, '["a"]', 'Metformin by itself has a low risk of hypoglycemia because it does not increase insulin secretion. It decreases, rather than raises, glucose release from the liver.'),
  ('metformin', 3, 'The nurse is caring for four clients with type 2 diabetes. Which client is at greatest risk for hypoglycemia?', '[{"id": "a", "text": "Client taking immediate-release metformin twice daily with meals"}, {"id": "b", "text": "Client taking extended-release metformin with the evening meal"}, {"id": "c", "text": "Client managed with diet, exercise, and metformin alone"}, {"id": "d", "text": "Client taking metformin together with glipizide"}]'::jsonb, '["d"]', 'Hypoglycemia can occur when metformin is taken with a sulfonylurea such as glipizide, which stimulates the pancreas to release more insulin. Metformin alone has a low risk of hypoglycemia regardless of formulation.'),
  ('metformin', 4, 'A client takes both metformin and glyburide and asks how glyburide differs from metformin. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Glyburide stimulates the pancreas to release more insulin.\""}, {"id": "b", "text": "\"Glyburide only decreases glucose release from the liver.\""}, {"id": "c", "text": "\"Glyburide only improves the body''s response to insulin.\""}, {"id": "d", "text": "\"Glyburide carries no added risk of low blood glucose.\""}]'::jsonb, '["a"]', 'Glyburide is a sulfonylurea, an oral type 2 medication that stimulates the pancreas to release more insulin. Decreasing liver glucose release and improving insulin response describe metformin, and sulfonylureas add hypoglycemia risk.'),
  ('metformin', 5, 'A client who has taken metformin for a year is now also prescribed insulin. Which teaching point is the priority?', '[{"id": "a", "text": "\"Stop metformin, because it cannot be taken with insulin.\""}, {"id": "b", "text": "\"Watch for signs of low blood glucose, which can now occur.\""}, {"id": "c", "text": "\"Low blood glucose is not a concern with this combination.\""}, {"id": "d", "text": "\"Take metformin on an empty stomach to boost the insulin.\""}]'::jsonb, '["b"]', 'Metformin alone rarely causes hypoglycemia, but hypoglycemia can happen when it is taken with insulin. Insulin may be added to metformin therapy, so stopping metformin is not required.'),
  ('metformin', 6, 'The nurse teaches a client about metformin. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Metformin works by making my pancreas release more insulin.\""}, {"id": "b", "text": "\"Metformin helps my body respond better to insulin.\""}, {"id": "c", "text": "\"Metformin decreases the glucose my liver releases.\""}, {"id": "d", "text": "\"Metformin is commonly the first-line pill for type 2 diabetes.\""}]'::jsonb, '["a"]', 'Metformin does not stimulate insulin secretion from the pancreas, which is why it usually does not cause hypoglycemia alone. Improving insulin response, decreasing liver glucose release, and first-line use for type 2 diabetes are correct.'),
  ('metformin', 7, 'A client with type 2 diabetes has followed a diet and exercise plan for several months, but blood glucose remains poorly controlled. Which medication plan does the nurse anticipate?', '[{"id": "a", "text": "Insulin as the first medication"}, {"id": "b", "text": "Metformin as the first-line oral agent"}, {"id": "c", "text": "A GLP-1 before any oral agent"}, {"id": "d", "text": "No medication; continue diet alone"}]'::jsonb, '["b"]', 'Metformin is started in type 2 diabetes when diet and exercise alone are not enough to control blood glucose. Insulin and additional agents such as GLP-1 come later on the treatment ladder.'),
  ('metformin', 8, 'A provider prescribes metformin for a client with type 1 diabetes. Which concern should the nurse communicate to the provider?', '[{"id": "a", "text": "Metformin will cause severe hypoglycemia when used alone."}, {"id": "b", "text": "Metformin is only effective when taken on an empty stomach."}, {"id": "c", "text": "Metformin is not effective because of absolute insulin deficiency."}, {"id": "d", "text": "Metformin stimulates beta cells to release more insulin."}]'::jsonb, '["c"]', 'Type 1 diabetes is a contraindication because metformin is not effective when there is absolute insulin deficiency. Metformin alone has a low hypoglycemia risk and does not stimulate insulin secretion.'),
  ('metformin', 9, 'The nurse is reviewing the step-by-step treatment approach for type 2 diabetes. Which sequence is correct?', '[{"id": "a", "text": "Metformin → diet and exercise → insulin → other oral agents or GLP-1"}, {"id": "b", "text": "Insulin → metformin → diet and exercise → other oral agents or GLP-1"}, {"id": "c", "text": "Diet and exercise → insulin → metformin → other oral agents or GLP-1"}, {"id": "d", "text": "Diet and exercise → metformin → other oral agents or GLP-1 → insulin"}]'::jsonb, '["d"]', 'The ladder begins with lifestyle modification, adds metformin if lifestyle is insufficient, then additional oral agents or a GLP-1, and finally insulin when HbA1c remains above 7%. Insulin is not the first or second step.'),
  ('metformin', 10, 'A client is prescribed immediate-release metformin. Which instruction should the nurse include in the teaching?', '[{"id": "a", "text": "\"Take it twice daily with meals.\""}, {"id": "b", "text": "\"Take it once daily at bedtime on an empty stomach.\""}, {"id": "c", "text": "\"Take it once daily before breakfast without food.\""}, {"id": "d", "text": "\"Take it every 6 hours around the clock.\""}]'::jsonb, '["a"]', 'Immediate-release metformin is commonly taken twice daily with meals. Taking it on an empty stomach worsens GI effects such as nausea.'),
  ('metformin', 11, 'A client''s metformin is changed to the extended-release formulation. When should the nurse instruct the client to take it?', '[{"id": "a", "text": "Twice daily with breakfast and dinner"}, {"id": "b", "text": "Once daily on an empty stomach in the morning"}, {"id": "c", "text": "Once daily with the evening meal"}, {"id": "d", "text": "Once daily at bedtime without food"}]'::jsonb, '["c"]', 'Extended-release metformin is commonly taken once daily with the evening meal. Twice daily with meals describes the immediate-release form, and taking it without food increases GI side effects.'),
  ('metformin', 12, 'A client who takes metformin each morning before eating reports nausea and an upset stomach. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Take the dose on an empty stomach.\""}, {"id": "b", "text": "\"Stop the medication until symptoms resolve.\""}, {"id": "c", "text": "\"Take the dose at bedtime without a snack.\""}, {"id": "d", "text": "\"Take the dose with or after food.\""}]'::jsonb, '["d"]', 'Nausea from metformin is worse when it is taken on an empty stomach, and taking it with or after food decreases GI side effects. These GI effects are expected and usually improve, so stopping the drug is not indicated.'),
  ('metformin', 13, 'A client starting metformin asks which side effects are most common. Which response by the nurse is accurate?', '[{"id": "a", "text": "Frequent low blood glucose"}, {"id": "b", "text": "Lactic acidosis episodes"}, {"id": "c", "text": "Nausea, diarrhea, and bloating"}, {"id": "d", "text": "Muscle pain and feeling cold"}]'::jsonb, '["c"]', 'GI effects such as dyspepsia, bloating, and diarrhea are the most common side effects of metformin. Lactic acidosis, which causes muscle pain and feeling cold, is rare, and metformin alone does not cause hypoglycemia.'),
  ('metformin', 14, 'A client who started metformin 1 week ago reports mild diarrhea and wants to stop taking it. Which response by the nurse is most appropriate?', '[{"id": "a", "text": "\"Stop it now, because diarrhea means lactic acidosis.\""}, {"id": "b", "text": "\"These GI symptoms usually improve after the first few weeks.\""}, {"id": "c", "text": "\"Take it on an empty stomach to lessen the diarrhea.\""}, {"id": "d", "text": "\"Diarrhea is rare with metformin, so look for another cause.\""}]'::jsonb, '["b"]', 'Diarrhea is a very common GI side effect, and GI symptoms usually improve after the first few weeks, especially when metformin is taken with food. Taking it on an empty stomach worsens GI effects.'),
  ('metformin', 15, 'The nurse reviews metformin side effects with a client. Which side effect does the nurse describe as very common?', '[{"id": "a", "text": "Constipation"}, {"id": "b", "text": "Hypoglycemia"}, {"id": "c", "text": "Lactic acidosis"}, {"id": "d", "text": "Diarrhea"}]'::jsonb, '["d"]', 'Diarrhea is a very common GI side effect of metformin. Constipation is possible but less common, lactic acidosis is rare, and metformin does not cause hypoglycemia by itself.'),
  ('metformin', 16, 'A client asks why kidney function must be monitored while taking metformin. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is removed by the liver, so kidney tests track liver damage.\""}, {"id": "b", "text": "\"It directly damages the kidneys in most people who take it.\""}, {"id": "c", "text": "\"Kidney tests show whether it is lowering your blood glucose.\""}, {"id": "d", "text": "\"It is removed by the kidneys and can build up if they work poorly.\""}]'::jsonb, '["d"]', 'Metformin is removed by the kidneys, and poor kidney function allows it to build up in the blood, which can lead to lactic acidosis. Effectiveness is monitored with HbA1c, not kidney tests.'),
  ('metformin', 17, 'A client''s morning metformin dose is due. The most recent eGFR is 25 mL/min/1.73 m². What is the nurse''s best action?', '[{"id": "a", "text": "Give the dose with breakfast as ordered"}, {"id": "b", "text": "Give the dose with extra oral fluids"}, {"id": "c", "text": "Withhold the dose because the eGFR is too low"}, {"id": "d", "text": "Give the dose and recheck the eGFR next week"}]'::jsonb, '["c"]', 'Metformin must not be given when the eGFR is less than 30 mL/min/1.73 m² because the drug can accumulate and cause lactic acidosis. Giving the dose with food or fluids does not remove this risk.'),
  ('metformin', 18, 'A client who has taken metformin for several years has a new eGFR of 40 mL/min/1.73 m². Which action does the nurse anticipate?', '[{"id": "a", "text": "Continue metformin with no further review"}, {"id": "b", "text": "Provider reassessment of whether metformin is still safe"}, {"id": "c", "text": "Doubling the dose to maintain glucose control"}, {"id": "d", "text": "Taking metformin on an empty stomach instead"}]'::jsonb, '["b"]', 'When eGFR falls below 45, the provider must reassess whether metformin is still safe. Continuing without review ignores the declining renal function that can cause drug buildup.'),
  ('metformin', 19, 'The nurse is planning care for a client taking metformin. Which laboratory value is most important to monitor regularly to prevent drug accumulation?', '[{"id": "a", "text": "eGFR"}, {"id": "b", "text": "Serum potassium"}, {"id": "c", "text": "Thyroid-stimulating hormone"}, {"id": "d", "text": "Platelet count"}]'::jsonb, '["a"]', 'Metformin is removed by the kidneys, so renal function, especially eGFR, must be monitored regularly. Poor kidney function lets metformin build up and cause lactic acidosis.'),
  ('metformin', 20, 'A client taking metformin reports muscle pain, weakness, difficulty breathing, and feeling cold. The nurse suspects which condition?', '[{"id": "a", "text": "Expected GI effects that will improve"}, {"id": "b", "text": "Hypoglycemia caused by metformin alone"}, {"id": "c", "text": "Lactic acidosis"}, {"id": "d", "text": "Dyspepsia from taking doses without food"}]'::jsonb, '["c"]', 'Muscle pain, weakness, difficulty breathing, and feeling cold are signs of lactic acidosis, a rare but life-threatening complication. Metformin alone does not cause hypoglycemia, and these are not GI side effects.'),
  ('metformin', 21, 'The nurse suspects lactic acidosis in a hospitalized client who takes metformin. What is the nurse''s priority action?', '[{"id": "a", "text": "Give the next dose with food"}, {"id": "b", "text": "Stop metformin and notify the provider"}, {"id": "c", "text": "Give 15 g of simple carbohydrate"}, {"id": "d", "text": "Plan to recheck the HbA1c in 3 months"}]'::jsonb, '["b"]', 'If lactic acidosis is suspected, metformin is stopped immediately and the provider or emergency care is notified. Giving the next dose would allow further drug accumulation.'),
  ('metformin', 22, 'The nurse is reviewing reports from four clients who take metformin. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Bloating and gas after the evening meal"}, {"id": "b", "text": "Mild nausea during the first week of use"}, {"id": "c", "text": "Occasional heartburn after a large meal"}, {"id": "d", "text": "Slow, irregular heartbeat and trouble breathing"}]'::jsonb, '["d"]', 'A slow or irregular heartbeat and difficulty breathing are signs of lactic acidosis, which is life-threatening. Bloating, early mild nausea, and heartburn (dyspepsia) are common GI effects.'),
  ('metformin', 23, 'The nurse is caring for four clients who take metformin. Which client has the greatest risk for lactic acidosis?', '[{"id": "a", "text": "Client who reports heavy daily alcohol use"}, {"id": "b", "text": "Client with bloating during the first week"}, {"id": "c", "text": "Client taking the extended-release form"}, {"id": "d", "text": "Client who takes each dose with meals"}]'::jsonb, '["a"]', 'Heavy alcohol use increases the risk of lactic acidosis and is a contraindication to metformin. Early bloating, the extended-release form, and taking doses with meals do not increase this risk.'),
  ('metformin', 24, 'A client with hepatic impairment has a new prescription for metformin. For which reason should the nurse question the order?', '[{"id": "a", "text": "Liver disease makes metformin cause severe hypoglycemia."}, {"id": "b", "text": "Liver disease makes metformin ineffective in type 2 diabetes."}, {"id": "c", "text": "Impaired lactate clearance raises the risk of lactic acidosis."}, {"id": "d", "text": "Liver disease causes metformin to stimulate insulin release."}]'::jsonb, '["c"]', 'Hepatic impairment is a contraindication because impaired lactate clearance leads to lactic acidosis. Metformin does not stimulate insulin release, and lack of effectiveness is the reason it is avoided in type 1 diabetes.'),
  ('metformin', 25, 'A client who takes metformin is scheduled for a CT scan with iodinated contrast. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Continue taking it as usual, including the day of the scan.\""}, {"id": "b", "text": "\"Hold your metformin 24 hours before the procedure.\""}, {"id": "c", "text": "\"Take an extra dose the night before the scan.\""}, {"id": "d", "text": "\"Switch to the extended-release form before the scan.\""}]'::jsonb, '["b"]', 'Metformin is held 24 hours before a procedure with iodinated contrast (or per facility policy) because contrast can reduce kidney function and cause drug accumulation. Continuing or adding doses increases the risk of lactic acidosis.'),
  ('metformin', 26, 'A client who takes metformin had a CT scan with iodinated contrast this morning. When can metformin be restarted?', '[{"id": "a", "text": "As soon as the client is awake and alert after the scan"}, {"id": "b", "text": "12 hours after the scan, regardless of laboratory results"}, {"id": "c", "text": "48 hours after the scan, regardless of kidney function"}, {"id": "d", "text": "48 hours after the scan, once kidney function is stable"}]'::jsonb, '["d"]', 'Metformin is restarted 48 hours after the procedure only if kidney function/eGFR is stable and the client is medically stable. Restarting sooner or without confirming kidney function risks accumulation and lactic acidosis.'),
  ('metformin', 27, 'It has been 48 hours since a client''s surgery, and the eGFR is stable. The client is still not tolerating food or fluids. What should the nurse do about the client''s home metformin?', '[{"id": "a", "text": "Restart it now because the eGFR is stable"}, {"id": "b", "text": "Keep holding it until the client eats and drinks"}, {"id": "c", "text": "Give it with IV fluids instead of with food"}, {"id": "d", "text": "Restart it at a double dose to catch up"}]'::jsonb, '["b"]', 'Before metformin is restarted, the client should be eating, drinking, and medically stable in addition to having stable kidney function. A stable eGFR alone is not enough.'),
  ('metformin', 28, 'On the morning of a scheduled CT with iodinated contrast, a client states that the usual metformin dose was taken by mistake. What is the nurse''s priority action?', '[{"id": "a", "text": "Proceed with the procedure as scheduled"}, {"id": "b", "text": "Encourage oral fluids and proceed with the scan"}, {"id": "c", "text": "Notify the provider immediately"}, {"id": "d", "text": "Hold only the next scheduled metformin dose"}]'::jsonb, '["c"]', 'If metformin was taken by mistake before a contrast procedure, the provider must be notified immediately because contrast can reduce kidney function and lead to accumulation and lactic acidosis. Proceeding without notifying the provider is unsafe.'),
  ('metformin', 29, 'A client scheduled for surgery asks why metformin must be stopped before the operation. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Surgery and fasting can reduce kidney function, so it may build up.\""}, {"id": "b", "text": "\"Metformin causes severe low blood glucose while you are fasting.\""}, {"id": "c", "text": "\"Metformin stops working as soon as you begin fasting for surgery.\""}, {"id": "d", "text": "\"Metformin stimulates insulin release during the surgical stress.\""}]'::jsonb, '["a"]', 'Surgery, fasting, dehydration, and low blood pressure can temporarily reduce kidney function, allowing metformin to accumulate and cause lactic acidosis. Metformin alone does not cause hypoglycemia or stimulate insulin release.'),
  ('metformin', 30, 'The nurse teaches a client about when metformin must be held. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I need to stop metformin before a CT with iodinated dye.\""}, {"id": "b", "text": "\"I only need to stop metformin for dye tests, not surgery.\""}, {"id": "c", "text": "\"I may restart 48 hours later if my kidneys are stable.\""}, {"id": "d", "text": "\"I''ll tell the provider if I take it by mistake before a scan.\""}]'::jsonb, '["b"]', 'Metformin must be stopped before any surgery as well as before procedures with iodinated contrast dye. The other statements about contrast, restarting at 48 hours, and reporting a mistaken dose are correct.'),
  ('metformin', 31, 'A client started metformin today and asks when the provider will evaluate how well it is working. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"An HbA1c will be checked in about 3 months.\""}, {"id": "b", "text": "\"An HbA1c will be checked in about 1 week.\""}, {"id": "c", "text": "\"An eGFR will be checked tomorrow to measure effect.\""}, {"id": "d", "text": "\"A single fasting glucose in 2 days will decide it.\""}]'::jsonb, '["a"]', 'Effectiveness is evaluated by checking the HbA1c about 3 months after starting metformin. The eGFR monitors renal safety, not glucose control.'),
  ('metformin', 32, 'The nurse teaches a client who has started metformin about monitoring its effectiveness. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll have my HbA1c checked about 3 months after starting.\""}, {"id": "b", "text": "\"For many adults, the HbA1c target is below 7 percent.\""}, {"id": "c", "text": "\"If my HbA1c stays high, another medicine may be added.\""}, {"id": "d", "text": "\"Once I''m on metformin, I''ll never need another medicine.\""}]'::jsonb, '["d"]', 'If HbA1c remains above target after metformin is optimized, the provider may add another antidiabetic medication, and insulin may eventually be needed. Checking HbA1c at 3 months with a target below 7% is correct.'),
  ('metformin', 33, 'The nurse is evaluating four adult clients who have taken metformin for 3 months. Which HbA1c result indicates the therapy is meeting the target?', '[{"id": "a", "text": "9.1%"}, {"id": "b", "text": "8.4%"}, {"id": "c", "text": "6.6%"}, {"id": "d", "text": "7.8%"}]'::jsonb, '["c"]', 'The HbA1c target for many adults is below 7%, so 6.6% meets the goal. Results of 7.8%, 8.4%, and 9.1% remain above target.'),
  ('metformin', 34, 'A client with type 2 diabetes takes metformin and a second oral agent. The HbA1c remains 9.5%, and the client has symptoms of high blood glucose. Which therapy does the nurse anticipate?', '[{"id": "a", "text": "Adding insulin"}, {"id": "b", "text": "Stopping all medications"}, {"id": "c", "text": "Diet and exercise alone"}, {"id": "d", "text": "Taking doses before meals"}]'::jsonb, '["a"]', 'Insulin is the next step when HbA1c remains above 7% despite oral medications, especially when glucose is very high and symptoms are present. Stopping medications or relying on lifestyle alone would not control the glucose.'),
  ('metformin', 35, 'A client who takes metformin is admitted with a severe infection, shock, and hypoxia. The nurse monitors closely for which serious complication?', '[{"id": "a", "text": "Dyspepsia"}, {"id": "b", "text": "Constipation"}, {"id": "c", "text": "Hypoglycemia from metformin alone"}, {"id": "d", "text": "Lactic acidosis"}]'::jsonb, '["d"]', 'Severe infection, shock, and hypoxia increase the risk of lactic acidosis in a client taking metformin. Dyspepsia and constipation are GI effects, and metformin alone does not cause hypoglycemia.'),
  ('metformin', 36, 'A client with type 1 diabetes asks whether metformin could replace insulin injections. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Yes, metformin is first-line for all types of diabetes.\""}, {"id": "b", "text": "\"No, metformin is first-line for type 2, not type 1.\""}, {"id": "c", "text": "\"Yes, if you take metformin twice daily with meals.\""}, {"id": "d", "text": "\"Yes, once your HbA1c is below 7% on insulin.\""}]'::jsonb, '["b"]', 'Metformin is first-line for type 2 diabetes, not type 1, because it is not effective with absolute insulin deficiency. Dosing schedule or HbA1c level does not change this.'),
  ('metformin', 37, 'The nurse reviews new metformin orders for four clients. Which order should the nurse question?', '[{"id": "a", "text": "Client with type 2 diabetes whose diet and exercise failed"}, {"id": "b", "text": "Client with mild diarrhea in the first week of therapy"}, {"id": "c", "text": "Client with an eGFR of 26 mL/min/1.73 m²"}, {"id": "d", "text": "Client with type 2 diabetes who also takes insulin"}]'::jsonb, '["c"]', 'An eGFR below 30 mL/min (severe CKD) is a contraindication because the drug accumulates and raises the risk of lactic acidosis. Mild early diarrhea is an expected GI effect, and metformin may be combined with insulin.'),
  ('metformin', 38, 'The nurse teaches a client about extended-release metformin. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll take it twice a day on an empty stomach.\""}, {"id": "b", "text": "\"I''ll take it once a day with my evening meal.\""}, {"id": "c", "text": "\"Taking it with food helps lessen stomach upset.\""}, {"id": "d", "text": "\"I should report muscle pain and trouble breathing.\""}]'::jsonb, '["a"]', 'Extended-release metformin is commonly taken once daily with the evening meal, and taking it on an empty stomach worsens nausea. Reporting muscle pain and difficulty breathing is correct because they are signs of lactic acidosis.'),
  ('metformin', 39, 'A client taking metformin asks what lactate is. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"A waste product formed only when the kidneys fail\""}, {"id": "b", "text": "\"A digestive enzyme the pancreas releases after meals\""}, {"id": "c", "text": "\"A hormone that stimulates the pancreas to release insulin\""}, {"id": "d", "text": "\"A substance the body makes when cells use glucose for energy\""}]'::jsonb, '["d"]', 'Lactate is a substance made by the body when cells use sugar/glucose for energy. It is not a pancreatic enzyme or hormone, and it is produced normally rather than only in kidney failure.'),
  ('metformin', 40, 'A client taking metformin reports indigestion and heartburn after doses. The nurse recognizes this finding as which?', '[{"id": "a", "text": "Dyspepsia, a common GI side effect"}, {"id": "b", "text": "An early sign of lactic acidosis"}, {"id": "c", "text": "A sign of metformin-induced hypoglycemia"}, {"id": "d", "text": "A sign that the eGFR is below 30"}]'::jsonb, '["a"]', 'Dyspepsia (indigestion, heartburn) is one of the most common GI side effects of metformin. It is not among the listed signs of lactic acidosis, and metformin alone does not cause hypoglycemia.'),
  ('metformin', 41, 'A client with nausea from metformin was taught to take each dose with a meal. Which finding indicates the teaching was effective?', '[{"id": "a", "text": "The client now takes metformin before eating each morning."}, {"id": "b", "text": "The client reports less nausea since taking doses with breakfast."}, {"id": "c", "text": "The client skips doses on days when nausea is present."}, {"id": "d", "text": "The client takes each dose with water only at bedtime."}]'::jsonb, '["b"]', 'Taking metformin with food reduces GI side effects, so less nausea with doses at breakfast shows the teaching worked. Taking doses before eating or with water only worsens nausea, and skipping doses is not the intended outcome.'),
  ('metformin', 42, 'A client who takes metformin is scheduled for a CT with iodinated contrast. Which sequence of care is correct?', '[{"id": "a", "text": "Continue dosing → perform CT → hold 48 hours → restart without labs"}, {"id": "b", "text": "Hold 24 hours before → perform CT → restart right away → check labs later"}, {"id": "c", "text": "Hold 24 hours before → perform CT → confirm stable renal function → restart at 48 hours"}, {"id": "d", "text": "Hold 48 hours before → perform CT → restart at 24 hours → check labs later"}]'::jsonb, '["c"]', 'Metformin is held 24 hours before the contrast procedure and restarted 48 hours afterward only after kidney function is confirmed stable. Restarting early or without checking renal function risks accumulation and lactic acidosis.'),
  ('metformin', 43, 'A client with type 2 diabetes whose glucose is not controlled by diet and exercise asks why the provider chose metformin instead of insulin. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"Metformin is usually the first-line oral medicine before insulin.\""}, {"id": "b", "text": "\"Insulin is never used for people who have type 2 diabetes.\""}, {"id": "c", "text": "\"Metformin is the only medicine that cannot cause side effects.\""}, {"id": "d", "text": "\"Insulin is reserved for people who are not able to swallow pills.\""}]'::jsonb, '["a"]', 'Metformin is usually considered the first-line oral medication before insulin in type 2 diabetes. Insulin may still be needed later if HbA1c stays above target, and metformin does have side effects such as GI upset.'),
  ('metformin', 44, 'A client taking metformin calls the clinic and reports dizziness, weakness, muscle pain, and feeling cold. Which instruction should the nurse give?', '[{"id": "a", "text": "\"Take your next dose with a full meal.\""}, {"id": "b", "text": "\"Stop metformin and get emergency care now.\""}, {"id": "c", "text": "\"Eat a snack, because your sugar is low.\""}, {"id": "d", "text": "\"Keep taking it; this fades in a few weeks.\""}]'::jsonb, '["b"]', 'Dizziness, weakness, muscle pain, and feeling cold suggest lactic acidosis, so metformin is stopped immediately and emergency care or the provider is contacted. These are not expected GI effects that fade over time.'),
  ('metformin', 45, 'A client who takes metformin and glimepiride receives teaching about hypoglycemia. Which client statement indicates understanding?', '[{"id": "a", "text": "\"Low blood sugar is impossible because metformin prevents it.\""}, {"id": "b", "text": "\"Only insulin, not pills, can cause my blood sugar to drop low.\""}, {"id": "c", "text": "\"Glimepiride makes my pancreas release insulin, so lows can happen.\""}, {"id": "d", "text": "\"Metformin alone is the drug most likely to cause my lows.\""}]'::jsonb, '["c"]', 'Glimepiride is a sulfonylurea that stimulates the pancreas to release more insulin, so hypoglycemia can occur when it is combined with metformin. Metformin alone has a low hypoglycemia risk.'),
  ('metformin', 46, 'Which client taking metformin is at greatest risk for drug accumulation and lactic acidosis?', '[{"id": "a", "text": "Client with mild bloating after meals"}, {"id": "b", "text": "Client with renal impairment"}, {"id": "c", "text": "Client taking doses with breakfast"}, {"id": "d", "text": "Client whose HbA1c is 6.8%"}]'::jsonb, '["b"]', 'Metformin is removed by the kidneys, so lactic acidosis is more likely with renal failure. Bloating is a common GI effect, and an HbA1c below 7% reflects good glucose control.'),
  ('metformin', 47, 'A client scheduled for a CT asks why iodinated contrast dye matters for someone taking metformin. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Contrast reacts with metformin and causes low blood glucose.\""}, {"id": "b", "text": "\"Contrast blocks the absorption of metformin from the stomach.\""}, {"id": "c", "text": "\"Contrast makes metformin stimulate insulin release.\""}, {"id": "d", "text": "\"Contrast can reduce kidney function so metformin builds up.\""}]'::jsonb, '["d"]', 'Iodinated contrast causes transient nephrotoxicity, so metformin can accumulate and lead to lactic acidosis. Metformin does not stimulate insulin release, and contrast is not linked to hypoglycemia.'),
  ('metformin', 48, 'A client taking metformin asks what happens in the body during lactic acidosis. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"Glucose builds up and the blood becomes too alkaline.\""}, {"id": "b", "text": "\"Ketones build up because insulin is completely absent.\""}, {"id": "c", "text": "\"Lactate levels drop and the blood becomes too basic.\""}, {"id": "d", "text": "\"Lactate builds up in the blood and it becomes too acidic.\""}]'::jsonb, '["d"]', 'Lactic acidosis is a buildup of lactate in the blood that makes the blood too acidic. It involves lactate rising, not falling, and it is not a buildup of glucose or ketones.'),
  ('metformin', 49, 'A client starting metformin asks how often lactic acidosis occurs and how serious it is. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It is common and usually mild.\""}, {"id": "b", "text": "\"It is common and expected early on.\""}, {"id": "c", "text": "\"It is rare but can be life-threatening.\""}, {"id": "d", "text": "\"It is rare and resolves without treatment.\""}]'::jsonb, '["c"]', 'Lactic acidosis is a rare but life-threatening complication of metformin buildup. The common, expected effects of metformin are GI symptoms, not lactic acidosis.'),
  ('metformin', 50, 'A client taking metformin alone has an HbA1c of 7.6% and no symptoms of high blood glucose. Following the type 2 treatment ladder, which step does the nurse anticipate next?', '[{"id": "a", "text": "Return to diet and exercise only"}, {"id": "b", "text": "Stop metformin and recheck in 1 week"}, {"id": "c", "text": "Start insulin before any other agent"}, {"id": "d", "text": "Add another oral agent or a GLP-1"}]'::jsonb, '["d"]', 'When metformin alone is insufficient, the next step on the ladder is additional oral agents or a GLP-1. Insulin is used when HbA1c remains above 7% despite oral medications or when glucose is very high with symptoms.'),
  ('dka_hhns', 1, 'A client with type 1 diabetes is admitted with rapid, deep respirations and a fruity odor on the breath. Which laboratory finding should the nurse expect on admission?', '[{"id": "a", "text": "Serum potassium above the normal range"}, {"id": "b", "text": "Arterial pH above the normal range"}, {"id": "c", "text": "Urine that is negative for ketones"}, {"id": "d", "text": "Serum potassium below the normal range"}]'::jsonb, '["a"]', 'In DKA, potassium shifts out of the cells during acidosis, so the serum level is initially high (hyperkalemia). Low potassium is a risk later, after insulin drives potassium back into the cells; DKA also causes ketones and a low pH.'),
  ('dka_hhns', 2, 'The nurse observes rapid, deep respirations in a client with diabetic ketoacidosis (DKA). The nurse recognizes that this breathing pattern is the body''s attempt to:', '[{"id": "a", "text": "retain carbon dioxide to raise the blood pH"}, {"id": "b", "text": "blow off carbon dioxide to offset the acidosis"}, {"id": "c", "text": "compensate for a falling serum potassium level"}, {"id": "d", "text": "eliminate acetone produced from glucose breakdown"}]'::jsonb, '["b"]', 'Kussmaul breathing is rapid, deep breathing that blows off CO₂ to compensate for metabolic acidosis. It does not retain CO₂, and the acetone in DKA comes from ketones produced by fat breakdown, not glucose.'),
  ('dka_hhns', 3, 'A client is admitted to the emergency department with diabetic ketoacidosis. Which prescribed intervention should the nurse implement first?', '[{"id": "a", "text": "Begin the continuous IV regular insulin infusion"}, {"id": "b", "text": "Administer subcutaneous insulin in the abdomen"}, {"id": "c", "text": "Establish a large-bore peripheral IV line"}, {"id": "d", "text": "Start an infusion of dextrose 5% in water"}]'::jsonb, '["c"]', 'First-line treatment is establishing a large-bore peripheral IV immediately, followed by 0.9% normal saline. IV regular insulin is second-line, D5W is added once glucose approaches target, and SubQ insulin is used only after the client stabilizes.'),
  ('dka_hhns', 4, 'IV access has been obtained for a client with hyperosmolar hyperglycemic nonketotic syndrome (HHNS). Which treatment should the nurse anticipate administering next?', '[{"id": "a", "text": "Dextrose 5% in water (D5W)"}, {"id": "b", "text": "Continuous IV regular insulin"}, {"id": "c", "text": "IV potassium replacement"}, {"id": "d", "text": "0.9% normal saline"}]'::jsonb, '["d"]', 'The first treatment for both DKA and HHNS is 0.9% normal saline IV, which rapidly corrects dehydration and hypotension. IV regular insulin is second-line, and D5W is added later as glucose approaches target.'),
  ('dka_hhns', 5, 'The nurse is preparing a continuous insulin infusion for a client with DKA. Which type of insulin should the nurse verify is prescribed for the infusion?', '[{"id": "a", "text": "NPH insulin"}, {"id": "b", "text": "Regular insulin"}, {"id": "c", "text": "Glargine insulin"}, {"id": "d", "text": "Detemir insulin"}]'::jsonb, '["b"]', 'Only regular insulin can be given IV, so a continuous IV infusion for DKA uses regular insulin. The other insulins listed are not given by the IV route.'),
  ('dka_hhns', 6, 'A client with DKA is receiving continuous IV regular insulin. The blood glucose was 560 mg/dL at 0800. Which 0900 glucose reading reflects the desired rate of decrease?', '[{"id": "a", "text": "540 mg/dL"}, {"id": "b", "text": "400 mg/dL"}, {"id": "c", "text": "500 mg/dL"}, {"id": "d", "text": "300 mg/dL"}]'::jsonb, '["c"]', 'The goal is to drop glucose 50–75 mg/dL per hour; a fall from 560 to 500 mg/dL is a 60 mg/dL drop. A fall to 540 is too slow, while drops to 400 or 300 mg/dL are far faster than the goal.'),
  ('dka_hhns', 7, 'A client with HHNS has been started on a continuous IV regular insulin infusion. How often should the nurse plan to check the client''s blood glucose?', '[{"id": "a", "text": "Every hour"}, {"id": "b", "text": "Every 4 hours"}, {"id": "c", "text": "Every 6 hours"}, {"id": "d", "text": "Every 12 hours"}]'::jsonb, '["a"]', 'During the insulin infusion, glucose is checked every hour so the drop can be kept at 50–75 mg/dL per hour. Checking every 4 or more hours would not allow hourly adjustment toward that goal.'),
  ('dka_hhns', 8, 'A client with DKA on continuous IV regular insulin now has a blood glucose of 240 mg/dL, and serum ketones are still present. Which action should the nurse anticipate?', '[{"id": "a", "text": "Stop the insulin infusion and recheck in 1 hour"}, {"id": "b", "text": "Switch to subcutaneous insulin right away"}, {"id": "c", "text": "Increase the insulin rate to lower glucose faster"}, {"id": "d", "text": "Continue the insulin and add IV dextrose"}]'::jsonb, '["d"]', 'In DKA, when glucose drops to about 200–250 mg/dL, insulin is NOT stopped; dextrose is added and continued until ketones and acidosis resolve. Stopping insulin while ketones are still present would leave the ketoacidosis untreated.'),
  ('dka_hhns', 9, 'A client with HHNS is receiving a continuous IV regular insulin infusion. The blood glucose has fallen to 300 mg/dL. Which change should the nurse anticipate?', '[{"id": "a", "text": "Slow the insulin drip and add dextrose"}, {"id": "b", "text": "Stop the insulin drip and give oral fluids"}, {"id": "c", "text": "Increase the insulin drip to reach normal glucose"}, {"id": "d", "text": "Keep the same insulin rate without dextrose"}]'::jsonb, '["a"]', 'In HHNS, when glucose drops to about 300 mg/dL, the insulin drip is slowed and dextrose is added. Continuing without dextrose or increasing insulin raises the risk of hypoglycemia.'),
  ('dka_hhns', 10, 'A client with HHNS is receiving IV insulin and dextrose. The nurse should titrate therapy to keep the blood glucose within which range until serum osmolality and mental status improve?', '[{"id": "a", "text": "70–110 mg/dL"}, {"id": "b", "text": "250–300 mg/dL"}, {"id": "c", "text": "100–150 mg/dL"}, {"id": "d", "text": "350–400 mg/dL"}]'::jsonb, '["b"]', 'For HHNS, once glucose drops to about 300 mg/dL, it is kept at 250–300 mg/dL until osmolality and mental status improve. Lower ranges increase the risk of hypoglycemia during insulin infusion.'),
  ('dka_hhns', 11, 'A client with HHNS is receiving IV insulin with dextrose added. Which finding indicates that this glucose-maintenance phase can be ended?', '[{"id": "a", "text": "Serum ketones have cleared from the blood"}, {"id": "b", "text": "Serum potassium has risen above 5.1 mEq/L"}, {"id": "c", "text": "Blood glucose has fallen below 100 mg/dL"}, {"id": "d", "text": "Serum osmolality and mental status improve"}]'::jsonb, '["d"]', 'In HHNS, glucose is maintained at 250–300 mg/dL until osmolality and mental status improve. Clearing of ketones is the endpoint for DKA, since HHNS has no ketones.'),
  ('dka_hhns', 12, 'A client with DKA is receiving IV regular insulin, and dextrose has been added. The nurse understands that the insulin and dextrose will continue until which outcome is reached?', '[{"id": "a", "text": "Serum osmolality and mental status improve"}, {"id": "b", "text": "Ketones and acidosis have resolved"}, {"id": "c", "text": "Blood glucose falls to 70–100 mg/dL"}, {"id": "d", "text": "Serum potassium rises to 5.1 mEq/L"}]'::jsonb, '["b"]', 'In DKA, insulin is not stopped; dextrose is added and continued until ketones and acidosis resolve. Improvement in osmolality and mental status is the endpoint used for HHNS.'),
  ('dka_hhns', 13, 'A nursing student asks why D5W is being infused while a client with DKA is still receiving IV insulin. Which response by the nurse is accurate?', '[{"id": "a", "text": "It prevents hypoglycemia as glucose falls"}, {"id": "b", "text": "It corrects the initial dehydration and hypotension"}, {"id": "c", "text": "It replaces potassium that is lost in the urine"}, {"id": "d", "text": "It prevents lipodystrophy at the infusion site"}]'::jsonb, '["a"]', 'D5W is given simultaneously once glucose approaches target to prevent hypoglycemia during the insulin infusion. Correcting dehydration and hypotension is the role of 0.9% normal saline.'),
  ('dka_hhns', 14, 'The nurse is to begin D5W for a client with HHNS who is receiving a continuous IV regular insulin infusion. Which action is correct?', '[{"id": "a", "text": "Pause the insulin while the D5W infuses"}, {"id": "b", "text": "Mix the D5W into the insulin infusion bag"}, {"id": "c", "text": "Infuse the D5W via a separate line or port"}, {"id": "d", "text": "Replace the insulin infusion with the D5W"}]'::jsonb, '["c"]', 'D5W is given through a separate IV line or port, simultaneously with the insulin infusion, to prevent hypoglycemia. The insulin is slowed in HHNS, not paused or replaced.'),
  ('dka_hhns', 15, 'A client with DKA has been receiving a continuous IV regular insulin infusion for several hours. The cardiac monitor now shows flattened T waves. The nurse should suspect:', '[{"id": "a", "text": "hyperkalemia"}, {"id": "b", "text": "hypoglycemia"}, {"id": "c", "text": "worsening acidosis"}, {"id": "d", "text": "hypokalemia"}]'::jsonb, '["d"]', 'Flat or inverted T waves are a sign of hypokalemia, a key risk because insulin drives potassium into the cells. Peaked T waves, not flat ones, indicate hyperkalemia.'),
  ('dka_hhns', 16, 'A client is admitted with DKA, and the initial ECG shows peaked T waves. Before insulin is started, the nurse interprets this finding as consistent with:', '[{"id": "a", "text": "low potassium caused by the insulin infusion"}, {"id": "b", "text": "high potassium shifting out of cells in acidosis"}, {"id": "c", "text": "low potassium caused by severe dehydration"}, {"id": "d", "text": "high potassium from hyperosmolarity in HHNS"}]'::jsonb, '["b"]', 'Peaked T waves are a sign of hyperkalemia; in DKA, potassium shifts out of cells during acidosis, so it starts high. Low potassium occurs later, after insulin shifts potassium back into the cells.'),
  ('dka_hhns', 17, 'A client with HHNS who is receiving a continuous IV regular insulin infusion has a serum potassium of 3.1 mEq/L. Which action should the nurse anticipate?', '[{"id": "a", "text": "Increase the insulin infusion rate"}, {"id": "b", "text": "Document this as an expected value"}, {"id": "c", "text": "Discontinue the normal saline infusion"}, {"id": "d", "text": "Administer potassium replacement"}]'::jsonb, '["d"]', 'Normal potassium is 3.5–5.1 mEq/L; a low level calls for potassium replacement. Increasing insulin would drive more potassium into the cells and worsen the hypokalemia.'),
  ('dka_hhns', 18, 'A client with DKA had hyperkalemia on admission, but after several hours of treatment the potassium is falling. Which explanation should the nurse give the client''s family?', '[{"id": "a", "text": "Insulin moves potassium back into the cells"}, {"id": "b", "text": "Dextrose pushes potassium out of the cells"}, {"id": "c", "text": "Acidosis moves potassium out of the cells"}, {"id": "d", "text": "Rapid breathing removes potassium from blood"}]'::jsonb, '["a"]', 'As insulin is given, potassium shifts back into the cells, creating a risk of hypokalemia. Acidosis moves potassium out of the cells, which is why the level was high at first.'),
  ('dka_hhns', 19, 'The nurse is planning care for a client with DKA who is receiving a continuous IV regular insulin infusion. Which two complications of the infusion should the nurse monitor for?', '[{"id": "a", "text": "Hyperglycemia and hyperkalemia"}, {"id": "b", "text": "Hypoglycemia and hyperkalemia"}, {"id": "c", "text": "Hypoglycemia and hypokalemia"}, {"id": "d", "text": "Hyperglycemia and hypokalemia"}]'::jsonb, '["c"]', 'The two key risks of continuous insulin infusion in both DKA and HHNS are hypoglycemia and hypokalemia, because insulin lowers glucose and drives potassium into the cells. Hyperkalemia is the admission finding in DKA, not a risk of the infusion.'),
  ('dka_hhns', 20, 'A client who recovered from DKA is being taught to self-inject subcutaneous insulin. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will rotate my injection sites each day.\""}, {"id": "b", "text": "\"I will inject 1.5 to 2 inches from my belly button.\""}, {"id": "c", "text": "\"I will use the very same spot for every injection.\""}, {"id": "d", "text": "\"My abdomen is the preferred area for my injections.\""}]'::jsonb, '["c"]', 'Injection sites should be rotated daily to prevent lipodystrophy, so using the same spot every time needs correction. Injecting 1.5–2 inches from the umbilicus in the abdomen is correct.'),
  ('dka_hhns', 21, 'A client transitioning from IV to subcutaneous insulin asks why injection sites need to be rotated. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It keeps your potassium from dropping too low.\""}, {"id": "b", "text": "\"It prevents abnormal fat at the injection sites.\""}, {"id": "c", "text": "\"It stops your body from making more ketones.\""}, {"id": "d", "text": "\"It makes each dose of insulin act much faster.\""}]'::jsonb, '["b"]', 'Rotating injection sites daily prevents lipodystrophy, which is abnormal fat at the injection site. Hypokalemia is a risk of IV insulin infusion and is managed by monitoring and replacement, not site rotation.'),
  ('dka_hhns', 22, 'The nurse is administering the first subcutaneous insulin dose to a client whose DKA has resolved. When choosing an abdominal site, how far from the umbilicus should the nurse inject?', '[{"id": "a", "text": "Within 0.5 inch of the umbilicus"}, {"id": "b", "text": "Directly at the umbilicus"}, {"id": "c", "text": "1.5 to 2 inches from the umbilicus"}, {"id": "d", "text": "At least 6 inches from the umbilicus"}]'::jsonb, '["c"]', 'SubQ insulin is injected 1.5–2 inches from the umbilicus, and the abdomen is the preferred site. Injecting at or immediately next to the umbilicus does not follow this guideline.'),
  ('dka_hhns', 23, 'A client with HHNS is receiving a continuous IV regular insulin infusion. The nurse anticipates the transition to subcutaneous insulin at which point?', '[{"id": "a", "text": "As soon as IV access is established"}, {"id": "b", "text": "Once the client has stabilized"}, {"id": "c", "text": "Right after the first saline bolus"}, {"id": "d", "text": "When glucose first reaches 400 mg/dL"}]'::jsonb, '["b"]', 'The transition from IV insulin to SubQ insulin occurs once the patient stabilizes. Early in treatment the priorities are IV access, normal saline, and continuous IV regular insulin.'),
  ('dka_hhns', 24, 'The nurse is assessing a client with type 2 diabetes who has severe hyperglycemia. Which finding most strongly suggests HHNS rather than DKA?', '[{"id": "a", "text": "Fruity odor on the breath"}, {"id": "b", "text": "Rapid, deep respirations"}, {"id": "c", "text": "Ketones present in the urine"}, {"id": "d", "text": "Symptoms developed over days"}]'::jsonb, '["d"]', 'HHNS has a slow onset that develops over days, while DKA develops quickly over hours. Fruity breath, Kussmaul respirations, and ketones are features of DKA.'),
  ('dka_hhns', 25, 'Which statement by a nursing student about the onset of DKA and HHNS indicates correct understanding?', '[{"id": "a", "text": "\"DKA develops over hours; HHNS develops over days.\""}, {"id": "b", "text": "\"DKA develops over days; HHNS develops over hours.\""}, {"id": "c", "text": "\"Both conditions develop suddenly within minutes.\""}, {"id": "d", "text": "\"Both conditions develop gradually over weeks.\""}]'::jsonb, '["a"]', 'DKA has a rapid onset over hours, while HHNS has a slow, gradual onset over days. The reversed statement confuses the two conditions.'),
  ('dka_hhns', 26, 'A nursing student is comparing hyperglycemic emergencies. Which statement about HHNS by the student is accurate?', '[{"id": "a", "text": "\"It is milder than DKA because ketones are absent.\""}, {"id": "b", "text": "\"It is more dangerous than DKA due to hyperosmolarity.\""}, {"id": "c", "text": "\"It causes metabolic acidosis from ketone buildup.\""}, {"id": "d", "text": "\"It develops more rapidly than DKA does in adults.\""}]'::jsonb, '["b"]', 'HHNS is more dangerous than DKA because of extreme hyperosmolarity. The absence of ketones does not make it milder, and it has no acidosis and a slower onset than DKA.'),
  ('dka_hhns', 27, 'A client with type 2 diabetes is admitted with a blood glucose above 600 mg/dL, but the urine is negative for ketones. The client asks why there are no ketones. Which explanation is correct?', '[{"id": "a", "text": "\"The kidneys clear ketones faster when glucose is high.\""}, {"id": "b", "text": "\"The glucose level is too high for ketones to form.\""}, {"id": "c", "text": "\"Your body has enough insulin to prevent ketones.\""}, {"id": "d", "text": "\"Your body is breaking down fat faster than usual.\""}]'::jsonb, '["c"]', 'In HHNS there is enough insulin to prevent ketones, but not enough to control glucose. Fat breakdown producing ketones occurs in DKA from absolute insulin deficiency.'),
  ('dka_hhns', 28, 'The nurse is teaching a client newly diagnosed with type 1 diabetes about how DKA develops. Which description of the underlying process is accurate?', '[{"id": "a", "text": "Excess insulin converts glucose into ketones"}, {"id": "b", "text": "Absolute insulin lack causes fat breakdown to ketones"}, {"id": "c", "text": "Partial insulin lack prevents any fat breakdown"}, {"id": "d", "text": "Low potassium triggers the liver to make ketones"}]'::jsonb, '["b"]', 'DKA is caused by absolute insulin deficiency, which leads the body to break down fat and produce ketones. Having some insulin, which prevents ketones, describes HHNS.'),
  ('dka_hhns', 29, 'The nurse is reviewing the recent history of a client with type 2 diabetes admitted with HHNS. Which event is most likely the precipitating factor?', '[{"id": "a", "text": "Daily rotation of insulin injection sites"}, {"id": "b", "text": "A recent increase in the insulin dosage"}, {"id": "c", "text": "A stomach virus during the past week"}, {"id": "d", "text": "A recent ECG showing normal T waves"}]'::jsonb, '["c"]', 'Viral infections such as a stomach virus, flu, or COVID are common precipitating factors for both DKA and HHNS. Increasing the insulin dosage is the recommended management of stress triggers, not a cause.'),
  ('dka_hhns', 30, 'A client with type 1 diabetes calls the clinic reporting flu symptoms and asks what to do about insulin while sick. Which instruction by the nurse is appropriate?', '[{"id": "a", "text": "\"Skip your insulin until you are eating again.\""}, {"id": "b", "text": "\"Lower your insulin dose until you recover.\""}, {"id": "c", "text": "\"Stop insulin and drink extra water instead.\""}, {"id": "d", "text": "\"Your insulin dose may need to be increased.\""}]'::jsonb, '["d"]', 'Viral infections such as the flu are common triggers of DKA, and stress triggers are managed by increasing the insulin dosage. Skipping or lowering insulin does the opposite.'),
  ('dka_hhns', 31, 'The nurse is teaching a client with diabetes about preventing hyperglycemic emergencies. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Severe emotional stress can trigger a glucose crisis.\""}, {"id": "b", "text": "\"I should lower my insulin when I am very stressed.\""}, {"id": "c", "text": "\"Surgery or an injury can set off this emergency.\""}, {"id": "d", "text": "\"A serious infection like sepsis can be a trigger.\""}]'::jsonb, '["b"]', 'Stress triggers are managed by increasing the insulin dosage, so lowering insulin under stress is incorrect. Emotional stress, trauma or surgery, and sepsis are all listed precipitating factors.'),
  ('dka_hhns', 32, 'A client with type 1 diabetes is admitted with DKA. Which item in the client''s recent history is a recognized precipitating factor?', '[{"id": "a", "text": "Lipodystrophy at the abdominal injection sites"}, {"id": "b", "text": "Hypokalemia that was treated last month"}, {"id": "c", "text": "Fruity breath odor noticed by the family"}, {"id": "d", "text": "Sepsis from an infection two days ago"}]'::jsonb, '["d"]', 'Sepsis is a common precipitating factor for both DKA and HHNS, along with viral infections, trauma or surgery, and stress. Fruity breath is a symptom of DKA caused by ketones, not a trigger.'),
  ('dka_hhns', 33, 'A client with type 2 diabetes is admitted with confusion. Which set of laboratory findings is consistent with HHNS?', '[{"id": "a", "text": "Glucose above 600 mg/dL with no ketones"}, {"id": "b", "text": "Glucose above 600 mg/dL with ketoacidosis"}, {"id": "c", "text": "Ketones present with metabolic acidosis"}, {"id": "d", "text": "Ketones present with hyperkalemia"}]'::jsonb, '["a"]', 'HHNS presents with blood glucose above 600 mg/dL and no ketones or acidosis. Ketones, metabolic acidosis, and hyperkalemia are features of DKA.'),
  ('dka_hhns', 34, 'Two clients with severe hyperglycemia are admitted, one with DKA and one with HHNS. Which assessment finding would the nurse expect only in the client with DKA?', '[{"id": "a", "text": "Extreme dehydration"}, {"id": "b", "text": "Severe confusion"}, {"id": "c", "text": "Fruity-smelling breath"}, {"id": "d", "text": "Decreased level of consciousness"}]'::jsonb, '["c"]', 'Fruity, acetone-smelling breath comes from ketones, which are present in DKA but absent in HHNS. Extreme dehydration and severe neuro changes such as confusion and decreased LOC are more typical of HHNS.'),
  ('dka_hhns', 35, 'An older adult with type 2 diabetes is admitted with HHNS. Which neurologic finding should the nurse expect?', '[{"id": "a", "text": "Confusion and decreased level of consciousness"}, {"id": "b", "text": "Alert and oriented with only mild fatigue"}, {"id": "c", "text": "Rapid, deep breathing with fruity breath"}, {"id": "d", "text": "Moderate changes that develop within hours"}]'::jsonb, '["a"]', 'Neuro changes in HHNS are severe, including decreased LOC and confusion. Moderate neuro changes with a rapid onset and Kussmaul breathing with fruity breath are features of DKA.'),
  ('dka_hhns', 36, 'The nurse is comparing the fluid status of a client with DKA to that of a client with HHNS. Which statement is accurate?', '[{"id": "a", "text": "Dehydration is absent in DKA"}, {"id": "b", "text": "Dehydration is extreme in HHNS"}, {"id": "c", "text": "HHNS causes no dehydration"}, {"id": "d", "text": "DKA dehydration is the more severe"}]'::jsonb, '["b"]', 'Dehydration occurs in DKA but is extreme in HHNS. Both conditions involve dehydration, so neither statement claiming its absence is accurate.'),
  ('dka_hhns', 37, 'The nurse is reviewing the DKA mnemonic D·KKK·AAA with a nursing student. Which component is the initial focus of treatment?', '[{"id": "a", "text": "Hyperkalemia"}, {"id": "b", "text": "Acidosis"}, {"id": "c", "text": "Ketones"}, {"id": "d", "text": "Dehydration"}]'::jsonb, '["d"]', 'In the D·KKK·AAA mnemonic, dehydration is the initial focus of treatment, which is why normal saline is given first. Ketones, acidosis, and hyperkalemia are addressed as treatment continues.'),
  ('dka_hhns', 38, 'A client admitted with DKA reports loss of appetite, nausea, and abdominal pain. How should the nurse interpret these findings?', '[{"id": "a", "text": "They suggest HHNS rather than DKA"}, {"id": "b", "text": "They are expected findings with DKA"}, {"id": "c", "text": "They signal hypokalemia from insulin"}, {"id": "d", "text": "They indicate SubQ insulin is needed"}]'::jsonb, '["b"]', 'Anorexia, which may be accompanied by nausea and abdominal pain, is one of the three A''s of the DKA mnemonic. These findings are part of the DKA presentation, not a sign of HHNS or of an insulin complication.'),
  ('dka_hhns', 39, 'A nursing student asks what causes the metabolic acidosis seen in DKA. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Ketone accumulation lowers the blood pH"}, {"id": "b", "text": "Rapid breathing removes too much CO₂"}, {"id": "c", "text": "High serum potassium lowers the blood pH"}, {"id": "d", "text": "Extreme hyperosmolarity lowers the pH"}]'::jsonb, '["a"]', 'DKA causes metabolic acidosis, a low pH from ketone accumulation. Rapid, deep Kussmaul breathing blows off CO₂ to compensate for the acidosis rather than cause it.'),
  ('dka_hhns', 40, 'A client with type 2 diabetes is admitted with HHNS. Which respiratory pattern should the nurse expect?', '[{"id": "a", "text": "Rapid, deep Kussmaul respirations"}, {"id": "b", "text": "Deep respirations with fruity odor"}, {"id": "c", "text": "A normal breathing pattern"}, {"id": "d", "text": "Slow breathing that retains CO₂"}]'::jsonb, '["c"]', 'Breathing in HHNS is normal because there is no acidosis to compensate for. Kussmaul respirations and fruity breath are features of DKA.'),
  ('dka_hhns', 41, 'The nurse is caring for a client admitted with DKA. Which sequence of interventions reflects the correct order of treatment?', '[{"id": "a", "text": "IV access, IV regular insulin, 0.9% saline, then D5W"}, {"id": "b", "text": "IV access, 0.9% saline, IV regular insulin, then D5W"}, {"id": "c", "text": "0.9% saline, SubQ insulin, IV access, then D5W"}, {"id": "d", "text": "IV access, D5W, IV regular insulin, then 0.9% saline"}]'::jsonb, '["b"]', 'First-line treatment is IV access and 0.9% normal saline, second-line is continuous IV regular insulin, and D5W is added once glucose approaches target. Starting insulin before saline or starting with D5W reverses the order.'),
  ('dka_hhns', 42, 'The nurse is reviewing admission orders for a client with HHNS. Which order should the nurse question?', '[{"id": "a", "text": "Infuse 0.9% normal saline through a large-bore IV"}, {"id": "b", "text": "Check the capillary blood glucose every hour"}, {"id": "c", "text": "Place the client on a continuous ECG monitor"}, {"id": "d", "text": "Administer NPH insulin by continuous IV infusion"}]'::jsonb, '["d"]', 'Only regular insulin can be given IV, so an IV NPH infusion should be questioned. Normal saline through a large-bore IV, hourly glucose checks, and ECG monitoring are all appropriate.'),
  ('dka_hhns', 43, 'A client with DKA is receiving IV regular insulin and normal saline. At what point should the nurse anticipate starting D5W?', '[{"id": "a", "text": "On admission as the first IV fluid"}, {"id": "b", "text": "After the insulin has been discontinued"}, {"id": "c", "text": "Once glucose approaches the target range"}, {"id": "d", "text": "Only if the potassium falls below 3.5"}]'::jsonb, '["c"]', 'D5W is given simultaneously with the insulin once glucose approaches target, to prevent hypoglycemia. Normal saline, not D5W, is the first fluid, and insulin is not stopped in DKA.'),
  ('dka_hhns', 44, 'The nurse is monitoring a client with DKA who is receiving a continuous IV regular insulin infusion. Which finding should the nurse report to the provider?', '[{"id": "a", "text": "Glucose fell from 580 to 515 mg/dL in an hour"}, {"id": "b", "text": "Glucose fell from 580 to 400 mg/dL in an hour"}, {"id": "c", "text": "Serum potassium of 4.4 mEq/L on hourly labs"}, {"id": "d", "text": "Normal saline infusing via a large-bore IV"}]'::jsonb, '["b"]', 'The goal is a glucose drop of 50–75 mg/dL per hour, so a 180 mg/dL drop in one hour is too rapid and should be reported. A 65 mg/dL drop is within the goal, and 4.4 mEq/L is within the normal potassium range of 3.5–5.1 mEq/L.'),
  ('dka_hhns', 45, 'A confused client with HHNS has received normal saline and IV regular insulin for several hours. Which finding best indicates that treatment is effective?', '[{"id": "a", "text": "The client is more alert and oriented"}, {"id": "b", "text": "Glucose fell to 90 mg/dL within 2 hours"}, {"id": "c", "text": "Kussmaul respirations have now resolved"}, {"id": "d", "text": "The client''s urine remains ketone-free"}]'::jsonb, '["a"]', 'HHNS treatment continues until osmolality and mental status improve, so increased alertness indicates effectiveness. A drop to 90 mg/dL in 2 hours far exceeds the 50–75 mg/dL per hour goal, and Kussmaul breathing and ketones relate to DKA.'),
  ('dka_hhns', 46, 'A client with type 2 diabetes has a blood glucose of 850 mg/dL, no ketones in the urine, and no acidosis. Which condition does the nurse identify?', '[{"id": "a", "text": "DKA"}, {"id": "b", "text": "HHNS"}, {"id": "c", "text": "Hypoglycemia"}, {"id": "d", "text": "Hypokalemia"}]'::jsonb, '["b"]', 'Glucose above 600 mg/dL with no ketones and no acidosis is consistent with HHNS. DKA is defined by ketones and metabolic acidosis.'),
  ('dka_hhns', 47, 'The nurse is assessing four clients. Which client is most likely to develop HHNS?', '[{"id": "a", "text": "An adult with type 1 diabetes who has the flu"}, {"id": "b", "text": "An adult with type 1 diabetes who has sepsis"}, {"id": "c", "text": "A teen with type 1 diabetes after a fracture"}, {"id": "d", "text": "An adult with type 2 diabetes who has the flu"}]'::jsonb, '["d"]', 'HHNS occurs in type 2 diabetes, and viral infections such as the flu are common triggers. The clients with type 1 diabetes are at risk for DKA rather than HHNS.'),
  ('dka_hhns', 48, 'During care of a client with HHNS on an insulin infusion, a nursing student says, "We don''t need to watch potassium because there is no acidosis." Which response by the nurse is best?', '[{"id": "a", "text": "\"Insulin infusion can still shift potassium.\""}, {"id": "b", "text": "\"Potassium is checked only once on admission.\""}, {"id": "c", "text": "\"You''re right; potassium only matters in DKA.\""}, {"id": "d", "text": "\"Potassium is checked only if T waves peak.\""}]'::jsonb, '["a"]', 'Even in HHNS, potassium is still monitored because the insulin infusion can shift potassium into cells. Potassium monitoring is required throughout the infusion in both conditions.'),
  ('dka_hhns', 49, 'A client with DKA is hypotensive on arrival, and the nurse rapidly infuses 0.9% normal saline. Which finding best indicates that this intervention is having the intended effect?', '[{"id": "a", "text": "Serum ketones are no longer detected"}, {"id": "b", "text": "Respirations become rapid and deeper"}, {"id": "c", "text": "Serum potassium is starting to decrease"}, {"id": "d", "text": "Blood pressure is rising toward normal"}]'::jsonb, '["d"]', 'Normal saline 0.9% rapidly corrects dehydration and hypotension, so a rising blood pressure shows it is working. Clearing of ketones is the endpoint of continued insulin with dextrose.'),
  ('dka_hhns', 50, 'At a follow-up visit, a client who recovered from DKA has a lumpy area of abnormal fatty tissue at the one abdominal spot used for every insulin injection. The nurse recognizes this as:', '[{"id": "a", "text": "lipodystrophy from not rotating sites"}, {"id": "b", "text": "a sign of low serum potassium"}, {"id": "c", "text": "an early sign of returning ketosis"}, {"id": "d", "text": "a reaction to the D5W given earlier"}]'::jsonb, '["a"]', 'Lipodystrophy is abnormal fat at the injection site and is prevented by rotating injection sites daily. Using one spot for every injection skips that rotation.'),
  ('di_siadh', 1, 'A nursing student asks where antidiuretic hormone (ADH) is stored and released. Which response by the nurse is correct?', '[{"id": "a", "text": "The anterior pituitary gland"}, {"id": "b", "text": "The adrenal cortex"}, {"id": "c", "text": "The kidneys"}, {"id": "d", "text": "The posterior pituitary gland"}]'::jsonb, '["d"]', 'ADH is produced by the hypothalamus and stored and released by the posterior pituitary gland via nerve fibers. The kidneys are where ADH acts, not where it is stored.'),
  ('di_siadh', 2, 'The nurse is reviewing ADH physiology with a client newly diagnosed with central diabetes insipidus. Which client statement indicates correct understanding?', '[{"id": "a", "text": "\"ADH is made in my hypothalamus and released by my posterior pituitary.\""}, {"id": "b", "text": "\"ADH is made in my posterior pituitary and released by my hypothalamus.\""}, {"id": "c", "text": "\"ADH is made in my kidneys and released by my posterior pituitary.\""}, {"id": "d", "text": "\"ADH is made and released by my anterior pituitary gland.\""}]'::jsonb, '["a"]', 'ADH is produced by the hypothalamus and stored and released by the posterior pituitary. The reversed statement confuses where ADH is made with where it is released.'),
  ('di_siadh', 3, 'The nurse is explaining the normal action of antidiuretic hormone (ADH) to a client. Which description is accurate?', '[{"id": "a", "text": "It tells the kidneys to release more water"}, {"id": "b", "text": "It tells the kidneys to keep water in"}, {"id": "c", "text": "It dilates the blood vessels"}, {"id": "d", "text": "It raises the daily urine output"}]'::jsonb, '["b"]', 'ADH tells the kidneys to keep water, reducing urine output, and also constricts blood vessels. When ADH is low, the result is lots of urine (polyuria).'),
  ('di_siadh', 4, 'A client''s medication record lists "vasopressin." The nurse recognizes that vasopressin is another name for which hormone?', '[{"id": "a", "text": "ADH"}, {"id": "b", "text": "Tolvaptan"}, {"id": "c", "text": "Demeclocycline"}, {"id": "d", "text": "Hydrochlorothiazide"}]'::jsonb, '["a"]', 'ADH is also called vasopressin. Tolvaptan is a vasopressin receptor antagonist that blocks ADH effect, and demeclocycline blocks ADH effect at the kidney.'),
  ('di_siadh', 5, 'A postoperative adult client has had a urine output of 25 mL/hr for the past 2 hours. How should the nurse interpret this finding?', '[{"id": "a", "text": "Within the expected adult range"}, {"id": "b", "text": "Below the expected adult minimum"}, {"id": "c", "text": "Consistent with polyuria"}, {"id": "d", "text": "Consistent with anuria"}]'::jsonb, '["b"]', 'Oliguria is less than 30 mL/hr, and normal adult output is at least 30 mL/hr. Anuria is less than 100 mL/day, which 25 mL/hr does not meet.'),
  ('di_siadh', 6, 'The nurse is monitoring hourly urine output for a 70-kg adult client. Which hourly output is within the expected normal range for this client?', '[{"id": "a", "text": "20 mL/hr"}, {"id": "b", "text": "3 mL/hr"}, {"id": "c", "text": "300 mL/hr"}, {"id": "d", "text": "50 mL/hr"}]'::jsonb, '["d"]', 'Normal adult urine output is about 0.5–1 mL/kg/hr or at least 30 mL/hr, which is 35–70 mL/hr for a 70-kg adult. 20 mL/hr is below 30 mL/hr (oliguria), and 300 mL/hr would exceed 3,000 mL/day (polyuria).'),
  ('di_siadh', 7, 'A client with suspected diabetes insipidus has a 24-hour urine collection. Which total volume meets the definition of polyuria?', '[{"id": "a", "text": "450 mL"}, {"id": "b", "text": "1,500 mL"}, {"id": "c", "text": "4,200 mL"}, {"id": "d", "text": "2,000 mL"}]'::jsonb, '["c"]', 'Polyuria is urine output greater than 3,000 mL/day, so 4,200 mL qualifies. 450 mL falls in the oliguria range of less than 400–500 mL/day.'),
  ('di_siadh', 8, 'A client''s total urine output for the past 24 hours is 80 mL. How should the nurse interpret this finding?', '[{"id": "a", "text": "Polyuria consistent with diabetes insipidus"}, {"id": "b", "text": "Oliguria expected with prescribed fluid restriction"}, {"id": "c", "text": "Anuria, which is a medical emergency"}, {"id": "d", "text": "Normal output for an adult client"}]'::jsonb, '["c"]', 'Anuria is urine output of less than 100 mL/day and is a medical emergency. Calling 80 mL/day an expected finding would delay response to an emergency.'),
  ('di_siadh', 9, 'The nurse is caring for four clients. Which client is at greatest risk for developing diabetes insipidus?', '[{"id": "a", "text": "A client with small-cell lung cancer"}, {"id": "b", "text": "A client taking an SSRI antidepressant"}, {"id": "c", "text": "A client receiving vincristine"}, {"id": "d", "text": "A client one day after hypophysectomy"}]'::jsonb, '["d"]', 'Pituitary surgery (hypophysectomy) is a cause of diabetes insipidus. Small-cell lung cancer, SSRIs, and vincristine are causes of SIADH.'),
  ('di_siadh', 10, 'A client who sustained head trauma has a urine output of 400 mL/hr with a urine specific gravity of 1.002. Which condition should the nurse suspect?', '[{"id": "a", "text": "Diabetes insipidus from low ADH"}, {"id": "b", "text": "SIADH from high ADH"}, {"id": "c", "text": "Diabetes insipidus from high ADH"}, {"id": "d", "text": "SIADH from low ADH"}]'::jsonb, '["a"]', 'Head trauma is a cause of DI, which is low ADH producing polyuria and very dilute urine with a specific gravity often below 1.010. SIADH involves high ADH with low urine output and concentrated urine.'),
  ('di_siadh', 11, 'A client with chronic SIADH has been taking demeclocycline. The client now has a large output of dilute urine because the kidneys are not responding to ADH. The nurse recognizes this as:', '[{"id": "a", "text": "central DI from low ADH production"}, {"id": "b", "text": "nephrogenic DI caused by the medication"}, {"id": "c", "text": "worsening SIADH from the medication"}, {"id": "d", "text": "osmotic demyelination from the medication"}]'::jsonb, '["b"]', 'Demeclocycline is used for SIADH but can cause nephrogenic DI, in which the kidneys do not respond to ADH. This differs from central DI, where ADH itself is low.'),
  ('di_siadh', 12, 'The nurse is assessing a client with central diabetes insipidus. Which finding should the nurse expect?', '[{"id": "a", "text": "Extreme thirst"}, {"id": "b", "text": "Weight gain"}, {"id": "c", "text": "Dark, concentrated urine"}, {"id": "d", "text": "Low serum sodium"}]'::jsonb, '["a"]', 'DI causes polydipsia (extreme thirst) along with polyuria. Weight gain, dark concentrated urine, and low sodium are findings of SIADH.'),
  ('di_siadh', 13, 'A client is admitted with untreated diabetes insipidus. Which laboratory finding should the nurse expect?', '[{"id": "a", "text": "Decreased serum sodium"}, {"id": "b", "text": "High urine specific gravity"}, {"id": "c", "text": "Low serum osmolality"}, {"id": "d", "text": "Elevated serum sodium"}]'::jsonb, '["d"]', 'DI causes hypernatremia because water is lost and the blood becomes concentrated. Low sodium, low serum osmolality, and high urine specific gravity are findings of SIADH.'),
  ('di_siadh', 14, 'A client with diabetes insipidus reports feeling dizzy when getting up from bed. The nurse recognizes that this symptom is most likely related to:', '[{"id": "a", "text": "fluid retention from excess ADH"}, {"id": "b", "text": "low blood volume from water loss"}, {"id": "c", "text": "brain cell swelling from low sodium"}, {"id": "d", "text": "high blood pressure from vasoconstriction"}]'::jsonb, '["b"]', 'In DI, excess water loss causes hypovolemia, leading to low BP or orthostatic hypotension and dizziness. Brain cell swelling from low sodium is a cause of neurologic changes in SIADH.'),
  ('di_siadh', 15, 'The nurse is reviewing the daily weights of a client with untreated diabetes insipidus. Which trend should the nurse expect?', '[{"id": "a", "text": "A steady loss of weight"}, {"id": "b", "text": "A mild gain in weight"}, {"id": "c", "text": "A large gain in weight"}, {"id": "d", "text": "No change in weight"}]'::jsonb, '["a"]', 'DI causes weight loss from fluid loss. Weight gain from water retention is a finding of SIADH.'),
  ('di_siadh', 16, 'A client with severe diabetes insipidus becomes lethargic with a decreased level of consciousness. The nurse attributes this change to:', '[{"id": "a", "text": "hyponatremia and brain cell swelling"}, {"id": "b", "text": "fluid overload from water retention"}, {"id": "c", "text": "severe dehydration or hypernatremia"}, {"id": "d", "text": "a urine output below 30 mL/hr"}]'::jsonb, '["c"]', 'In DI, decreased LOC may occur from severe dehydration or hypernatremia. Hyponatremia with brain cell swelling causes altered mental status in SIADH, not DI.'),
  ('di_siadh', 17, 'The nurse is caring for one client with diabetes insipidus and another with SIADH. Which pairing of urine findings is accurate?', '[{"id": "a", "text": "DI: dark, high specific gravity; SIADH: pale, low specific gravity"}, {"id": "b", "text": "DI: pale, low specific gravity; SIADH: dark, high specific gravity"}, {"id": "c", "text": "DI: pale, high specific gravity; SIADH: dark, low specific gravity"}, {"id": "d", "text": "DI: dark, low specific gravity; SIADH: pale, high specific gravity"}]'::jsonb, '["b"]', 'DI urine is pale and dilute with a low specific gravity, while SIADH urine is dark and concentrated with a high specific gravity. The reversed pairing confuses low-ADH and high-ADH states.'),
  ('di_siadh', 18, 'A client is diagnosed with neurogenic (central) diabetes insipidus. Which explanation of this condition should the nurse provide?', '[{"id": "a", "text": "\"Your kidneys do not respond to ADH.\""}, {"id": "b", "text": "\"Your body is releasing too much ADH.\""}, {"id": "c", "text": "\"Your brain cannot make enough ADH.\""}, {"id": "d", "text": "\"Your kidneys are making extra ADH.\""}]'::jsonb, '["c"]', 'Neurogenic (central) DI is a brain or pituitary malfunction in which ADH cannot be made. Kidneys failing to respond to ADH describes nephrogenic DI.'),
  ('di_siadh', 19, 'A client taking lithium develops diabetes insipidus, and ADH levels are present. Which type of DI does the nurse anticipate, and why?', '[{"id": "a", "text": "Neurogenic, because the brain cannot make ADH"}, {"id": "b", "text": "Nephrogenic, because the kidneys ignore ADH"}, {"id": "c", "text": "Neurogenic, because the pituitary was injured"}, {"id": "d", "text": "Nephrogenic, because the kidneys lack ADH"}]'::jsonb, '["b"]', 'Nephrogenic DI is a kidney malfunction in which ADH is present but the kidneys do not respond to it; stopping lithium is listed under its treatment. Neurogenic DI is an inability of the brain or pituitary to make ADH.'),
  ('di_siadh', 20, 'The nurse is preparing a client for a water deprivation test. Which sequence of steps is correct?', '[{"id": "a", "text": "Give vasopressin, restrict water, then obtain baseline data"}, {"id": "b", "text": "Restrict water, obtain baseline data, then give vasopressin"}, {"id": "c", "text": "Obtain baseline data, give vasopressin, then restrict water"}, {"id": "d", "text": "Obtain baseline data, restrict water, then give vasopressin"}]'::jsonb, '["d"]', 'The protocol starts with an initial assessment of weight, urine output, and blood tests, followed by 8 hours of water restriction, then administration of vasopressin while observing urine output. Giving vasopressin before restricting water reverses the order.'),
  ('di_siadh', 21, 'During a water deprivation test, the client receives vasopressin, and the urine output then decreases and becomes concentrated. How should the nurse interpret this result?', '[{"id": "a", "text": "Nephrogenic diabetes insipidus"}, {"id": "b", "text": "Syndrome of inappropriate ADH"}, {"id": "c", "text": "Neurogenic diabetes insipidus"}, {"id": "d", "text": "Normal response ruling out any DI"}]'::jsonb, '["c"]', 'When urine decreases or concentrates after desmopressin/vasopressin, the client has neurogenic (central) DI, because the problem is in the brain and the kidneys respond to ADH. No response indicates nephrogenic DI.'),
  ('di_siadh', 22, 'During a water deprivation test, the client''s urine output continues unchanged after vasopressin is administered. The nurse recognizes this finding as consistent with:', '[{"id": "a", "text": "nephrogenic diabetes insipidus"}, {"id": "b", "text": "neurogenic diabetes insipidus"}, {"id": "c", "text": "central diabetes insipidus"}, {"id": "d", "text": "excess desmopressin effect"}]'::jsonb, '["a"]', 'If urine continues after vasopressin, the client has nephrogenic DI because the kidneys do not respond to ADH. Neurogenic (central) DI responds to ADH with decreased urine output.'),
  ('di_siadh', 23, 'A client is undergoing a water deprivation test. Which parameters should the nurse track throughout the test?', '[{"id": "a", "text": "Blood glucose, ketones, and pH"}, {"id": "b", "text": "Pupil size, grip strength, and gait"}, {"id": "c", "text": "Temperature, pulse, and pain score"}, {"id": "d", "text": "Urine output, BP, and weight"}]'::jsonb, '["d"]', 'Monitoring during the water deprivation test includes tracking urine output, BP, and weight throughout. These reflect the fluid loss being evaluated in the test.'),
  ('di_siadh', 24, 'A client develops central diabetes insipidus after pituitary surgery. Which medication should the nurse anticipate administering?', '[{"id": "a", "text": "Desmopressin (DDAVP)"}, {"id": "b", "text": "Hydrochlorothiazide"}, {"id": "c", "text": "Tolvaptan"}, {"id": "d", "text": "Demeclocycline"}]'::jsonb, '["a"]', 'Neurogenic/central DI is treated with desmopressin/DDAVP, a synthetic ADH replacement. Hydrochlorothiazide treats nephrogenic DI, and tolvaptan and demeclocycline block ADH effect and are used for SIADH.'),
  ('di_siadh', 25, 'A client with nephrogenic diabetes insipidus is prescribed hydrochlorothiazide and asks why a "water pill" is needed when urine output is already high. Which response by the nurse is best?', '[{"id": "a", "text": "\"It replaces the ADH that your brain is not making.\""}, {"id": "b", "text": "\"It increases urine output to remove excess water.\""}, {"id": "c", "text": "\"It paradoxically lowers your urine output.\""}, {"id": "d", "text": "\"It raises your sodium level back to normal.\""}]'::jsonb, '["c"]', 'In nephrogenic DI, hydrochlorothiazide paradoxically lowers urine output. Replacing ADH is the role of desmopressin, which is used for central DI.'),
  ('di_siadh', 26, 'A nursing student asks why desmopressin is not the main treatment for a client with nephrogenic diabetes insipidus. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"The client''s brain cannot make ADH.\""}, {"id": "b", "text": "\"The client already has too much ADH.\""}, {"id": "c", "text": "\"The client''s sodium level is too low.\""}, {"id": "d", "text": "\"The client''s kidneys resist ADH.\""}]'::jsonb, '["d"]', 'In nephrogenic DI, ADH is present but the kidneys are resistant to it, so desmopressin usually will not work. An inability to make ADH describes central DI, which does respond to desmopressin.'),
  ('di_siadh', 27, 'The nurse is providing dietary teaching to a client with nephrogenic diabetes insipidus. Which diet should the nurse recommend?', '[{"id": "a", "text": "High-sodium, high-protein diet"}, {"id": "b", "text": "Low-sodium, low-protein diet"}, {"id": "c", "text": "High-sodium, low-protein diet"}, {"id": "d", "text": "Low-sodium, high-protein diet"}]'::jsonb, '["b"]', 'A low-sodium, low-protein diet helps reduce urine volume in nephrogenic DI. Increasing sodium or protein would not support this goal.'),
  ('di_siadh', 28, 'The nurse is teaching a client with nephrogenic diabetes insipidus about self-care. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will drink enough water to stay hydrated.\""}, {"id": "b", "text": "\"I will follow a low-sodium, low-protein diet.\""}, {"id": "c", "text": "\"I will take my hydrochlorothiazide as ordered.\""}, {"id": "d", "text": "\"I will limit my fluids to about 800 mL a day.\""}]'::jsonb, '["d"]', 'Nephrogenic DI requires adequate water intake to prevent dehydration; restricting fluid to 800–1,000 mL/day is a treatment for SIADH. Thiazide, water, and a low-sodium diet are correct for nephrogenic DI.'),
  ('di_siadh', 29, 'A client with central diabetes insipidus is severely dehydrated, and IV fluids are prescribed. Which principle should guide the nurse''s administration of the IV fluids?', '[{"id": "a", "text": "Infuse rapidly regardless of the sodium level"}, {"id": "b", "text": "Give carefully based on the serum sodium level"}, {"id": "c", "text": "Withhold until the desmopressin takes effect"}, {"id": "d", "text": "Limit total intake to 800–1,000 mL per day"}]'::jsonb, '["b"]', 'In central DI, IV fluids for severe dehydration are given carefully based on the sodium level. Limiting fluid to 800–1,000 mL/day is a treatment for SIADH, not DI.'),
  ('di_siadh', 30, 'A client with central diabetes insipidus was started on desmopressin (DDAVP). Which finding indicates that the medication is effective?', '[{"id": "a", "text": "Urine output decreases"}, {"id": "b", "text": "Serum sodium continues to rise"}, {"id": "c", "text": "Thirst becomes more intense"}, {"id": "d", "text": "Daily weight continues to drop"}]'::jsonb, '["a"]', 'Desmopressin is a synthetic ADH replacement, and ADH tells the kidneys to keep water and reduce urine output. Rising sodium, worsening thirst, and continued weight loss indicate ongoing DI.'),
  ('di_siadh', 31, 'A client with nephrogenic diabetes insipidus has been taking lithium. In addition to a thiazide and adequate water intake, which intervention should the nurse anticipate?', '[{"id": "a", "text": "Increasing the lithium dose"}, {"id": "b", "text": "Starting 3% hypertonic saline"}, {"id": "c", "text": "Stopping lithium if ordered"}, {"id": "d", "text": "Restricting water intake"}]'::jsonb, '["c"]', 'Treatment of nephrogenic DI includes treating the cause, such as stopping lithium if ordered. Water restriction and 3% saline are SIADH treatments.'),
  ('di_siadh', 32, 'The nurse is reviewing the histories of four clients. Which client is at greatest risk for developing SIADH?', '[{"id": "a", "text": "A client after hypophysectomy"}, {"id": "b", "text": "A client taking lithium"}, {"id": "c", "text": "A client with small-cell lung cancer"}, {"id": "d", "text": "A client taking hydrochlorothiazide"}]'::jsonb, '["c"]', 'Small-cell lung cancer is the classic cause of SIADH through ectopic ADH production. Hypophysectomy causes DI, and lithium is associated with nephrogenic DI.'),
  ('di_siadh', 33, 'A client''s serum sodium has been falling, and SIADH is suspected. Which medication on the client''s list could be contributing?', '[{"id": "a", "text": "Desmopressin taken in correct doses"}, {"id": "b", "text": "An SSRI antidepressant"}, {"id": "c", "text": "Hydrochlorothiazide"}, {"id": "d", "text": "Tolvaptan"}]'::jsonb, '["b"]', 'SSRIs are among the medications that cause SIADH. Tolvaptan blocks ADH effect and is used to treat SIADH; only excess desmopressin is listed as a cause.'),
  ('di_siadh', 34, 'A client hospitalized with pneumonia develops SIADH. Which daily weight trend should the nurse expect?', '[{"id": "a", "text": "A steady loss of weight"}, {"id": "b", "text": "Rapid loss from fluid shifts"}, {"id": "c", "text": "A mild gain in weight"}, {"id": "d", "text": "No change in weight"}]'::jsonb, '["c"]', 'Pulmonary infections such as pneumonia cause SIADH, which produces mild weight gain from water retention. Weight loss from fluid loss occurs with DI.'),
  ('di_siadh', 35, 'A client taking desmopressin for central diabetes insipidus reports headache and confusion, and the nurse notes decreased urine output and weight gain. The nurse suspects:', '[{"id": "a", "text": "worsening central DI from too little ADH"}, {"id": "b", "text": "nephrogenic DI from kidney resistance"}, {"id": "c", "text": "excess desmopressin causing SIADH effects"}, {"id": "d", "text": "dehydration from the water deprivation test"}]'::jsonb, '["c"]', 'Excess desmopressin/DDAVP, an ADH-like medication, is a cause of SIADH, producing oliguria, weight gain, and hyponatremia symptoms such as headache and confusion. Worsening DI would increase urine output and cause weight loss.'),
  ('di_siadh', 36, 'The nurse is assessing a client with SIADH. Which finding should the nurse expect?', '[{"id": "a", "text": "Pale urine with low specific gravity"}, {"id": "b", "text": "Dark urine with high specific gravity"}, {"id": "c", "text": "Large volumes of very dilute urine"}, {"id": "d", "text": "Extreme thirst with high serum sodium"}]'::jsonb, '["b"]', 'SIADH causes a high urine specific gravity with dark, concentrated urine. Pale, dilute urine, extreme thirst, and high sodium are findings of DI.'),
  ('di_siadh', 37, 'The nurse reviews the laboratory results of a client with suspected SIADH. Which set of findings supports this diagnosis?', '[{"id": "a", "text": "Low serum sodium, low serum osmolality, high urine osmolality"}, {"id": "b", "text": "High serum sodium, high serum osmolality, low urine osmolality"}, {"id": "c", "text": "Low serum sodium, high serum osmolality, low urine osmolality"}, {"id": "d", "text": "High serum sodium, low serum osmolality, high urine osmolality"}]'::jsonb, '["a"]', 'SIADH causes hyponatremia and low serum osmolality because extra water dilutes the blood, with high urine osmolality because the kidneys keep water. High serum sodium is a finding of DI.'),
  ('di_siadh', 38, 'A client with SIADH becomes disoriented. The nurse recognizes this change is most likely caused by:', '[{"id": "a", "text": "hypernatremia from water loss"}, {"id": "b", "text": "low blood volume from polyuria"}, {"id": "c", "text": "hyponatremia and brain cell swelling"}, {"id": "d", "text": "high serum osmolality from dehydration"}]'::jsonb, '["c"]', 'In SIADH, disorientation and altered mental status result from hyponatremia and brain cell swelling. Hypernatremia and dehydration cause decreased LOC in DI.'),
  ('di_siadh', 39, 'The nurse is caring for a client with SIADH. Which finding should the nurse report to the provider immediately?', '[{"id": "a", "text": "Urine that is dark and concentrated"}, {"id": "b", "text": "No reports of excessive thirst"}, {"id": "c", "text": "A mild weight gain since yesterday"}, {"id": "d", "text": "New onset of seizure activity"}]'::jsonb, '["d"]', 'Seizures are a symptom of worsening hyponatremia and may require 3% hypertonic saline. Dark, concentrated urine, absence of excessive thirst, and mild weight gain are expected findings of SIADH.'),
  ('di_siadh', 40, 'A client with SIADH has mild hyponatremia without neurologic symptoms. Which fluid order should the nurse anticipate?', '[{"id": "a", "text": "Encourage at least 3,000 mL of water daily"}, {"id": "b", "text": "Allow unrestricted oral water intake"}, {"id": "c", "text": "Restrict fluids to about 800–1,000 mL/day"}, {"id": "d", "text": "Infuse 3% hypertonic saline immediately"}]'::jsonb, '["c"]', 'SIADH is treated with fluid restriction, often around 800–1,000 mL/day. 3% hypertonic saline is reserved for severe symptomatic hyponatremia such as seizures or severe confusion.'),
  ('di_siadh', 41, 'The nurse is teaching a client with SIADH about home management. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I should drink plenty of water to flush my kidneys.\""}, {"id": "b", "text": "\"I will weigh myself every day at home.\""}, {"id": "c", "text": "\"I will limit my fluids to the amount prescribed.\""}, {"id": "d", "text": "\"I will report any headache or new confusion.\""}]'::jsonb, '["a"]', 'SIADH means too much water is retained, so the treatment is to restrict water rather than increase intake. Daily weights, fluid limits, and reporting headache or confusion are appropriate.'),
  ('di_siadh', 42, 'The nurse is reviewing the plans of care for four clients. For which client should the nurse anticipate an order for 3% hypertonic saline?', '[{"id": "a", "text": "A client with central DI and hypernatremia"}, {"id": "b", "text": "A client with SIADH who is having seizures"}, {"id": "c", "text": "A client with nephrogenic DI on a thiazide"}, {"id": "d", "text": "A client with SIADH and no symptoms"}]'::jsonb, '["b"]', '3% hypertonic saline is used for severe symptomatic hyponatremia, such as seizures, severe confusion, or very low sodium. Clients with DI have hypernatremia, and asymptomatic SIADH is managed with fluid restriction.'),
  ('di_siadh', 43, 'A client with SIADH and severe symptomatic hyponatremia is receiving 3% hypertonic saline. Which nursing action is the priority?', '[{"id": "a", "text": "Ensure the sodium rises as quickly as possible"}, {"id": "b", "text": "Encourage oral water intake during the infusion"}, {"id": "c", "text": "Monitor that the sodium is rising slowly"}, {"id": "d", "text": "Stop daily weights until the infusion ends"}]'::jsonb, '["c"]', 'Sodium must be corrected slowly to prevent osmotic demyelination syndrome, a brain injury from sodium rising too fast. Raising sodium as quickly as possible creates that risk.'),
  ('di_siadh', 44, 'A nursing student asks why the sodium level of a client with SIADH must not be corrected too quickly. Which complication does the nurse identify?', '[{"id": "a", "text": "Nephrogenic diabetes insipidus"}, {"id": "b", "text": "Osmotic demyelination syndrome"}, {"id": "c", "text": "Ectopic ADH production"}, {"id": "d", "text": "Orthostatic hypotension"}]'::jsonb, '["b"]', 'Correcting sodium slowly prevents osmotic demyelination syndrome, which is brain injury from sodium rising too fast. Nephrogenic DI is a possible effect of demeclocycline, not of sodium correction.'),
  ('di_siadh', 45, 'A client with SIADH is prescribed tolvaptan. Which explanation of the drug''s action should the nurse provide?', '[{"id": "a", "text": "\"It replaces the ADH your body is missing.\""}, {"id": "b", "text": "\"It blocks ADH and helps you lose free water.\""}, {"id": "c", "text": "\"It paradoxically lowers your urine output.\""}, {"id": "d", "text": "\"It causes your kidneys to hold on to water.\""}]'::jsonb, '["b"]', 'Tolvaptan is a vasopressin receptor antagonist that blocks ADH effect and promotes free-water loss. Replacing ADH describes desmopressin, and paradoxically lowering urine output describes hydrochlorothiazide in nephrogenic DI.'),
  ('di_siadh', 46, 'A client has chronic SIADH. Which medication blocks the effect of ADH at the kidney and is used more often for chronic SIADH?', '[{"id": "a", "text": "Desmopressin"}, {"id": "b", "text": "Hydrochlorothiazide"}, {"id": "c", "text": "Furosemide"}, {"id": "d", "text": "Demeclocycline"}]'::jsonb, '["d"]', 'Demeclocycline blocks ADH effect at the kidney and is used more for chronic SIADH. Furosemide is a loop diuretic that removes extra water, and desmopressin is an ADH replacement that can cause SIADH in excess.'),
  ('di_siadh', 47, 'A client with SIADH is prescribed furosemide. The client asks what this medication will do. Which response by the nurse is accurate?', '[{"id": "a", "text": "\"It helps your body remove extra water.\""}, {"id": "b", "text": "\"It replaces ADH your brain is not making.\""}, {"id": "c", "text": "\"It helps your kidneys keep more water.\""}, {"id": "d", "text": "\"It raises how much ADH your body makes.\""}]'::jsonb, '["a"]', 'Furosemide is a loop diuretic that helps remove extra water in SIADH, sometimes used with salt replacement. Keeping more water would worsen SIADH, which is already caused by too much water retention.'),
  ('di_siadh', 48, 'The nurse is monitoring a client with SIADH. Which assessment is the best indicator of fluid retention?', '[{"id": "a", "text": "Urine color"}, {"id": "b", "text": "Thirst level"}, {"id": "c", "text": "Daily weight"}, {"id": "d", "text": "Blood pressure"}]'::jsonb, '["c"]', 'Daily weights are the best indicator of fluid retention or water loss in SIADH. Strict I&O, serum sodium, and urine specific gravity are also monitored but are not described as the best indicator.'),
  ('di_siadh', 49, 'A client with SIADH has a very low serum sodium and is becoming confused. Which nursing intervention should the nurse implement to protect the client''s safety?', '[{"id": "a", "text": "Encourage extra oral fluids"}, {"id": "b", "text": "Implement seizure precautions"}, {"id": "c", "text": "Hold all sodium monitoring"}, {"id": "d", "text": "Increase the fluid allowance"}]'::jsonb, '["b"]', 'Seizure precautions are indicated when sodium is very low or the client is symptomatic, because worsening hyponatremia can cause seizures. Extra fluids would worsen water retention in SIADH.'),
  ('di_siadh', 50, 'A client is admitted with SIADH caused by an SSRI. In addition to fluid restriction, which intervention addresses the root problem?', '[{"id": "a", "text": "Treating the medication cause with the provider"}, {"id": "b", "text": "Starting desmopressin to balance ADH levels"}, {"id": "c", "text": "Encouraging a high-protein, high-sodium diet"}, {"id": "d", "text": "Starting hydrochlorothiazide to reduce urine"}]'::jsonb, '["a"]', 'SIADH treatment includes treating the underlying cause, such as an infection, tumor, or medication. Desmopressin is an ADH-like medication that would worsen SIADH.'),
  ('patch', 1, 'A client starting an insulin patch asks where the device delivers the insulin. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Deep into the muscle below the patch\""}, {"id": "b", "text": "\"Directly into a vein under the patch\""}, {"id": "c", "text": "\"Into the fatty tissue just under the skin\""}, {"id": "d", "text": "\"Onto the skin surface, where it is absorbed\""}]'::jsonb, '["c"]', 'An insulin patch delivers insulin into the subcutaneous tissue, the fatty tissue just under the skin. It does not deliver insulin into a vein or muscle.'),
  ('patch', 2, 'A client says, "I chose an insulin patch because it is completely needle-free." Which response by the nurse is most accurate?', '[{"id": "a", "text": "\"Some patches use a tiny cannula or microneedle under the skin.\""}, {"id": "b", "text": "\"Patches absorb insulin through the skin without any device.\""}, {"id": "c", "text": "\"Only patches used for type 1 diabetes have any needle.\""}, {"id": "d", "text": "\"That''s right; patches never place anything under the skin.\""}]'::jsonb, '["a"]', 'An insulin patch is not always completely needle-free; some use a tiny cannula, microneedle, or automatic insertion system under the skin. Insulin is delivered into subcutaneous tissue, not absorbed across the skin surface.'),
  ('patch', 3, 'A client using a basal-bolus patch pump asks what the basal insulin does. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It gives an extra dose of insulin right before each meal.\""}, {"id": "b", "text": "\"It gives a correction dose only when glucose is high.\""}, {"id": "c", "text": "\"It gives slow, steady insulin to control background glucose.\""}, {"id": "d", "text": "\"It gives insulin only when you press the click button.\""}]'::jsonb, '["c"]', 'Basal insulin is a continuous low-level insulin used to control fasting/background glucose. Mealtime and correction doses are bolus insulin.'),
  ('patch', 4, 'A client with a basal-bolus patch pump is about to eat lunch. Which type of insulin dose does the nurse expect the client to deliver?', '[{"id": "a", "text": "An intermediate-acting dose with the meal"}, {"id": "b", "text": "A basal dose given with the meal"}, {"id": "c", "text": "No dose, because basal insulin covers meals"}, {"id": "d", "text": "A bolus dose given with the meal"}]'::jsonb, '["d"]', 'Bolus insulin is an extra dose given before meals or to correct high blood glucose. Basal insulin is the slow, steady background dose.'),
  ('patch', 5, 'A nurse is explaining the purpose of an insulin patch to a client. Which goal should the nurse include?', '[{"id": "a", "text": "To reduce multiple daily injections and improve adherence"}, {"id": "b", "text": "To eliminate the risk of low blood glucose episodes"}, {"id": "c", "text": "To eliminate the need for blood glucose monitoring"}, {"id": "d", "text": "To eliminate the need to carry backup insulin"}]'::jsonb, '["a"]', 'The goal of an insulin patch is to reduce the need for multiple daily injections and improve adherence. Patients still need frequent glucose monitoring, must watch for hypoglycemia, and should carry backup insulin.'),
  ('patch', 6, 'A nurse is reviewing clients in a diabetes clinic. Which client is the most appropriate candidate for an insulin patch?', '[{"id": "a", "text": "A client with type 2 diabetes who needs basal and mealtime insulin and struggles with daily injections"}, {"id": "b", "text": "A client with type 1 diabetes who wants a device so blood glucose checks can be stopped"}, {"id": "c", "text": "A client with type 1 diabetes who wants to stop carrying backup insulin and supplies"}, {"id": "d", "text": "A client with type 2 diabetes whose glucose is well controlled without any insulin therapy"}]'::jsonb, '["a"]', 'Indications include type 2 diabetes requiring basal insulin, mealtime insulin, or both, and difficulty following multiple daily injection schedules. Patches are for patients who need insulin, and they do not replace glucose checks or backup supplies.'),
  ('patch', 7, 'A client is being taught about the CeQur Simplicity insulin patch. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"This patch delivers insulin through a tiny flexible cannula.\""}, {"id": "b", "text": "\"I will use this patch to take my mealtime insulin doses.\""}, {"id": "c", "text": "\"This patch will also give me my background basal insulin.\""}, {"id": "d", "text": "\"I can use this patch to take a correction dose when high.\""}]'::jsonb, '["c"]', 'CeQur Simplicity is a bolus-only patch for mealtime or correction doses and does not provide basal insulin. It delivers rapid-acting insulin through a tiny flexible cannula.'),
  ('patch', 8, 'A client asks the nurse how the Omnipod differs from other insulin devices. Which description is accurate?', '[{"id": "a", "text": "It is tubeless but provides only mealtime bolus insulin"}, {"id": "b", "text": "It uses long tubing and provides only basal insulin"}, {"id": "c", "text": "It uses long tubing and provides only correction doses"}, {"id": "d", "text": "It is tubeless and provides both basal and bolus insulin"}]'::jsonb, '["d"]', 'Omnipod is a tubeless patch pump that provides basal and bolus insulin through a small cannula under the device. A bolus-only patch is the CeQur Simplicity.'),
  ('patch', 9, 'A client using a V-Go device asks how often it is replaced. Which response by the nurse is correct?', '[{"id": "a", "text": "\"It is a weekly device used over 7 days.\""}, {"id": "b", "text": "\"It is replaced every 2 weeks with the reservoir.\""}, {"id": "c", "text": "\"It is a daily disposable device used over 24 hours.\""}, {"id": "d", "text": "\"It is replaced once a month at your clinic visit.\""}]'::jsonb, '["c"]', 'V-Go is a daily disposable patch-like device that provides basal insulin and on-demand bolus dosing over 24 hours using U-100 rapid-acting insulin.'),
  ('patch', 10, 'A client needs continuous background insulin and also needs mealtime doses. Which type of patch device best meets this need?', '[{"id": "a", "text": "A basal-bolus patch pump"}, {"id": "b", "text": "A basal-only patch"}, {"id": "c", "text": "A bolus-only patch"}, {"id": "d", "text": "A continuous glucose monitor"}]'::jsonb, '["a"]', 'A basal-bolus patch pump delivers both continuous basal insulin and bolus doses. A basal-only patch gives only steady insulin, and a bolus-only patch gives only mealtime or correction insulin.'),
  ('patch', 11, 'A client with an insulin patch and a CGM feels shaky and sweaty, but the CGM shows a normal glucose reading. What should the nurse instruct the client to do?', '[{"id": "a", "text": "Remove the patch until the symptoms resolve"}, {"id": "b", "text": "Deliver a correction bolus to stabilize glucose"}, {"id": "c", "text": "Ignore the symptoms because the CGM is normal"}, {"id": "d", "text": "Perform a fingerstick glucose check per instructions"}]'::jsonb, '["d"]', 'Patients with a CGM still follow provider or facility instructions for fingerstick checks, especially when symptoms do not match CGM readings. A CGM checks trends but does not replace all safety checks.'),
  ('patch', 12, 'A nurse is teaching a client who just started using an insulin patch pump. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I will check my blood sugar often, even with the patch on.\""}, {"id": "b", "text": "\"I will look at my patch site and device every day.\""}, {"id": "c", "text": "\"I will watch for signs of both high and low blood sugar.\""}, {"id": "d", "text": "\"Now that I have the patch, I can stop checking my blood sugar.\""}]'::jsonb, '["d"]', 'Insulin delivery devices do not replace blood glucose checks, and patients still need frequent glucose monitoring. Monitoring for both hypoglycemia and hyperglycemia and inspecting the site daily are correct.'),
  ('patch', 13, 'A nurse is selecting a site for a client''s new insulin patch. Which site is most appropriate?', '[{"id": "a", "text": "Clean, dry, intact skin at a new site"}, {"id": "b", "text": "A slightly swollen area near the last site"}, {"id": "c", "text": "A healed surgical scar on the abdomen"}, {"id": "d", "text": "An area of mildly irritated skin"}]'::jsonb, '["a"]', 'The patch should not be placed over broken, irritated, infected, scarred, or swollen skin, and it is applied to clean, dry skin. Sites are rotated with every change.'),
  ('patch', 14, 'A nurse observes a client changing an insulin patch. Which action by the client requires correction?', '[{"id": "a", "text": "Checking that the new patch is attached correctly"}, {"id": "b", "text": "Washing hands before applying the new patch"}, {"id": "c", "text": "Applying the new patch before removing the old one"}, {"id": "d", "text": "Choosing a different site than the last patch"}]'::jsonb, '["c"]', 'The old patch is removed before a new one is applied to prevent accidental overdose. Hand washing, rotating sites, and checking attachment are correct.'),
  ('patch', 15, 'During assessment, a nurse notes that the edges of a client''s insulin patch are lifting and the patch is partly loose. How should the nurse interpret this finding?', '[{"id": "a", "text": "The patch is delivering a larger dose than set"}, {"id": "b", "text": "The finding is expected near the end of wear"}, {"id": "c", "text": "The client is at increased risk for hypoglycemia"}, {"id": "d", "text": "Insulin delivery from the patch may be reduced"}]'::jsonb, '["d"]', 'If the patch is loose or falling off, insulin delivery may be reduced, which can lead to hyperglycemia. A loose patch does not increase the delivered dose.'),
  ('patch', 16, 'A client asks whether it is all right to trim the insulin patch with scissors so it fits a smaller area. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Trimming is fine if you avoid the cannula area.\""}, {"id": "b", "text": "\"Trimming is fine if you tape the cut edges down.\""}, {"id": "c", "text": "\"Trimming is fine once the patch has been applied.\""}, {"id": "d", "text": "\"Do not cut, tear, or modify the patch in any way.\""}]'::jsonb, '["d"]', 'Patches must not be cut, torn, or modified. Altering the patch is unsafe regardless of where it is cut or how it is secured.'),
  ('patch', 17, 'A client asks how to handle a used insulin patch device after removing it. Which instruction by the nurse is correct?', '[{"id": "a", "text": "\"Keep it on until the new patch is working well.\""}, {"id": "b", "text": "\"Cut it open first to check for leftover insulin.\""}, {"id": "c", "text": "\"Reuse it once more if the skin under it looks healthy.\""}, {"id": "d", "text": "\"Discard it safely because it may contain a needle or cannula.\""}]'::jsonb, '["d"]', 'Used devices may contain needles or cannulas and should be discarded safely. Patches are not cut or modified, and the old patch is removed before applying a new one.'),
  ('patch', 18, 'A nurse is preparing to start a new insulin patch pump for a client. Which action best supports safe use?', '[{"id": "a", "text": "Leave the old patch on until the new one works"}, {"id": "b", "text": "Verify the insulin type, dose, and device settings"}, {"id": "c", "text": "Apply the patch over a healed scar for stability"}, {"id": "d", "text": "Trim the patch so it fits the chosen site better"}]'::jsonb, '["b"]', 'The nurse verifies the insulin type, dose, device settings, and patient understanding. Scarred skin is avoided, the old patch is removed first, and the patch is never trimmed.'),
  ('patch', 19, 'A client wearing an insulin patch pump becomes sweaty, tremulous, and confused, with a heart rate of 118/min. Which condition should the nurse suspect?', '[{"id": "a", "text": "Diabetic ketoacidosis"}, {"id": "b", "text": "Hyperglycemia"}, {"id": "c", "text": "Patch site infection"}, {"id": "d", "text": "Hypoglycemia"}]'::jsonb, '["d"]', 'Sweating, tremors, confusion, and tachycardia are signs of hypoglycemia. Hyperglycemia presents with thirst, frequent urination, fatigue, blurred vision, and nausea.'),
  ('patch', 20, 'A client with an insulin patch pump has a low blood glucose reading, is conscious, and can swallow. What is the nurse''s first action?', '[{"id": "a", "text": "Remove the pump and recheck in 1 hour"}, {"id": "b", "text": "Give 5 g of fast-acting carbohydrate"}, {"id": "c", "text": "Give 15 g of fast-acting carbohydrate"}, {"id": "d", "text": "Deliver a small correction bolus dose"}]'::jsonb, '["c"]', 'If the client is conscious and able to swallow, the nurse gives 15 g fast-acting carbohydrate, rechecks glucose in 15 minutes, and repeats if still low. A bolus adds insulin, and hypoglycemia is caused by too much insulin.'),
  ('patch', 21, 'A nurse gave 15 g of fast-acting carbohydrate to a conscious client with low blood glucose. When should the nurse recheck the glucose?', '[{"id": "a", "text": "In 5 minutes"}, {"id": "b", "text": "In 15 minutes"}, {"id": "c", "text": "In 1 hour"}, {"id": "d", "text": "In 4 hours"}]'::jsonb, '["b"]', 'After giving 15 g fast-acting carbohydrate, glucose is rechecked in 15 minutes and treatment is repeated if still low. Waiting an hour or more delays retreatment.'),
  ('patch', 22, 'Fifteen minutes after receiving 15 g of fast-acting carbohydrate, a conscious client''s blood glucose is still low. What should the nurse do next?', '[{"id": "a", "text": "Give another 15 g of fast-acting carbohydrate"}, {"id": "b", "text": "Remove the patch pump without a backup plan"}, {"id": "c", "text": "Wait 2 hours, then recheck the glucose"}, {"id": "d", "text": "Deliver a bolus dose to stabilize the glucose"}]'::jsonb, '["a"]', 'If glucose is still low on recheck, the 15 g fast-acting carbohydrate treatment is repeated. Insulin delivery should never be stopped without a backup plan, and a bolus adds more insulin.'),
  ('patch', 23, 'A client''s insulin patch failed overnight without the client noticing. Which findings would the nurse expect?', '[{"id": "a", "text": "Weakness, dizziness, and a seizure"}, {"id": "b", "text": "Sweating, tremors, and intense hunger"}, {"id": "c", "text": "Irritability, tachycardia, and shakiness"}, {"id": "d", "text": "Thirst, frequent urination, and blurred vision"}]'::jsonb, '["d"]', 'Patch failure can cause hyperglycemia, which presents with thirst, frequent urination, fatigue, and blurred vision. Sweating, tremors, hunger, and tachycardia are signs of hypoglycemia.'),
  ('patch', 24, 'A client''s insulin patch fell off several hours ago and was not replaced. Which finding suggests the client is developing DKA?', '[{"id": "a", "text": "Tremors and irritability"}, {"id": "b", "text": "Fruity breath and Kussmaul respirations"}, {"id": "c", "text": "Tachycardia and shakiness"}, {"id": "d", "text": "Sweating and intense hunger"}]'::jsonb, '["b"]', 'Fruity breath or Kussmaul respirations are listed hyperglycemia signs when DKA develops. Sweating, hunger, tremors, irritability, and tachycardia are signs of hypoglycemia.'),
  ('patch', 25, 'A nursing student asks why clients using patch pumps can develop DKA faster when delivery stops. Which explanation by the nurse is correct?', '[{"id": "a", "text": "\"Removing the pump causes the blood glucose to drop very low.\""}, {"id": "b", "text": "\"They usually have no long-acting insulin in the body as backup.\""}, {"id": "c", "text": "\"Their pumps contain long-acting insulin that wears off suddenly.\""}, {"id": "d", "text": "\"Patch pumps deliver insulin into the muscle instead of fat.\""}]'::jsonb, '["b"]', 'Pump and patch pump users usually receive rapid-acting insulin only and may not have long-acting insulin in the body as backup. Removing the pump causes hyperglycemia, not hypoglycemia.'),
  ('patch', 26, 'A client using an insulin patch pump has had several unexplained high blood glucose readings today. Which cause should the nurse investigate first?', '[{"id": "a", "text": "Extra exercise this morning"}, {"id": "b", "text": "An empty insulin reservoir"}, {"id": "c", "text": "An extra bolus dose at lunch"}, {"id": "d", "text": "A recently skipped meal"}]'::jsonb, '["b"]', 'Hyperglycemia with a patch may mean patch failure, blockage, empty reservoir, illness, or a missed bolus. Missed meals, exercise, and extra insulin are causes of hypoglycemia.'),
  ('patch', 27, 'A client wearing an insulin patch pump has a low blood glucose reading. Which history most likely explains this finding?', '[{"id": "a", "text": "The patch fell off overnight"}, {"id": "b", "text": "The cannula became blocked"}, {"id": "c", "text": "The client exercised and skipped lunch"}, {"id": "d", "text": "The insulin reservoir ran empty"}]'::jsonb, '["c"]', 'Hypoglycemia is caused by too much insulin, missed meals, exercise, or dosing error. A patch falling off, a blocked cannula, or an empty reservoir stops insulin delivery and causes hyperglycemia.'),
  ('patch', 28, 'A nurse is teaching a client about an insulin patch pump. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"Too much insulin is what causes low blood sugar.\""}, {"id": "b", "text": "\"If I take my pump off, my blood sugar will drop too low.\""}, {"id": "c", "text": "\"If my pump stops working, my blood sugar can rise quickly.\""}, {"id": "d", "text": "\"I need a backup insulin plan if the pump comes off.\""}]'::jsonb, '["b"]', 'Hypoglycemia happens from too much insulin, not from removing the pump; removing the pump stops insulin delivery and causes hyperglycemia and DKA risk.'),
  ('patch', 29, 'A client with an insulin patch pump plans to remove the device for an extended period during a weekend trip. What is the most important teaching?', '[{"id": "a", "text": "\"Skip glucose checks while the pump is removed.\""}, {"id": "b", "text": "\"Have a backup insulin plan before stopping delivery.\""}, {"id": "c", "text": "\"Carry extra snacks because your sugar will drop.\""}, {"id": "d", "text": "\"No plan is needed because pump insulin lasts all day.\""}]'::jsonb, '["b"]', 'Insulin delivery should never be stopped without a backup plan, because pump removal stops insulin and raises hyperglycemia and DKA risk. Removing the pump does not cause low blood glucose.'),
  ('patch', 30, 'A client who uses an insulin patch pump is admitted with DKA. Which factor in the client''s history most likely contributed?', '[{"id": "a", "text": "An extra correction bolus taken at dinner"}, {"id": "b", "text": "An increase in daily exercise this week"}, {"id": "c", "text": "Several skipped meals over the weekend"}, {"id": "d", "text": "An infection with illness over several days"}]'::jsonb, '["d"]', 'Infection or illness is a listed cause of DKA in pump users. Extra insulin, missed meals, and exercise are causes of hypoglycemia.'),
  ('patch', 31, 'A client with an insulin patch pump calls the clinic reporting flu symptoms and high glucose readings. Which instruction should the nurse reinforce?', '[{"id": "a", "text": "Check ketones as directed by the provider"}, {"id": "b", "text": "Stop checking glucose until feeling better"}, {"id": "c", "text": "Skip the next bolus to rest the infusion site"}, {"id": "d", "text": "Remove the patch until the illness resolves"}]'::jsonb, '["a"]', 'Ketones are checked if glucose is very high or if sick, per provider instructions. Removing the patch or skipping insulin stops delivery and increases hyperglycemia and DKA risk.'),
  ('patch', 32, 'A nurse is teaching a client how often to inspect the insulin patch site and device. Which frequency is correct?', '[{"id": "a", "text": "Daily"}, {"id": "b", "text": "Only at each patch change"}, {"id": "c", "text": "Only when an alarm sounds"}, {"id": "d", "text": "Weekly"}]'::jsonb, '["a"]', 'Clients are taught to inspect the site and device daily as part of DKA prevention. Waiting for an alarm or a scheduled change could miss a problem.'),
  ('patch', 33, 'Which statement by a client using an insulin patch indicates understanding of discharge teaching?', '[{"id": "a", "text": "\"I will buy backup insulin only if the patch stops working.\""}, {"id": "b", "text": "\"I keep backup insulin at home in case I ever need it.\""}, {"id": "c", "text": "\"I don''t need backup supplies because the patch holds insulin.\""}, {"id": "d", "text": "\"I keep backup insulin and supplies with me at all times.\""}]'::jsonb, '["d"]', 'Clients should carry backup insulin and supplies at all times. Keeping backup only at home or obtaining it after a failure leaves the client without insulin when delivery stops.'),
  ('patch', 34, 'A client with a new insulin pump asks how often the infusion set is usually changed. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Every 7 days, no matter which device you use\""}, {"id": "b", "text": "\"Every 12 hours, no matter which device you use\""}, {"id": "c", "text": "\"Every 2 to 3 days, unless your device instructions differ\""}, {"id": "d", "text": "\"Only when the insulin in the device runs out\""}]'::jsonb, '["c"]', 'Many pump infusion sets are changed every 2–3 days unless the device has different manufacturer instructions. Leaving sets on too long increases the risk of poor absorption and infection.'),
  ('patch', 35, 'A client reports leaving an insulin infusion site in place much longer than the device instructions allow. The nurse recognizes the client is at risk for which problem?', '[{"id": "a", "text": "Better absorption from a settled site"}, {"id": "b", "text": "Poor insulin absorption and infection"}, {"id": "c", "text": "No problem while the adhesive still sticks"}, {"id": "d", "text": "Faster absorption and low blood glucose"}]'::jsonb, '["b"]', 'Leaving infusion sites on too long increases the risk of poor absorption, infection, and site problems. It does not improve or speed absorption.'),
  ('patch', 36, 'A client places each new insulin patch on the same area of the abdomen. Which teaching should the nurse provide?', '[{"id": "a", "text": "\"Rotate sites with every patch change to prevent lipodystrophy.\""}, {"id": "b", "text": "\"Rotate sites only if the skin becomes red or swollen.\""}, {"id": "c", "text": "\"Rotate sites once a month when you see your provider.\""}, {"id": "d", "text": "\"Keep using the same area so absorption stays consistent.\""}]'::jsonb, '["a"]', 'Sites are rotated with every patch change to prevent lipodystrophy and inconsistent insulin absorption. Reusing the same area does not keep absorption consistent.'),
  ('patch', 37, 'A nurse is reviewing a client''s insulin patch pump supplies. Which insulin would the nurse expect to find in the device?', '[{"id": "a", "text": "Premixed insulin"}, {"id": "b", "text": "Intermediate-acting NPH"}, {"id": "c", "text": "Insulin lispro (Humalog)"}, {"id": "d", "text": "Long-acting insulin"}]'::jsonb, '["c"]', 'Most pumps and patch pumps use rapid-acting insulin such as insulin lispro (Humalog). Pump users usually do not have long-acting insulin in the body as backup.'),
  ('patch', 38, 'A nurse is preparing a vial of insulin aspart (NovoLog) to fill a client''s patch pump. The insulin is clear. Which action is appropriate?', '[{"id": "a", "text": "Discard it because it should be cloudy"}, {"id": "b", "text": "Use it without rolling"}, {"id": "c", "text": "Roll it gently between the palms"}, {"id": "d", "text": "Turn it until it looks evenly cloudy"}]'::jsonb, '["b"]', 'Rapid-acting insulin such as aspart is clear and is not rolled. Gentle rolling is used for cloudy insulins such as NPH and premixed insulin.'),
  ('patch', 39, 'A nurse is preparing a dose of premixed insulin that appears cloudy. Which action is appropriate?', '[{"id": "a", "text": "Draw up only the clear liquid at the top"}, {"id": "b", "text": "Gently roll the insulin before use"}, {"id": "c", "text": "Discard it because insulin must be clear"}, {"id": "d", "text": "Use it without mixing because it is premixed"}]'::jsonb, '["b"]', 'Premixed insulin may be cloudy and is gently rolled before use. Only clear insulin, such as rapid-acting insulin, is used without rolling.'),
  ('patch', 40, 'A nurse is reviewing travel plans with a client who uses an insulin patch pump. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll leave my extra insulin in the car while I''m at the beach.\""}, {"id": "b", "text": "\"I''ll pack backup insulin and supplies in my carry bag.\""}, {"id": "c", "text": "\"I''ll keep my insulin out of direct sunlight while traveling.\""}, {"id": "d", "text": "\"I''ll keep my unopened insulin in the refrigerator as directed.\""}]'::jsonb, '["a"]', 'Insulin should not be left in a hot car because temperature extremes reduce its effectiveness. Refrigerating unopened insulin, avoiding sunlight, and carrying backup supplies are correct.'),
  ('patch', 41, 'A client asks how to store unopened insulin for a patch pump at home. Which instruction by the nurse is correct?', '[{"id": "a", "text": "\"Freeze it so that it lasts longer before use.\""}, {"id": "b", "text": "\"Store it as directed, usually in the refrigerator.\""}, {"id": "c", "text": "\"Keep it in the car so it is always available.\""}, {"id": "d", "text": "\"Keep it on a sunny windowsill so it stays warm.\""}]'::jsonb, '["b"]', 'Unopened insulin is stored as directed, usually refrigerated. Insulin is never frozen and is kept away from heat, direct sunlight, and hot cars.'),
  ('patch', 42, 'A nurse observes a client preparing to apply a new insulin patch. Which action by the client requires correction?', '[{"id": "a", "text": "Pressing the patch to check it is attached correctly"}, {"id": "b", "text": "Selecting a new site away from the last patch"}, {"id": "c", "text": "Applying body lotion to the site just before the patch"}, {"id": "d", "text": "Washing hands before handling the new patch"}]'::jsonb, '["c"]', 'The patch is applied to clean, dry skin, avoiding lotions, oils, or creams under the adhesive. Hand washing, rotating sites, and checking attachment are correct.'),
  ('patch', 43, 'A nurse is teaching a client how to change an insulin patch. Which sequence is correct?', '[{"id": "a", "text": "Apply new patch over lotion at the same site, remove old patch, wash hands, check attachment"}, {"id": "b", "text": "Wash hands, remove old patch, apply new patch to clean dry skin at a new site, check attachment"}, {"id": "c", "text": "Remove old patch, apply new patch at the same site, check attachment, wash hands"}, {"id": "d", "text": "Wash hands, apply new patch at a new site, remove old patch, check attachment"}]'::jsonb, '["b"]', 'Hands are washed before applying the patch, the old patch is removed before applying a new one to prevent overdose, and the new patch goes on clean, dry skin at a rotated site and is checked for attachment.'),
  ('patch', 44, 'A nurse is teaching a client which problems with an insulin patch to report. Which finding should the client report?', '[{"id": "a", "text": "A single reading within target range"}, {"id": "b", "text": "Clear rapid-acting insulin in the device"}, {"id": "c", "text": "Repeated high blood glucose readings"}, {"id": "d", "text": "A patch that stays firmly attached"}]'::jsonb, '["c"]', 'Clients report repeated high blood glucose, patch failure, signs of infection, or symptoms of DKA. Target-range readings, clear rapid-acting insulin, and firm adhesion are expected.'),
  ('patch', 45, 'A nurse assesses the site of a client''s insulin patch. Which finding requires follow-up?', '[{"id": "a", "text": "Adhesive firmly attached to the skin"}, {"id": "b", "text": "Redness and swelling around the site"}, {"id": "c", "text": "No leakage around the patch border"}, {"id": "d", "text": "Clean, dry, intact skin under the edges"}]'::jsonb, '["b"]', 'The patch site is assessed for redness, pain, swelling, leakage, or infection. Firm adhesion, intact skin, and no leakage are expected findings.'),
  ('patch', 46, 'A client with an insulin patch pump has high blood glucose, nausea, and fruity breath. The nurse finds that the insulin reservoir is empty. Which complication is the client at greatest risk for?', '[{"id": "a", "text": "Skin irritation"}, {"id": "b", "text": "Hypoglycemia"}, {"id": "c", "text": "Lipodystrophy"}, {"id": "d", "text": "Diabetic ketoacidosis"}]'::jsonb, '["d"]', 'If the pump runs out of insulin, the patient can develop hyperglycemia and DKA faster, and fruity breath suggests DKA. Hypoglycemia is caused by too much insulin, not by an empty reservoir.'),
  ('patch', 47, 'A nurse documents that a client''s adherence improved after switching to an insulin patch. What does this documentation indicate?', '[{"id": "a", "text": "The client follows the prescribed treatment plan"}, {"id": "b", "text": "The device now delivers basal insulin only"}, {"id": "c", "text": "The patch adhesive sticks firmly to the skin"}, {"id": "d", "text": "The client has had no low glucose episodes"}]'::jsonb, '["a"]', 'Adherence means following the prescribed treatment plan. It does not refer to how well the patch adhesive sticks to the skin.'),
  ('patch', 48, 'A client using an insulin patch pump asks what causes diabetic ketoacidosis. Which response by the nurse is correct?', '[{"id": "a", "text": "\"A lack of insulin in the body\""}, {"id": "b", "text": "\"Missing a meal or snack\""}, {"id": "c", "text": "\"Doing extra exercise\""}, {"id": "d", "text": "\"Taking too much insulin\""}]'::jsonb, '["a"]', 'DKA is a dangerous complication from lack of insulin. Too much insulin, missed meals, and exercise are causes of hypoglycemia.'),
  ('patch', 49, 'A nurse is planning care for a client newly started on an insulin patch pump. Which monitoring should the nurse include?', '[{"id": "a", "text": "Monitor for hyperglycemia only, since doses are small"}, {"id": "b", "text": "Monitor for both hypoglycemia and hyperglycemia"}, {"id": "c", "text": "Stop glucose monitoring once a CGM is in place"}, {"id": "d", "text": "Monitor for hypoglycemia only, since delivery is constant"}]'::jsonb, '["b"]', 'Clients using insulin patches are monitored for both hypoglycemia and hyperglycemia. A CGM checks trends but does not replace all safety checks.'),
  ('patch', 50, 'A client with diabetes who needs insulin is discussing an insulin patch with the nurse. Which client statement reflects an appropriate reason for choosing one?', '[{"id": "a", "text": "\"I no longer want to carry backup insulin.\""}, {"id": "b", "text": "\"I want to never have low blood sugar again.\""}, {"id": "c", "text": "\"I want to stop checking my blood sugar.\""}, {"id": "d", "text": "\"I want a more discreet way to take my insulin.\""}]'::jsonb, '["d"]', 'A desire for a more discreet or convenient insulin delivery method is an indication for a patch. Patch users still need glucose checks, backup insulin, and monitoring for hypoglycemia.'),
  ('storage', 1, 'A nurse receives a pharmacy delivery of unopened insulin vials for the unit. Which storage action is appropriate?', '[{"id": "a", "text": "Place the vials in the freezer compartment to extend shelf life"}, {"id": "b", "text": "Place the vials in the refrigerator at 2–8°C (36–46°F)"}, {"id": "c", "text": "Place the vials on the counter at room temperature until needed"}, {"id": "d", "text": "Place the vials against the back wall of the refrigerator"}]'::jsonb, '["b"]', 'Unopened insulin vials are stored in the refrigerator at 2–8°C / 36–46°F. Insulin must never be frozen and should be kept away from the freezer compartment and back wall of the refrigerator.'),
  ('storage', 2, 'A client who keeps unopened insulin vials in the refrigerator asks how long they remain usable. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Until the expiration date printed on the package\""}, {"id": "b", "text": "\"For 6 months, regardless of the printed date\""}, {"id": "c", "text": "\"For 28 days from the date you picked them up\""}, {"id": "d", "text": "\"For 7 days after you place them in the refrigerator\""}]'::jsonb, '["a"]', 'When stored correctly, unopened insulin is usually good until the expiration date printed on the package. The 28-day limit applies after a vial is opened, not to unopened refrigerated vials.'),
  ('storage', 3, 'A nurse is organizing the unit medication refrigerator that holds both opened and unopened insulin vials. Which arrangement is appropriate?', '[{"id": "a", "text": "All vials grouped together near the cooling vent to stay cold"}, {"id": "b", "text": "Opened vials on one side and unopened vials on the other side"}, {"id": "c", "text": "Opened vials stored in the freezer door to slow expiration"}, {"id": "d", "text": "Unopened vials lined up against the back wall of the refrigerator"}]'::jsonb, '["b"]', 'The refrigerator should be organized with opened vials on one side and unopened vials on the other. Insulin should be kept away from the freezer compartment, back wall, and cooling vent.'),
  ('storage', 4, 'A nurse is teaching a client with diabetes about home insulin storage. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "\"I''ll write the date I open each vial on its label.\""}, {"id": "b", "text": "\"I''ll keep my spare insulin in the glove compartment of my car.\""}, {"id": "c", "text": "\"I''ll keep my unopened vials in the refrigerator.\""}, {"id": "d", "text": "\"I''ll keep my insulin away from the freezer compartment.\""}]'::jsonb, '["b"]', 'Insulin should never be stored in a car because heat and cold extremes can damage it and make it less effective. Refrigerating unopened vials, avoiding the freezer, and labeling the opening date are all correct.'),
  ('storage', 5, 'A nurse finds an insulin vial that was stored against the back wall of the refrigerator. The insulin now contains small crystals. What is the nurse''s best action?', '[{"id": "a", "text": "Warm the vial in hot water until the crystals dissolve"}, {"id": "b", "text": "Roll the vial firmly until the crystals disappear"}, {"id": "c", "text": "Let the vial sit at room temperature, then use it"}, {"id": "d", "text": "Discard the vial and obtain a new one"}]'::jsonb, '["d"]', 'Insulin of any type that contains clumps, particles, or crystals is discarded because it may be contaminated or frozen. Heat must never be used to warm insulin, and abnormal insulin should not be used.'),
  ('storage', 6, 'A nurse is about to administer insulin from a vial. Which information must the nurse check before use?', '[{"id": "a", "text": "The vial''s lot number and manufacturer name only"}, {"id": "b", "text": "The vial''s temperature and the color of its cap only"}, {"id": "c", "text": "The insulin type, concentration, and expiration date"}, {"id": "d", "text": "The expiration date only, since the type is on the order"}]'::jsonb, '["c"]', 'The nurse should always check the insulin type, concentration, and expiration date before use. Checking only the expiration date misses the type and concentration.'),
  ('storage', 7, 'During a medication room check, a nurse finds a vial of insulin that is past its expiration date. Which action is appropriate?', '[{"id": "a", "text": "Use the vial until the end of the shift"}, {"id": "b", "text": "Use the vial if the insulin looks normal"}, {"id": "c", "text": "Return it to the refrigerator for pharmacy pickup"}, {"id": "d", "text": "Discard the vial immediately and document"}]'::jsonb, '["d"]', 'Expired or abnormal insulin is discarded immediately and documented. A normal appearance does not make expired insulin acceptable to use.'),
  ('storage', 8, 'A nurse punctures a new multidose insulin vial for the first time. What should the nurse do next with the vial?', '[{"id": "a", "text": "Label it with the date opened and the discard date"}, {"id": "b", "text": "Leave it unlabeled because it will be refrigerated"}, {"id": "c", "text": "Label it with the client''s initials only"}, {"id": "d", "text": "Label it with the printed expiration date only"}]'::jsonb, '["a"]', 'Once a vial is opened or punctured, it is labeled with the date opened and the discard date. Refrigeration does not remove the need to label because opened insulin is usually discarded after 28 days either way.'),
  ('storage', 9, 'A nurse finds a labeled vial of insulin that was opened 30 days ago. The insulin appears normal, and no special manufacturer or facility instructions apply. What should the nurse do?', '[{"id": "a", "text": "Discard the vial because it is past 28 days"}, {"id": "b", "text": "Use the vial because the insulin looks normal"}, {"id": "c", "text": "Relabel the vial with a new discard date"}, {"id": "d", "text": "Use the vial because it has been refrigerated"}]'::jsonb, '["a"]', 'Most opened insulin vials are discarded after 28 days unless the manufacturer or facility policy says otherwise. A normal appearance or refrigeration does not extend this limit.'),
  ('storage', 10, 'A client states, "I keep my opened insulin in the refrigerator, so it will last until the date printed on the box." Which response by the nurse is best?', '[{"id": "a", "text": "\"Opened insulin is usually discarded after 28 days, even if refrigerated.\""}, {"id": "b", "text": "\"Opened insulin lasts 28 days only if it is kept at room temperature.\""}, {"id": "c", "text": "\"Opened insulin should be thrown away after 7 days in the refrigerator.\""}, {"id": "d", "text": "\"That''s correct, because refrigeration keeps opened insulin good until expiration.\""}]'::jsonb, '["a"]', 'Opened insulin is usually discarded after 28 days whether it is refrigerated or kept at room temperature. The printed expiration date applies to correctly stored unopened insulin.'),
  ('storage', 11, 'A nurse finds an opened insulin vial in the medication refrigerator with no date-opened label. What is the appropriate action?', '[{"id": "a", "text": "Label it with today''s date and continue using it"}, {"id": "b", "text": "Use it if the insulin looks clear and normal"}, {"id": "c", "text": "Do not use it, and discard it per facility policy"}, {"id": "d", "text": "Use it once, then discard it at the end of the day"}]'::jsonb, '["c"]', 'If the opening date is unknown, the insulin is not used and is discarded per facility policy. Labeling it with today''s date would hide the true opening date.'),
  ('storage', 12, 'A client plans to keep an opened insulin vial at room temperature. The nurse teaches that the storage temperature should remain below which level?', '[{"id": "a", "text": "30°C (86°F)"}, {"id": "b", "text": "37°C (98.6°F)"}, {"id": "c", "text": "40°C (104°F)"}, {"id": "d", "text": "45°C (113°F)"}]'::jsonb, '["a"]', 'Opened insulin stored at room temperature should be kept below 30°C / 86°F. Higher temperatures expose insulin to heat that can make it less effective.'),
  ('storage', 13, 'A client keeps an opened insulin vial at room temperature at home. Which storage location should the nurse recommend?', '[{"id": "a", "text": "A bedroom shelf directly above a heater vent"}, {"id": "b", "text": "A kitchen cabinet away from the stove and windows"}, {"id": "c", "text": "A shelf next to the stove for use at mealtimes"}, {"id": "d", "text": "A sunny windowsill where it is easy to see"}]'::jsonb, '["b"]', 'Insulin should be kept away from direct sunlight and heat sources because heat and sunlight can make it less effective. Windowsills, stoves, and heater vents expose insulin to heat or sunlight.'),
  ('storage', 14, 'A client asks why the nurse suggested keeping the opened insulin vial at room temperature instead of in the refrigerator. Which response is accurate?', '[{"id": "a", "text": "\"Room-temperature insulin can be used beyond 28 days.\""}, {"id": "b", "text": "\"Room-temperature insulin may be more comfortable to inject.\""}, {"id": "c", "text": "\"Room-temperature insulin does not need to be inspected.\""}, {"id": "d", "text": "\"Room-temperature insulin does not need a discard label.\""}]'::jsonb, '["b"]', 'Room-temperature insulin may be more comfortable to inject than cold insulin. It still must be labeled, inspected, and is usually discarded after 28 days.'),
  ('storage', 15, 'A client reports that injections of insulin taken straight from the refrigerator are uncomfortable. Which action should the nurse take before the next injection?', '[{"id": "a", "text": "Set the vial in direct sunlight until it feels warm"}, {"id": "b", "text": "Warm the vial in the microwave for a few seconds"}, {"id": "c", "text": "Place the vial in a cup of hot water for several minutes"}, {"id": "d", "text": "Let the vial reach room temperature or roll it gently in the palms"}]'::jsonb, '["d"]', 'Refrigerated insulin can be allowed to reach room temperature or gently rolled in the palms to reduce discomfort. Heat sources such as a microwave, hot water, or sunlight must never be used.'),
  ('storage', 16, 'A nurse is supervising a nursing student who is preparing insulin. Which action by the student requires correction?', '[{"id": "a", "text": "Inspecting a vial of clear insulin before drawing it up"}, {"id": "b", "text": "Placing a cold vial in a cup of hot water to warm it"}, {"id": "c", "text": "Rolling an NPH vial gently between the palms"}, {"id": "d", "text": "Labeling a newly punctured vial with the discard date"}]'::jsonb, '["b"]', 'Heat must never be used to warm insulin, including placing it in hot water. Gently rolling NPH, inspecting insulin, and labeling opened vials are correct actions.'),
  ('storage', 17, 'A client says, "I shake my insulin vial hard before every dose so it''s well mixed." Which response by the nurse is best?', '[{"id": "a", "text": "\"Shaking can create bubbles or foam that may affect dose accuracy.\""}, {"id": "b", "text": "\"Shaking is fine as long as the vial was warmed first.\""}, {"id": "c", "text": "\"Shaking is needed only for clear insulins such as Regular.\""}, {"id": "d", "text": "\"Shaking works better than rolling for cloudy NPH insulin.\""}]'::jsonb, '["a"]', 'Insulin should never be shaken because shaking can create bubbles or foam and may affect accurate dosing. Cloudy NPH is gently rolled and inverted, and clear insulin is not mixed.'),
  ('storage', 18, 'A nurse is preparing a dose of NPH insulin from a vial. Which technique is correct?', '[{"id": "a", "text": "Warm the vial in hot water until the insulin turns clear"}, {"id": "b", "text": "Shake the vial firmly until foam forms at the top"}, {"id": "c", "text": "Leave the vial still and draw from the clear top layer"}, {"id": "d", "text": "Gently roll and invert the vial until it looks evenly cloudy"}]'::jsonb, '["d"]', 'Cloudy insulin such as NPH is gently rolled between the palms and gently turned or inverted until it looks evenly cloudy. Shaking creates bubbles or foam, and heat must never be used.'),
  ('storage', 19, 'A nurse is preparing a dose of Regular insulin. After confirming the order and the vial, which action is appropriate?', '[{"id": "a", "text": "Roll the vial between the palms until it turns cloudy"}, {"id": "b", "text": "Invert the vial repeatedly until it looks milky"}, {"id": "c", "text": "Inspect the insulin, then draw it up without rolling"}, {"id": "d", "text": "Shake the vial gently to mix the contents evenly"}]'::jsonb, '["c"]', 'Clear insulin such as Regular is not mixed or rolled; it is ready to use after inspection. Rolling until cloudy applies to NPH, not clear insulin.'),
  ('storage', 20, 'A nurse gently rolls a vial of NPH insulin and then inspects it. Which finding is expected?', '[{"id": "a", "text": "Evenly cloudy, milky appearance with no clumps"}, {"id": "b", "text": "Cloudy appearance with crystals on the glass"}, {"id": "c", "text": "Cloudy appearance with small white clumps"}, {"id": "d", "text": "Clear, colorless appearance with no particles"}]'::jsonb, '["a"]', 'After gentle mixing, NPH should look evenly cloudy or milky with no clumps or particles. Clumps or crystals mean the insulin must be discarded.'),
  ('storage', 21, 'While preparing a dose, a nurse notices that a vial labeled Regular insulin appears cloudy. What should the nurse do?', '[{"id": "a", "text": "Use the vial because cloudiness is expected"}, {"id": "b", "text": "Let the vial rest, then draw from the clear top layer"}, {"id": "c", "text": "Roll the vial gently until it looks evenly cloudy"}, {"id": "d", "text": "Discard the vial immediately and document the incident"}]'::jsonb, '["d"]', 'Regular insulin should always be clear; cloudy Regular insulin is degraded and is discarded immediately with the incident documented. Rolling until evenly cloudy is the technique for NPH only.'),
  ('storage', 22, 'A client using insulin glargine (Lantus) shows the nurse a vial that is clear and colorless with no particles. How should the nurse interpret this finding?', '[{"id": "a", "text": "It must be rolled until it becomes evenly cloudy"}, {"id": "b", "text": "It is normal and can be used as-is without rolling"}, {"id": "c", "text": "It must be shaken briefly to activate the insulin"}, {"id": "d", "text": "It is abnormal because glargine should be cloudy"}]'::jsonb, '["b"]', 'Long-acting glargine (Lantus) is a clear insulin; clear insulin is normal, is not rolled, and is ready to use after inspection. Rolling until evenly cloudy applies to NPH.'),
  ('storage', 23, 'A nurse accidentally shakes a vial of insulin, and foam forms at the top. What is the nurse''s first action?', '[{"id": "a", "text": "Allow the vial to rest undisturbed until the foam disappears"}, {"id": "b", "text": "Draw up the dose quickly before the foam spreads"}, {"id": "c", "text": "Tap the vial firmly to break up the bubbles"}, {"id": "d", "text": "Discard the vial immediately without further inspection"}]'::jsonb, '["a"]', 'If insulin is accidentally shaken, the vial is allowed to rest undisturbed until bubbles or foam disappear, and then it is inspected. Discarding is required only if the appearance is abnormal or the foam does not settle.'),
  ('storage', 24, 'A vial of insulin was accidentally shaken and left to rest, but the foam has not settled. Which action is appropriate?', '[{"id": "a", "text": "Draw the dose from below the foam layer"}, {"id": "b", "text": "Shake the vial again to break the bubbles"}, {"id": "c", "text": "Discard the vial and use a new vial"}, {"id": "d", "text": "Warm the vial gently to dissolve the foam"}]'::jsonb, '["c"]', 'If bubbles or foam do not settle, or the appearance is abnormal, the vial is discarded and a new vial is used. Heat and shaking must never be used on insulin.'),
  ('storage', 25, 'A vial of rapid-acting insulin was accidentally shaken and has rested until the bubbles disappeared. Which appearance allows the nurse to use it?', '[{"id": "a", "text": "Slightly yellow but free of particles"}, {"id": "b", "text": "Clear with a few small crystals"}, {"id": "c", "text": "Clear, colorless, and free of particles"}, {"id": "d", "text": "Evenly cloudy and milky throughout"}]'::jsonb, '["c"]', 'Clear insulin must remain clear, colorless, and free of particles after being accidentally shaken. Evenly cloudy is expected only for NPH, and discoloration or crystals require discarding.'),
  ('storage', 26, 'A nurse inspects several insulin vials before drawing up doses. Which finding means the nurse should NOT use the vial?', '[{"id": "a", "text": "Glargine insulin that is clear with no particles"}, {"id": "b", "text": "NPH insulin that is evenly milky after rolling"}, {"id": "c", "text": "Regular insulin with a yellowish discoloration"}, {"id": "d", "text": "Rapid-acting insulin that is clear and colorless"}]'::jsonb, '["c"]', 'Insulin should not be used if it has clumps, particles, crystals, discoloration, or an abnormal appearance. Evenly cloudy NPH and clear rapid-acting or glargine insulin are normal.'),
  ('storage', 27, 'A nursing student is reviewing insulin preparation. Which statement by the student shows correct understanding?', '[{"id": "a", "text": "\"Clear and cloudy insulins are both shaken before use.\""}, {"id": "b", "text": "\"Clear insulin is gently rolled; cloudy insulin is not rolled.\""}, {"id": "c", "text": "\"Cloudy insulin is discarded; only clear insulin is used.\""}, {"id": "d", "text": "\"Clear insulin is not rolled; cloudy insulin is gently rolled.\""}]'::jsonb, '["d"]', 'The memory tip is "Clear = Don''t Roll. Cloudy = Gently Roll." NPH is expected to be cloudy, and rolling mixes the suspension evenly; insulin is never shaken.'),
  ('storage', 28, 'A client who uses an insulin patch pump asks which insulin the pod is filled with. Which response by the nurse is correct?', '[{"id": "a", "text": "\"Intermediate-acting NPH insulin\""}, {"id": "b", "text": "\"Rapid-acting U-100 insulin\""}, {"id": "c", "text": "\"A mixture of NPH and glargine\""}, {"id": "d", "text": "\"Long-acting glargine insulin\""}]'::jsonb, '["b"]', 'Insulin patch pumps contain rapid-acting U-100 insulin. Because pumps rely on rapid-acting insulin, interrupted delivery can cause blood glucose to rise quickly.'),
  ('storage', 29, 'A client new to an insulin patch pump asks how often the pod site is usually changed. Which response is accurate?', '[{"id": "a", "text": "\"Only when the pod runs out of insulin\""}, {"id": "b", "text": "\"Usually every 2 to 3 days, per the device instructions\""}, {"id": "c", "text": "\"Usually every 12 hours, regardless of the device\""}, {"id": "d", "text": "\"Usually every 7 days, regardless of the device\""}]'::jsonb, '["b"]', 'The pod or patch pump site is usually changed every 2–3 days, up to 72 hours, depending on the device and manufacturer instructions. Waiting until insulin runs out ignores the site-change schedule.'),
  ('storage', 30, 'A client reports that the insulin patch pump stopped delivering insulin several hours ago. The nurse recognizes the client is at greatest risk for which problem?', '[{"id": "a", "text": "Frozen insulin remaining inside the pod"}, {"id": "b", "text": "A rapid rise in blood glucose leading to ketones/DKA"}, {"id": "c", "text": "A sudden drop in blood glucose from stored insulin"}, {"id": "d", "text": "Lipodystrophy at the most recent pod site"}]'::jsonb, '["b"]', 'Because pumps use only rapid-acting insulin, interrupted delivery can cause blood glucose to rise quickly and may lead to ketones/DKA. A drop in glucose is not the expected result of stopped delivery.'),
  ('storage', 31, 'A client''s patch pump is not due for a site change for another day. Which finding indicates the pod should be changed sooner?', '[{"id": "a", "text": "Adhesive firmly attached with no drainage"}, {"id": "b", "text": "Pod placed on a newly rotated site"}, {"id": "c", "text": "Blood glucose readings within target range"}, {"id": "d", "text": "Unexplained high blood glucose readings"}]'::jsonb, '["d"]', 'The pod or site is changed sooner if there is unexplained high blood glucose, as well as redness, swelling, pain, leakage, loose adhesive, or an alarm. Target-range readings and firm adhesion are expected findings.'),
  ('storage', 32, 'A nurse assesses a client''s insulin pod and finds redness, swelling, and loose adhesive at the site. The pod was placed yesterday. What is the nurse''s best action?', '[{"id": "a", "text": "Leave the pod until its scheduled change tomorrow"}, {"id": "b", "text": "Replace the pod at the same site for consistency"}, {"id": "c", "text": "Change the pod now and place it at a new site"}, {"id": "d", "text": "Wait for a pod alarm before changing the device"}]'::jsonb, '["c"]', 'Redness, swelling, and loose adhesive call for changing the pod or site sooner, and sites are rotated with each change. Waiting for the scheduled change or an alarm delays needed action.'),
  ('storage', 33, 'A client using an insulin patch pump places each new pod on the same spot on the abdomen because it is convenient. Which teaching is most appropriate?', '[{"id": "a", "text": "\"Rotate sites with each change to protect your skin and absorption.\""}, {"id": "b", "text": "\"Rotate sites only if the pod alarm goes off.\""}, {"id": "c", "text": "\"Rotate sites only once a month to reduce irritation.\""}, {"id": "d", "text": "\"Using the same spot is best for steady insulin absorption.\""}]'::jsonb, '["a"]', 'Sites are rotated with each change to protect the skin and improve insulin absorption. Using the same spot does not improve absorption.'),
  ('storage', 34, 'A nurse enters a client''s room to perform a fingerstick blood glucose check. What is the nurse''s first action?', '[{"id": "a", "text": "Perform hand hygiene and apply gloves"}, {"id": "b", "text": "Prick the side of the client''s fingertip"}, {"id": "c", "text": "Clean the fingertip with an alcohol swab"}, {"id": "d", "text": "Insert the test strip into the meter"}]'::jsonb, '["a"]', 'The fingerstick protocol begins with hand hygiene and applying gloves. Inserting the strip, cleaning the fingertip, and pricking the finger come later in the sequence.'),
  ('storage', 35, 'A nurse has performed hand hygiene, put on gloves, and identified the client. Which action should the nurse take before inserting the test strip into the meter?', '[{"id": "a", "text": "Check the meter, strip expiration date, and supplies"}, {"id": "b", "text": "Wipe away the first drop of blood"}, {"id": "c", "text": "Prick the side of the fingertip with a lancet"}, {"id": "d", "text": "Apply clean gauze to the fingertip"}]'::jsonb, '["a"]', 'After identifying the patient and verifying the order, the nurse checks the glucose meter, test strip expiration date, and supplies, then inserts the strip. Pricking the finger and handling blood drops come after the strip is inserted.'),
  ('storage', 36, 'A nurse observes a colleague performing a fingerstick glucose check. Which action by the colleague requires correction?', '[{"id": "a", "text": "Pricking the side of the fingertip with a lancet"}, {"id": "b", "text": "Pricking the finger while the alcohol is still wet"}, {"id": "c", "text": "Applying clean gauze after obtaining the sample"}, {"id": "d", "text": "Inserting the test strip before pricking the finger"}]'::jsonb, '["b"]', 'The fingertip is cleaned with an alcohol swab and allowed to dry completely before pricking. Alcohol on the finger can contaminate the blood drop and give an inaccurate reading.'),
  ('storage', 37, 'A nurse is about to obtain a fingerstick blood glucose sample. Where should the nurse puncture the finger?', '[{"id": "a", "text": "The center of the palm"}, {"id": "b", "text": "The base of the finger"}, {"id": "c", "text": "The center of the fingertip"}, {"id": "d", "text": "The side of the fingertip"}]'::jsonb, '["d"]', 'The side of the fingertip, not the center, is pricked with a lancet. The base of the finger is where gentle squeezing begins if more blood is needed.'),
  ('storage', 38, 'After pricking a client''s finger, a nurse sees that the blood drop is too small for the test strip. Which action is appropriate?', '[{"id": "a", "text": "Gently squeeze from the base of the finger"}, {"id": "b", "text": "Prick the center of the same fingertip"}, {"id": "c", "text": "Milk the fingertip firmly and repeatedly"}, {"id": "d", "text": "Squeeze hard directly at the puncture site"}]'::jsonb, '["a"]', 'If needed, the nurse gently squeezes from the base of the finger but does not milk the finger aggressively. Squeezing too hard can add tissue fluid to the sample and cause an inaccurate reading.'),
  ('storage', 39, 'A facility policy requires wiping away the first drop of blood during fingerstick glucose testing. Which drop should the nurse place on the test strip?', '[{"id": "a", "text": "The first drop of blood"}, {"id": "b", "text": "The third drop of blood"}, {"id": "c", "text": "Any drop once bleeding slows"}, {"id": "d", "text": "The second drop of blood"}]'::jsonb, '["d"]', 'When the first drop is wiped away per facility policy, the second drop is placed on the test strip. Many facilities use the second drop for better accuracy.'),
  ('storage', 40, 'A nursing student asks why some facilities require wiping away the first drop of blood during a fingerstick. Which explanation by the nurse is accurate?', '[{"id": "a", "text": "\"It may damage the meter if placed on the strip.\""}, {"id": "b", "text": "\"It contains too much insulin to read accurately.\""}, {"id": "c", "text": "\"It clots too quickly to reach the test strip.\""}, {"id": "d", "text": "\"It may contain alcohol, skin residue, or tissue fluid.\""}]'::jsonb, '["d"]', 'The first drop may be contaminated with alcohol, skin residue, or tissue fluid, especially if the finger was squeezed too hard, which can give an inaccurate reading. This is why many facilities use the second drop.'),
  ('storage', 41, 'A nurse has just placed a drop of blood on the test strip during a fingerstick glucose check. How should the nurse manage the puncture site?', '[{"id": "a", "text": "Squeeze the finger again to clear the puncture"}, {"id": "b", "text": "Prick a second finger to confirm the bleeding stops"}, {"id": "c", "text": "Apply clean gauze or cotton, and a bandage if needed"}, {"id": "d", "text": "Leave the site uncovered so it can bleed freely"}]'::jsonb, '["c"]', 'After the sample is placed on the strip, clean gauze or cotton is applied to stop bleeding, with a bandage if needed. Leaving the site to bleed or squeezing it again is not part of the protocol.'),
  ('storage', 42, 'A nurse is performing a fingerstick blood glucose check. Which sequence of steps is correct?', '[{"id": "a", "text": "Prick center of fingertip, insert strip, clean finger, place second drop"}, {"id": "b", "text": "Insert strip, prick side of fingertip, clean finger, place first drop"}, {"id": "c", "text": "Clean finger, prick side of fingertip, place first drop, insert strip"}, {"id": "d", "text": "Insert strip, clean finger and let dry, prick side of fingertip, place second drop"}]'::jsonb, '["d"]', 'The strip is inserted, the fingertip is cleaned with alcohol and allowed to dry, the side of the fingertip is pricked, and the second drop is placed on the strip. Cleaning after pricking or pricking the center are incorrect.'),
  ('storage', 43, 'A nurse reads a client''s fingerstick blood glucose result, and it is abnormal. After documenting the result, what should the nurse do?', '[{"id": "a", "text": "Report or treat the result according to protocol"}, {"id": "b", "text": "Repeat the test by pricking the center of the finger"}, {"id": "c", "text": "Wait until the next scheduled check to address it"}, {"id": "d", "text": "Discard the result because it may be inaccurate"}]'::jsonb, '["a"]', 'The final step of the protocol is to report or treat abnormal blood glucose results according to protocol. Waiting or discarding the result delays care.'),
  ('storage', 44, 'In a hospital setting, a nurse has performed hand hygiene and applied gloves before a fingerstick glucose check. What is the nurse''s next action?', '[{"id": "a", "text": "Identify the client and verify the order"}, {"id": "b", "text": "Read the result from the glucose meter"}, {"id": "c", "text": "Clean the fingertip with an alcohol swab"}, {"id": "d", "text": "Insert the test strip into the meter"}]'::jsonb, '["a"]', 'After hand hygiene and gloves, the nurse identifies the patient and verifies the order in a clinical setting. Checking supplies, inserting the strip, and cleaning the fingertip follow.'),
  ('storage', 45, 'A nurse observes a nursing student completing a fingerstick glucose check. Which action by the student requires correction?', '[{"id": "a", "text": "Reading the result after applying gauze to the site"}, {"id": "b", "text": "Documenting the blood glucose result"}, {"id": "c", "text": "Dropping the used lancet into the bedside trash can"}, {"id": "d", "text": "Removing gloves and performing hand hygiene"}]'::jsonb, '["c"]', 'The lancet must be disposed of in a sharps container, and contaminated supplies discarded. Reading the result, removing gloves, hand hygiene, and documenting are correct steps.'),
  ('storage', 46, 'A client who injects insulin at home reports always using the same spot on the thigh. Which teaching should the nurse provide?', '[{"id": "a", "text": "\"Shake the vial well before each injection there.\""}, {"id": "b", "text": "\"Rotate sites only when the skin becomes irritated.\""}, {"id": "c", "text": "\"Rotate injection sites to prevent lipodystrophy.\""}, {"id": "d", "text": "\"Use the same spot to keep absorption consistent.\""}]'::jsonb, '["c"]', 'Injection sites are rotated to prevent lipodystrophy. Using the same spot, or rotating only after irritation appears, does not follow this rule.'),
  ('storage', 47, 'A client asks where in the home refrigerator to keep insulin. Which instruction by the nurse is correct?', '[{"id": "a", "text": "\"Keep it in the freezer compartment until needed.\""}, {"id": "b", "text": "\"Keep it against the back wall where it stays coldest.\""}, {"id": "c", "text": "\"Keep it directly in front of the cooling vent.\""}, {"id": "d", "text": "\"Keep it away from the back wall and the cooling vent.\""}]'::jsonb, '["d"]', 'Insulin is kept away from the freezer compartment, back wall, and cooling vent and must never be frozen. These areas risk freezing the insulin.'),
  ('storage', 48, 'A nurse opens a new vial of insulin on October 1. No special manufacturer or facility instructions apply. Which label is correct?', '[{"id": "a", "text": "Opened 10/1; discard at printed expiration"}, {"id": "b", "text": "Opened 10/1; discard 10/15"}, {"id": "c", "text": "Opened 10/1; discard 10/29"}, {"id": "d", "text": "Opened 10/1; discard 11/1"}]'::jsonb, '["c"]', 'Most opened insulin is discarded after 28 days, so a vial opened 10/1 is discarded 10/29, and the label must include both dates. The printed expiration date applies to unopened insulin.'),
  ('storage', 49, 'After gently rolling a vial of NPH insulin, a nurse notices white clumps that do not disperse. What should the nurse do?', '[{"id": "a", "text": "Shake the vial to break up the clumps"}, {"id": "b", "text": "Roll the vial harder until the clumps dissolve"}, {"id": "c", "text": "Discard the vial and use a new one"}, {"id": "d", "text": "Draw insulin from around the clumps"}]'::jsonb, '["c"]', 'Insulin with clumps, particles, or crystals is not used; it is discarded and a new vial is used. Shaking insulin is never appropriate.'),
  ('storage', 50, 'A nurse has taught a client how to prepare refrigerated insulin. Which client statement shows correct understanding?', '[{"id": "a", "text": "\"I''ll shake the vial under warm running water.\""}, {"id": "b", "text": "\"I''ll warm the vial in the microwave for a few seconds.\""}, {"id": "c", "text": "\"I''ll roll the cold vial gently between my palms first.\""}, {"id": "d", "text": "\"I''ll set the vial on my car dashboard in the sun.\""}]'::jsonb, '["c"]', 'Refrigerated insulin can be gently rolled in the palms or allowed to reach room temperature to reduce injection discomfort. Microwaving, sunlight, and shaking are never used.'),
  ('mixing', 1, 'A client who receives Regular and NPH insulin each morning asks why the nurse draws both insulins into one syringe. Which response by the nurse is best?', '[{"id": "a", "text": "It makes the long-acting insulin start working faster."}, {"id": "b", "text": "It lets you receive one injection instead of two."}, {"id": "c", "text": "It keeps the Regular insulin from reaching its peak."}, {"id": "d", "text": "It is safer than mixing the insulins in the vial."}]'::jsonb, '["b"]', 'Insulin mixing draws two insulin types into one syringe so the client receives one injection instead of two, for comfort and convenience. Long-acting insulin is never mixed, so mixing does not affect it.'),
  ('mixing', 2, 'A nurse is caring for a client who has two insulins due at the same time. Which principle should guide the nurse''s decision to mix them in one syringe?', '[{"id": "a", "text": "Any two insulins due at the same time may be mixed."}, {"id": "b", "text": "Insulins may be mixed whenever the client asks for fewer shots."}, {"id": "c", "text": "Mix only when ordered and only if the types are safe to mix."}, {"id": "d", "text": "Mix only when the client''s blood glucose is above 200 mg/dL."}]'::jsonb, '["c"]', 'Insulin should be mixed only when ordered and only if the insulin types are safe to mix. Long-acting insulin, for example, must never be mixed with any other insulin even if due at the same time.'),
  ('mixing', 3, 'A nurse is reviewing insulin prescriptions for a client. Which combination of insulins may be safely drawn into the same syringe?', '[{"id": "a", "text": "Glargine and Regular"}, {"id": "b", "text": "Detemir and NPH"}, {"id": "c", "text": "Glargine and NPH"}, {"id": "d", "text": "Regular and NPH"}]'::jsonb, '["d"]', 'Regular (R) insulin can be mixed with NPH (N) insulin, the classic mixing combination. Long-acting insulins such as glargine and detemir cannot be mixed with any other insulin.'),
  ('mixing', 4, 'A nursing student asks why insulin glargine cannot be combined with other insulin in one syringe. Which explanation by the nurse is correct?', '[{"id": "a", "text": "Mixing changes the pH and alters its absorption profile."}, {"id": "b", "text": "Glargine is cloudy and would contaminate clear insulin."}, {"id": "c", "text": "Mixing causes glargine to peak within 15 minutes."}, {"id": "d", "text": "Glargine may only be given by the intravenous route."}]'::jsonb, '["a"]', 'Long-acting insulin cannot be mixed with any other insulin because mixing changes the pH and alters the absorption profile. Contamination by cloudy insulin is the concern with NPH entering the Regular vial, not with glargine.'),
  ('mixing', 5, 'A charge nurse observes a new nurse preparing insulin for several clients. Which action by the new nurse requires correction?', '[{"id": "a", "text": "Injects air into the NPH vial before the Regular vial"}, {"id": "b", "text": "Draws up glargine and Regular insulin in the same syringe"}, {"id": "c", "text": "Draws up the Regular insulin before the NPH insulin"}, {"id": "d", "text": "Checks a fingerstick glucose before using a sliding scale"}]'::jsonb, '["b"]', 'Long-acting insulin such as glargine cannot be mixed with any other insulin, so drawing it with Regular insulin requires correction. Injecting air into NPH first and drawing Regular before NPH follow the NR-RN sequence.'),
  ('mixing', 6, 'A nurse is teaching a client how to prepare insulin at home. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I draw up the clear insulin before the cloudy insulin."}, {"id": "b", "text": "I put air into the NPH bottle before the Regular bottle."}, {"id": "c", "text": "I can mix my Lantus with my Regular to save a shot."}, {"id": "d", "text": "I give my mixed insulin when my meal is available."}]'::jsonb, '["c"]', 'Long-acting insulin such as Lantus should never be mixed with any other insulin. Drawing clear before cloudy and injecting air into the NPH vial first are correct.'),
  ('mixing', 7, 'A client has a sliding scale insulin prescription before breakfast, with the dose to be mixed in one syringe. What is the nurse''s first action?', '[{"id": "a", "text": "Inject air into the NPH insulin vial"}, {"id": "b", "text": "Draw up the Regular insulin dose"}, {"id": "c", "text": "Give the mixed dose with the meal tray"}, {"id": "d", "text": "Check the client''s fingerstick blood glucose"}]'::jsonb, '["d"]', 'The first step of the sliding scale protocol is to check blood glucose with a fingerstick glucose meter, then determine the dose from the sliding scale chart. Injecting air into the NPH vial is the first step of drawing up insulin, which comes after the dose is known.'),
  ('mixing', 8, 'A client on a sliding scale insulin protocol asks why the insulin dose is different from day to day. Which response by the nurse is best?', '[{"id": "a", "text": "Your dose is matched to your current blood glucose."}, {"id": "b", "text": "Your dose is based on what you ate the day before."}, {"id": "c", "text": "Your dose increases each day to build up your tolerance."}, {"id": "d", "text": "Your dose changes depending on the injection site used."}]'::jsonb, '["a"]', 'A sliding scale ensures the dose is proportional to the current glucose level, so the dose is determined from the blood glucose reading. The dose is not based on the previous day''s intake.'),
  ('mixing', 9, 'While mixing insulin, a nurse inserts a syringe that already contains NPH insulin into the Regular insulin vial. What is the main concern with this error?', '[{"id": "a", "text": "The NPH will lose its normal cloudy look"}, {"id": "b", "text": "NPH may contaminate the Regular vial''s insulin"}, {"id": "c", "text": "The Regular vial will develop a vacuum"}, {"id": "d", "text": "The NPH dose will begin to peak sooner"}]'::jsonb, '["b"]', 'When NPH is drawn before Regular, NPH contaminates the Regular insulin vial and changes its effectiveness, so the vial must be discarded. A vacuum is prevented by injecting air into the vials and is not the concern with this error.'),
  ('mixing', 10, 'A nurse is preparing to mix Regular and NPH insulin in one syringe. What is the nurse''s first step in preparing the syringe?', '[{"id": "a", "text": "Inject air into the Regular insulin vial"}, {"id": "b", "text": "Withdraw the Regular insulin dose"}, {"id": "c", "text": "Inject air into the NPH insulin vial"}, {"id": "d", "text": "Withdraw the NPH insulin dose"}]'::jsonb, '["c"]', 'Following NR-RN, the NPH vial gets air first, then the Regular vial gets air, then Regular is drawn, and NPH is drawn last. Injecting air into the Regular vial is the second step, not the first.'),
  ('mixing', 11, 'A nurse mixing Regular and NPH insulin has just injected air into the NPH vial. What is the nurse''s next step?', '[{"id": "a", "text": "Withdraw the NPH insulin dose"}, {"id": "b", "text": "Withdraw the Regular insulin dose"}, {"id": "c", "text": "Inject more air into the NPH vial"}, {"id": "d", "text": "Inject air into the Regular insulin vial"}]'::jsonb, '["d"]', 'After injecting air into the NPH vial, the nurse injects air into the Regular vial before any insulin is drawn. Withdrawing NPH at this point would skip steps and draw cloudy insulin first.'),
  ('mixing', 12, 'A nurse mixing Regular and NPH insulin has injected air into both vials and the needle remains in the Regular vial. What should the nurse do next?', '[{"id": "a", "text": "Withdraw the Regular dose while the needle stays in the vial"}, {"id": "b", "text": "Remove the needle and withdraw the NPH dose first"}, {"id": "c", "text": "Remove the needle and inject more air into the NPH vial"}, {"id": "d", "text": "Withdraw Regular and inject it into the NPH vial to mix"}]'::jsonb, '["a"]', 'With the syringe still in the Regular vial, the nurse aspirates the Regular dose, drawing clear insulin first. Withdrawing NPH first would reverse the clear-before-cloudy order.'),
  ('mixing', 13, 'A client is prescribed 4 units of Regular and 6 units of NPH insulin. The nurse has injected air into both vials and drawn up 4 units of Regular insulin. What is the nurse''s next action?', '[{"id": "a", "text": "Inject 4 more units of air into the Regular vial"}, {"id": "b", "text": "Insert the needle into the NPH vial and withdraw 6 units"}, {"id": "c", "text": "Inject the Regular insulin into the NPH vial to blend it"}, {"id": "d", "text": "Withdraw 6 more units from the Regular vial to total 10"}]'::jsonb, '["b"]', 'The final step is to insert the syringe into the NPH vial and aspirate the NPH dose, drawing cloudy insulin last. Injecting Regular into the NPH vial would mix insulins inside a vial, which is not okay.'),
  ('mixing', 14, 'Which sequence should the nurse follow when mixing Regular and NPH insulin in one syringe?', '[{"id": "a", "text": "Air into Regular, air into NPH, draw NPH, draw Regular"}, {"id": "b", "text": "Air into NPH, draw NPH, air into Regular, draw Regular"}, {"id": "c", "text": "Air into NPH, air into Regular, draw Regular, draw NPH"}, {"id": "d", "text": "Air into Regular, draw Regular, air into NPH, draw NPH"}]'::jsonb, '["c"]', 'The NR-RN mnemonic means air into NPH first, then air into Regular, then draw Regular, then draw NPH. Drawing NPH before Regular reverses the clear-before-cloudy rule.'),
  ('mixing', 15, 'A nurse educator observes a nurse mixing Regular and NPH insulin. Which action by the nurse requires correction?', '[{"id": "a", "text": "Injects air equal to the NPH dose into the NPH vial"}, {"id": "b", "text": "Injects air equal to the Regular dose into the Regular vial"}, {"id": "c", "text": "Draws the Regular dose while the needle is in the Regular vial"}, {"id": "d", "text": "Withdraws the NPH dose right after injecting air into that vial"}]'::jsonb, '["d"]', 'In step 1, air is injected into the NPH vial and the syringe is removed without drawing fluid; NPH is drawn last. Injecting air equal to each dose into each vial is correct.'),
  ('mixing', 16, 'A client is prescribed 4 units of Regular insulin and 6 units of NPH insulin in one syringe. How much air should the nurse inject into the NPH vial?', '[{"id": "a", "text": "6 units"}, {"id": "b", "text": "4 units"}, {"id": "c", "text": "10 units"}, {"id": "d", "text": "No air"}]'::jsonb, '["a"]', 'Step 1 is to draw 6 units of air and inject it into the NPH vial, matching the 6-unit NPH dose. Four units of air goes into the Regular vial, not the NPH vial.'),
  ('mixing', 17, 'A client is prescribed 8 units of Regular insulin and 14 units of NPH insulin to be mixed. After injecting air into the NPH vial, how much air should the nurse inject into the Regular vial?', '[{"id": "a", "text": "14 units"}, {"id": "b", "text": "8 units"}, {"id": "c", "text": "22 units"}, {"id": "d", "text": "6 units"}]'::jsonb, '["b"]', 'The air injected into the Regular vial equals the Regular dose, just as 4 units of air are used for a 4-unit Regular dose. Fourteen units matches the NPH dose, which was already injected into the NPH vial.'),
  ('mixing', 18, 'A nursing student asks why air is injected into the insulin vials before any insulin is withdrawn. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It mixes the two insulins evenly inside the vial."}, {"id": "b", "text": "It warms the insulin to room temperature."}, {"id": "c", "text": "It prevents a vacuum so insulin is easier to draw."}, {"id": "d", "text": "It removes air bubbles from the syringe barrel."}]'::jsonb, '["c"]', 'Injecting air into the vials first prevents a vacuum, so the insulin is easier to draw into the syringe. Insulins should never be mixed inside the vial.'),
  ('mixing', 19, 'A nurse has injected air into both the NPH and Regular insulin vials. A nursing student asks which insulin will be drawn into the syringe first. Which response is correct?', '[{"id": "a", "text": "NPH, because it is the cloudy insulin"}, {"id": "b", "text": "NPH, because it received air first"}, {"id": "c", "text": "Whichever insulin has the larger dose"}, {"id": "d", "text": "Regular, because it is the clear insulin"}]'::jsonb, '["d"]', 'The rule is clear before cloudy: Regular (clear) insulin is drawn before NPH (cloudy) insulin. NPH receives air first but is drawn last.'),
  ('mixing', 20, 'A nursing student asks why Regular insulin must be drawn up before NPH insulin. Which explanation by the nurse is correct?', '[{"id": "a", "text": "It keeps cloudy NPH from contaminating the Regular vial."}, {"id": "b", "text": "It allows the Regular insulin to last longer than NPH."}, {"id": "c", "text": "It gives the NPH insulin time to warm in the syringe."}, {"id": "d", "text": "It is needed because Regular insulin is the cloudy one."}]'::jsonb, '["a"]', 'Regular insulin is drawn first because it is clear and should not be contaminated with cloudy NPH insulin. Regular is the clear insulin and NPH is the cloudy one.'),
  ('mixing', 21, 'While mixing insulin, a nurse notices that the Regular insulin vial now looks slightly cloudy because NPH entered it. What is the nurse''s best action?', '[{"id": "a", "text": "Roll the vial gently and continue using it"}, {"id": "b", "text": "Do not use the Regular vial for this or future doses"}, {"id": "c", "text": "Shake the vial until the cloudiness clears"}, {"id": "d", "text": "Use it for this dose and then discard the vial"}]'::jsonb, '["b"]', 'If NPH gets into the Regular insulin vial, the Regular insulin is contaminated and should not be used. Regular insulin must stay clear and pure for future doses.'),
  ('mixing', 22, 'A nursing student asks why it is acceptable for Regular and NPH insulin to mix in the syringe but not in the vial. Which response by the nurse is correct?', '[{"id": "a", "text": "NPH insulin turns clear once it is inside a syringe."}, {"id": "b", "text": "The syringe neutralizes the pH of the two insulins."}, {"id": "c", "text": "The syringe mixture is injected right away as one dose."}, {"id": "d", "text": "Mixing in the vial is preferred to mixing in a syringe."}]'::jsonb, '["c"]', 'Mixing in the syringe is acceptable because the mixture is injected immediately as one dose, whereas mixing inside the vial contaminates the whole bottle. Mixing in the vial is never preferred.'),
  ('mixing', 23, 'A charge nurse observes a nurse preparing a dose of Regular and NPH insulin. Which action by the nurse requires correction?', '[{"id": "a", "text": "Draws up the Regular insulin before the NPH insulin"}, {"id": "b", "text": "Injects air into the NPH vial before the Regular vial"}, {"id": "c", "text": "Checks the blood glucose before preparing the dose"}, {"id": "d", "text": "Adds NPH to the Regular vial to premix the two insulins"}]'::jsonb, '["d"]', 'Mixing inside the vial contaminates the whole bottle and is not okay; mixing should occur only in the syringe for immediate use. Drawing Regular before NPH and injecting air into NPH first are correct steps.'),
  ('mixing', 24, 'While preparing a mixed dose, a nurse realizes NPH insulin was drawn into the syringe before the Regular insulin. What should the nurse do?', '[{"id": "a", "text": "Discard the syringe and Regular vial and start over"}, {"id": "b", "text": "Continue, because mixing in the syringe is acceptable"}, {"id": "c", "text": "Discard only the syringe and reuse the Regular vial"}, {"id": "d", "text": "Expel a few units to adjust for the incorrect order"}]'::jsonb, '["a"]', 'If NPH is drawn before Regular, the nurse discards the syringe and the contaminated Regular vial and starts the entire process over with a new syringe and fresh Regular vial. Reusing the Regular vial is unsafe because NPH may have contaminated it.'),
  ('mixing', 25, 'After drawing insulin in the wrong order, a nurse asks why the syringe must be discarded rather than given. Which explanation is correct?', '[{"id": "a", "text": "The mixed dose will now peak only overnight."}, {"id": "b", "text": "The syringe may not hold the exact ordered units."}, {"id": "c", "text": "The NPH in the syringe will no longer be cloudy."}, {"id": "d", "text": "The Regular insulin has become long-acting insulin."}]'::jsonb, '["b"]', 'When NPH is drawn first, some NPH may leave the syringe and enter the Regular vial and some Regular may mix unevenly, so the nurse cannot be sure the syringe contains the exact ordered units. The order of drawing does not change the insulin''s type.'),
  ('mixing', 26, 'A client is prescribed a mixed dose of Regular and NPH insulin before breakfast, which will be served at 0800. At what time should the nurse administer the insulin?', '[{"id": "a", "text": "0600"}, {"id": "b", "text": "1000"}, {"id": "c", "text": "0730"}, {"id": "d", "text": "0900"}]'::jsonb, '["c"]', 'Mixed Regular and NPH insulin is given when the meal is available or about 30 minutes before eating, so 0730 is appropriate. The nurse should not wait 2 hours to feed the client after injection.'),
  ('mixing', 27, 'A client receives mixed Regular and NPH insulin at 0730. Which plan proposed by a nursing student requires correction?', '[{"id": "a", "text": "Check the blood glucose at about 0930"}, {"id": "b", "text": "Check the blood glucose again around 1130 to 1330"}, {"id": "c", "text": "Make sure breakfast is available for the client"}, {"id": "d", "text": "Serve breakfast 2 hours after the insulin is given"}]'::jsonb, '["d"]', 'After mixed insulin, the nurse should not wait 2 hours to feed the client; the insulin is given when the meal is available or about 30 minutes before eating. Checking glucose about 2 hours and again 4-6 hours after injection is correct.'),
  ('mixing', 28, 'A client receives mixed Regular and NPH insulin at 0730. At what time should the nurse check blood glucose to monitor for the Regular insulin peak?', '[{"id": "a", "text": "0930"}, {"id": "b", "text": "0745"}, {"id": "c", "text": "1930"}, {"id": "d", "text": "0730 the next day"}]'::jsonb, '["a"]', 'Blood glucose is checked about 2 hours after injection to monitor for the Regular insulin peak, which is 0930. Checking at 0745 is too soon to capture that peak.'),
  ('mixing', 29, 'A client receives mixed Regular and NPH insulin at 0630. During which period should the nurse recheck blood glucose to monitor for the beginning of the NPH peak?', '[{"id": "a", "text": "0730 to 0830"}, {"id": "b", "text": "1030 to 1230"}, {"id": "c", "text": "1830 to 2030"}, {"id": "d", "text": "0630 the next day"}]'::jsonb, '["b"]', 'Blood glucose is checked again about 4-6 hours after injection to monitor for the beginning of the NPH peak, which is 1030-1230. 0730-0830 is too early; the check about 2 hours after injection monitors the Regular insulin peak, not NPH.'),
  ('mixing', 30, 'A client received mixed Regular and NPH insulin at 0800. At 1030, the nurse recognizes the client is in which period?', '[{"id": "a", "text": "NPH onset only, with no hypoglycemia risk"}, {"id": "b", "text": "After both insulins have stopped working"}, {"id": "c", "text": "First hypoglycemia risk, from Regular insulin"}, {"id": "d", "text": "Second hypoglycemia risk, from NPH insulin"}]'::jsonb, '["c"]', 'The first hypoglycemia risk is around 2-4 hours after injection and matches the Regular insulin peak; 1030 is 2.5 hours after the dose. The second risk, from NPH, occurs around 4-12 hours after injection.'),
  ('mixing', 31, 'A client received mixed Regular and NPH insulin at 0700. At 1700, the client''s hypoglycemia risk is most closely related to which insulin action?', '[{"id": "a", "text": "The Regular insulin peak"}, {"id": "b", "text": "No remaining insulin effect"}, {"id": "c", "text": "A long-acting insulin peak"}, {"id": "d", "text": "The NPH insulin peak"}]'::jsonb, '["d"]', 'The second hypoglycemia risk occurs around 4-12 hours after injection and matches the NPH insulin peak; 1700 is 10 hours after the dose. The Regular insulin peak occurs around 2-4 hours after injection.'),
  ('mixing', 32, 'A client develops low blood glucose 3 hours after receiving a mixed dose of Regular and NPH insulin. The nurse recognizes this timing most closely matches the peak of which insulin?', '[{"id": "a", "text": "Regular insulin"}, {"id": "b", "text": "NPH insulin"}, {"id": "c", "text": "Glargine insulin"}, {"id": "d", "text": "Detemir insulin"}]'::jsonb, '["a"]', 'The first hypoglycemia risk, around 2-4 hours after injection, matches the Regular insulin peak. The NPH-related risk occurs around 4-12 hours after injection.'),
  ('mixing', 33, 'A client is prescribed 7 units of Regular insulin and 15 units of NPH insulin in one syringe. What total dose should the nurse verify in the syringe before administration?', '[{"id": "a", "text": "15 units"}, {"id": "b", "text": "22 units"}, {"id": "c", "text": "8 units"}, {"id": "d", "text": "7 units"}]'::jsonb, '["b"]', 'Total syringe units equal the Regular dose plus the NPH dose, so 7 + 15 = 22 units. Fifteen units is only the NPH portion.'),
  ('mixing', 34, 'A client is prescribed 6 units of Regular and 10 units of NPH insulin. After drawing the Regular insulin, the syringe reads 6 units. What should the syringe read after the NPH is drawn?', '[{"id": "a", "text": "10 units"}, {"id": "b", "text": "4 units"}, {"id": "c", "text": "16 units"}, {"id": "d", "text": "6 units"}]'::jsonb, '["c"]', 'The total in the syringe is the Regular dose plus the NPH dose, 6 + 10 = 16 units, as in the example where 4 units Regular plus 6 units NPH totals 10 units. A reading of 10 units would mean only 4 units of NPH were added.'),
  ('mixing', 35, 'A nursing student is learning the Air-Air-Fluid-Fluid portion of the insulin-mixing mnemonic. Which description of this phrase is correct?', '[{"id": "a", "text": "Draw fluid from one vial, then inject air into the other"}, {"id": "b", "text": "Alternate air and fluid within each vial in turn"}, {"id": "c", "text": "Inject air only into the Regular vial before drawing"}, {"id": "d", "text": "Inject air into both vials before drawing any insulin"}]'::jsonb, '["d"]', 'In NR-RN (Air-Air-Fluid-Fluid), air goes into NPH and then Regular before any insulin is drawn, followed by drawing Regular and then NPH. Air is injected into both vials, not only the Regular vial.'),
  ('mixing', 36, 'A nurse is teaching a client to mix Regular and NPH insulin at home. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I will draw up the cloudy insulin first, then the clear."}, {"id": "b", "text": "I will put air into the NPH bottle before the Regular."}, {"id": "c", "text": "I will keep the needle in the Regular bottle to draw it."}, {"id": "d", "text": "My total dose is my Regular units plus my NPH units."}]'::jsonb, '["a"]', 'The rule is clear before cloudy: Regular is always drawn before NPH. Injecting air into the NPH vial first and keeping the syringe in the Regular vial to draw it are correct.'),
  ('mixing', 37, 'A client asks what benefit there is to mixing Regular and NPH insulin into one injection. Which response by the nurse is correct?', '[{"id": "a", "text": "You will no longer need to check your blood glucose."}, {"id": "b", "text": "You get short-acting and longer-acting insulin at once."}, {"id": "c", "text": "You will have no risk of low blood sugar after the dose."}, {"id": "d", "text": "You can add your long-acting insulin to the same shot."}]'::jsonb, '["b"]', 'Mixing helps the client receive both fast/short-acting and longer-acting insulin at the same time when prescribed. Hypoglycemia risk remains, with monitoring needed at both the Regular and NPH peaks.'),
  ('mixing', 38, 'A client on a sliding scale insulin protocol has a fingerstick blood glucose of 180 mg/dL. What is the nurse''s next action?', '[{"id": "a", "text": "Give the same dose the client received yesterday"}, {"id": "b", "text": "Draw up the NPH insulin before the Regular insulin"}, {"id": "c", "text": "Determine the dose using the sliding scale chart"}, {"id": "d", "text": "Inject air into the Regular insulin vial first"}]'::jsonb, '["c"]', 'After checking blood glucose, the nurse determines the dosage from the sliding scale chart based on the reading. Repeating yesterday''s dose ignores the current glucose level.'),
  ('mixing', 39, 'A nurse educator observes a nurse preparing a mixed dose of Regular and NPH insulin. Which action requires correction?', '[{"id": "a", "text": "Draws the Regular insulin before the NPH insulin"}, {"id": "b", "text": "Inserts the needle into the NPH vial for the last step"}, {"id": "c", "text": "Verifies the total equals the Regular plus NPH dose"}, {"id": "d", "text": "Skips injecting air and begins withdrawing insulin"}]'::jsonb, '["d"]', 'Air is injected into the vials first to prevent a vacuum so the insulin is easier to draw into the syringe. Drawing Regular first and NPH last is correct.'),
  ('mixing', 40, 'A client who mixes insulin at home asks what to do if NPH is accidentally drawn into the syringe before the Regular insulin. Which response by the nurse is correct?', '[{"id": "a", "text": "Throw out the syringe and the Regular bottle, then start over."}, {"id": "b", "text": "Inject the dose anyway, since it all mixes in the syringe."}, {"id": "c", "text": "Throw out the syringe but keep using the Regular bottle."}, {"id": "d", "text": "Squirt the syringe back into the NPH bottle and redraw."}]'::jsonb, '["a"]', 'If NPH is drawn before Regular, the syringe and contaminated Regular vial are discarded and the entire process is started over with a new syringe and fresh Regular vial. The Regular vial cannot be kept because NPH may have contaminated it.'),
  ('mixing', 41, 'A client who takes mixed Regular and NPH insulin at 0700 asks when to watch for a second episode of low blood sugar. Which time range should the nurse teach?', '[{"id": "a", "text": "0715 to 0800"}, {"id": "b", "text": "1100 to 1900"}, {"id": "c", "text": "0900 to 1100"}, {"id": "d", "text": "0700 the next day"}]'::jsonb, '["b"]', 'The second hypoglycemia risk occurs around 4-12 hours after injection, matching the NPH peak, which is 1100-1900. 0900-1100 is 2-4 hours after the dose and reflects the first risk from Regular insulin.'),
  ('mixing', 42, 'At 1000, a nurse is caring for four clients who receive mixed Regular and NPH insulin. Which client is at highest risk for hypoglycemia related to the Regular insulin peak at this time?', '[{"id": "a", "text": "Client who received the mixed dose at 0945"}, {"id": "b", "text": "Client who received the mixed dose at 1830 yesterday"}, {"id": "c", "text": "Client who received the mixed dose at 0700"}, {"id": "d", "text": "Client whose mixed dose is scheduled for 1130"}]'::jsonb, '["c"]', 'The first hypoglycemia risk is around 2-4 hours after injection, matching the Regular insulin peak; a dose at 0700 is 3 hours before 1000. A dose given at 0945 is only 15 minutes old and not yet at the Regular peak.'),
  ('mixing', 43, 'A client has prescriptions for insulin glargine, Regular insulin, and NPH insulin, all due at 0700. How should the nurse prepare the insulins?', '[{"id": "a", "text": "Draw all three insulins into a single syringe"}, {"id": "b", "text": "Mix glargine with Regular; give NPH separately"}, {"id": "c", "text": "Mix glargine with NPH; give Regular separately"}, {"id": "d", "text": "Mix Regular with NPH; give glargine separately"}]'::jsonb, '["d"]', 'Regular and NPH can be mixed in one syringe, but long-acting insulin such as glargine cannot be mixed with any other insulin and must be given separately. Any option combining glargine with another insulin is unsafe.'),
  ('mixing', 44, 'A nurse mixing Regular and NPH insulin has just injected air into the NPH vial. What should the nurse do with the syringe at this point?', '[{"id": "a", "text": "Remove it from the NPH vial without drawing any insulin"}, {"id": "b", "text": "Leave it in the NPH vial and withdraw the NPH dose"}, {"id": "c", "text": "Leave it in the NPH vial and inject the Regular dose"}, {"id": "d", "text": "Remove it and discard it before drawing the Regular"}]'::jsonb, '["a"]', 'After injecting air into the NPH vial, the nurse removes the syringe without drawing fluid, then injects air into the Regular vial. NPH is drawn last, not at this step.'),
  ('mixing', 45, 'A nurse teaches a client who needs both Regular and NPH insulin each morning about mixing them. Which client statement indicates understanding of the benefit?', '[{"id": "a", "text": "Mixing means I will not need to check my sugar."}, {"id": "b", "text": "Mixing means I will have fewer needle sticks."}, {"id": "c", "text": "Mixing means I can add my Lantus to the shot."}, {"id": "d", "text": "Mixing means I can skip my breakfast safely."}]'::jsonb, '["b"]', 'Mixing is done for comfort and convenience and can reduce the number of needle sticks. Lantus must never be mixed with any other insulin.'),
  ('mixing', 46, 'A client who mixes insulin at home asks, ''Can I pour some NPH into my Regular bottle so it is already mixed?'' Which response by the nurse is correct?', '[{"id": "a", "text": "Yes, premixing in the bottle saves time each day."}, {"id": "b", "text": "Yes, as long as you roll the bottle before each use."}, {"id": "c", "text": "No, that contaminates the whole Regular bottle."}, {"id": "d", "text": "No, NPH must be poured into the Lantus bottle instead."}]'::jsonb, '["c"]', 'Mixing inside the vial contaminates the whole bottle, and Regular insulin should stay clear and pure for future doses; mixing belongs in the syringe for immediate use. Lantus can never be mixed with other insulin.'),
  ('mixing', 47, 'A nurse observes a colleague caring for a client with a sliding scale insulin prescription. Which action by the colleague requires correction?', '[{"id": "a", "text": "Checks the fingerstick glucose before choosing a dose"}, {"id": "b", "text": "Uses the glucose reading to find the dose on the chart"}, {"id": "c", "text": "Matches the dose to the current glucose reading"}, {"id": "d", "text": "Draws up a dose before the blood glucose is checked"}]'::jsonb, '["d"]', 'Step 1 of the sliding scale protocol is to check blood glucose first, then determine the dose from the chart. Drawing up a dose before checking glucose skips this step.'),
  ('mixing', 48, 'A nurse reviews teaching with a client who takes mixed Regular and NPH insulin before breakfast. Which client statement indicates a need for further teaching?', '[{"id": "a", "text": "I wait 2 hours after my shot before I eat breakfast."}, {"id": "b", "text": "I take my shot when my meal is ready to eat."}, {"id": "c", "text": "I check my sugar about 2 hours after the shot."}, {"id": "d", "text": "I check my sugar again about 4 to 6 hours later."}]'::jsonb, '["a"]', 'Mixed insulin is given when the meal is available or about 30 minutes before eating, and the client should not wait 2 hours to eat. Checking glucose about 2 hours and again 4-6 hours after the injection is correct.'),
  ('mixing', 49, 'A nursing student asks why blood glucose is checked about 2 hours after a mixed Regular and NPH injection. Which explanation by the nurse is correct?', '[{"id": "a", "text": "To monitor for the beginning of the NPH peak"}, {"id": "b", "text": "To monitor for the Regular insulin peak"}, {"id": "c", "text": "To monitor for the long-acting insulin peak"}, {"id": "d", "text": "To decide whether to serve the client breakfast"}]'::jsonb, '["b"]', 'Blood glucose is checked around 2 hours after injection to monitor for the Regular insulin peak. The beginning of the NPH peak is monitored with a check around 4-6 hours after injection.'),
  ('mixing', 50, 'A nurse is holding two insulin vials, one clear and one cloudy, to prepare a mixed dose. Into which vial should the nurse inject air first?', '[{"id": "a", "text": "The clear vial, because it is drawn first"}, {"id": "b", "text": "Both vials at once, using two syringes"}, {"id": "c", "text": "The cloudy vial, because it is the NPH"}, {"id": "d", "text": "Neither vial, since air is not required"}]'::jsonb, '["c"]', 'In the NR-RN sequence, air is injected into the cloudy NPH vial first, then into the clear Regular vial. The clear Regular insulin is drawn first, but it receives air second.')
  ) AS v(source_key, display_order, stem, options, correct_answer, rationale)
  JOIN _endo_seed_map m USING (source_key)
 CROSS JOIN _endo_seed_config c;

DO $$
DECLARE
  v_bad text;
BEGIN
  SELECT string_agg(format('%s=%s', m.source_key, coalesce(n.cnt, 0)), ', ')
    INTO v_bad
    FROM _endo_seed_map m
    LEFT JOIN (SELECT category, count(*) AS cnt FROM test_questions GROUP BY category) n
      ON n.category = m.category
   WHERE coalesce(n.cnt, 0) <> 50;
  IF v_bad IS NOT NULL THEN
    RAISE EXCEPTION 'Endocrine seed post-check failed (expected 50 per topic): %', v_bad;
  END IF;
END $$;

COMMIT;
